                      <label><span>Mobile</span><input value={leadDetail.mobile||''} onChange={(e)=>setLeadDetail({...leadDetail, mobile:e.target.value})} onBlur={()=>updateLeadInline({ mobile: leadDetail.mobile })} /></label>
