                      <label><span>Owner</span><input value={leadDetail.owner||''} onChange={(e)=>setLeadDetail({...leadDetail, owner:e.target.value})} onBlur={()=>updateLeadInline({ owner: leadDetail.owner })} /></label>
                      <label><span>Stage</span>
