/* ================================================
   GLOBAL RESPONSIVE DESIGN SYSTEM
   TathaGat CAT Exam Preparation Platform
   Apply these rules across ALL pages
   ================================================ */

/* ================================================
   1. BASE RESET & OVERFLOW PREVENTION
   ================================================ */
html, body {
  overflow-x: hidden !important;
  max-width: 100vw;
  -webkit-overflow-scrolling: touch;
}

*, *::before, *::after {
  box-sizing: border-box;
}

/* Prevent horizontal scroll globally */
.student-lms,
.lms-main,
.lms-content,
.mock-test-page,
.reports-container,
.lc-view,
.dashboard-content,
.study-zone-content {
  overflow-x: hidden !important;
  max-width: 100%;
}

/* Long text handling */
h1, h2, h3, h4, h5, h6, p, span, label, a {
  word-wrap: break-word;
  overflow-wrap: break-word;
}

/* ================================================
   2. TYPOGRAPHY SCALE (Mobile-First)
   ================================================ */
@media (max-width: 768px) {
  /* Page Titles: 22-26px */
  .dashboard-header h1,
  .page-header h1,
  .reports-header h1,
  .lc-page-title,
  .mock-test-page .page-header h1,
  .section-header h2,
  h1.page-title {
    font-size: 24px !important;
    line-height: 1.3;
  }

  /* Section Headings: 16-18px - SCOPED to content areas */
  .chart-card h3,
  .upcoming-classes-card h3,
  .course-progress-card h3,
  .exam-title,
  .subject-title,
  .year-title,
  .section-stat-card h4,
  .dashboard-content h2,
  .dashboard-content h3,
  .reports-container h2,
  .reports-container h3,
  .lms-content h2,
  .lms-content h3,
  .mock-test-page h2,
  .mock-test-page h3 {
    font-size: 17px;
    line-height: 1.4;
  }

  /* Body Text: 13-15px - SCOPED to content containers only */
  .course-description,
  .test-description,
  .class-details p,
  .stat-card p,
  .course-card p,
  .test-card p,
  .chart-card p,
  .reports-container p,
  .dashboard-content > p,
  .lms-content p:not(.icon-wrapper p),
  .form-group label,
  .form-label {
    font-size: 14px;
    line-height: 1.5;
  }

  /* Table cells - scoped to data tables */
  .data-table td,
  .data-table th,
  .report-table td,
  .report-table th {
    font-size: 13px;
  }

  /* Small Labels: 11-12px */
  .meta-label,
  .lc-meta-label,
  .stat-info p,
  .notification-time,
  small,
  .badge-sm {
    font-size: 12px !important;
  }
}

/* ================================================
   3. SPACING SYSTEM (Mobile)
   ================================================ */
@media (max-width: 768px) {
  /* Container Padding: 12-16px */
  .lms-content,
  .mock-test-page,
  .reports-container,
  .lc-header,
  .dashboard-content {
    padding: 14px !important;
  }

  /* Card Gap: 10-14px */
  .stats-grid,
  .courses-grid,
  .dashboard-grid,
  .papers-grid,
  .topics-grid,
  .tests-grid {
    gap: 12px !important;
  }

  /* Section Spacing: 18-24px */
  .section-header,
  .dashboard-header,
  .page-header {
    margin-bottom: 20px !important;
  }
}

/* ================================================
   4. CARD STYLES (Mobile Full-Width)
   ================================================ */
@media (max-width: 768px) {
  /* Cards: Full width, 14-16px padding, consistent radius */
  .stat-card,
  .course-card,
  .test-card,
  .chart-card,
  .section-stat-card,
  .lc-card,
  .ns-card,
  .progress-chart-card,
  .upcoming-classes-card,
  .course-progress-card,
  .rank-progress-card {
    width: 100% !important;
    padding: 15px !important;
    border-radius: 12px !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
  }

  /* Shadow consistency */
  .stat-card,
  .course-card,
  .test-card,
  .chart-card {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06) !important;
  }
}

/* ================================================
