  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 500;
  transition: transform 0.3s ease;
  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3);
