  transform: scale(1.05);
}

.course-thumbnail-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  color: white;
  font-size: 2.5rem;
}

.course-details {
  padding: 1.5rem;
}

.price-badge {
  background: linear-gradient(135deg, #059669, #047857);
  color: white;
  padding: 0.3rem 0.8rem;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(5, 150, 105, 0.3);
}

.course-description {
  color: #718096;
  font-size: 0.9rem;
  line-height: 1.5;
  margin: 0.75rem 0 0;
  max-height: 44px;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.course-actions {
  display: flex;
  gap: 0.75rem;
  margin-top: 1rem;
  align-items: stretch;
}

.enroll-btn {
  flex: 1;
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  color: white;
  border: none;
  padding: 0.75rem 1rem;
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 0.9rem;
  transition: all 0.3s ease;
  box-shadow: 0 3px 12px rgba(79, 70, 229, 0.4);
}

.enroll-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 5px 20px rgba(79, 70, 229, 0.5);
}

.preview-btn {
  background: rgba(79, 70, 229, 0.1);
  color: #4f46e5;
  border: 2px solid rgba(79, 70, 229, 0.2);
  padding: 0.75rem;
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: all 0.3s ease;
  min-width: 48px;
}

.preview-btn:hover {
  background: rgba(79, 70, 229, 0.15);
  border-color: rgba(79, 70, 229, 0.3);
  transform: translateY(-2px);
}

/* Preview Modal */
.preview-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, .35);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1200;
  padding: 16px;
}

.preview-sheet {
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  width: 100%;
  max-width: 860px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, .2);
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 48px);
}

.preview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}

.preview-title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  color: #1a202c;
}

.preview-close {
  border: none;
  background: #f5f7fb;
  color: #333;
  border-radius: 8px;
  padding: 6px 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-body {
  padding: 16px;
  overflow-y: auto;
}

.overview-content {
  display: grid;
  gap: 12px;
}

.ov-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: #1a202c;
}

.ov-desc {
  margin: 0;
  color: #4a5568;
  line-height: 1.6;
}

.ov-section {
  margin: 10px 0 0;
}

.ov-section h5 {
  margin: 0 0 6px;
  color: #1f2937;
  font-size: 14px;
  font-weight: 700;
}

.ov-list {
  margin: 0;
  padding: 0 0 0 18px;
}

.ov-list li {
  margin: 4px 0;
  color: #374151;
}

.ov-muted {
  color: #718096;
}

.preview-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid rgba(0, 0, 0, 0.06);
}

.download-btn {
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 10px 14px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.download-btn:disabled {
  opacity: .7;
  cursor: not-allowed;
}

@media (max-width:640px) {
  .preview-sheet {
    max-width: 96%;
    max-height: calc(100vh - 24px);
  }
}

/* Loading States */
.loading-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem 2rem;
  text-align: center;
  color: #718096;
}

.loading-spinner {
  width: 40px;
  height: 40px;
  border: 4px solid rgba(79, 70, 229, 0.1);
  border-left: 4px solid #4f46e5;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 1rem;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

.error-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem 2rem;
  text-align: center;
}

.error-message {
  color: #e53e3e;
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
  font-weight: 500;
}

.retry-btn {
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 600;
  transition: transform 0.3s ease;
}

.retry-btn:hover:not(:disabled) {
  transform: translateY(-2px);
}

.retry-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem 2rem;
  text-align: center;
  color: #718096;
}

.empty-icon {
  font-size: 3rem;
  margin-bottom: 1rem;
  color: #cbd5e0;
}

.empty-state h3 {
  margin: 0 0 0.5rem 0;
  font-size: 1.3rem;
  color: #4a5568;
}

.empty-state p {
  margin: 0;
  font-size: 1rem;
}

/* Calendar Styles */
.classes-calendar {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  margin-bottom: 2rem;
}

.calendar-header h3 {
  margin: 0 0 1.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1rem;
}

.calendar-day {
  text-align: center;
  padding: 1rem;
  border-radius: 12px;
  background: rgba(102, 126, 234, 0.05);
  border: 1px solid rgba(102, 126, 234, 0.1);
}

.calendar-day h4 {
  margin: 0 0 0.5rem 0;
  color: #4a5568;
  font-size: 0.85rem;
  font-weight: 500;
}

.day-number {
  font-size: 1.2rem;
  font-weight: 600;
  color: #1a202c;
  margin-bottom: 0.5rem;
}

.class-event {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  padding: 0.3rem 0.5rem;
  border-radius: 6px;
  font-size: 0.7rem;
}

.event-time {
  display: block;
  opacity: 0.8;
}

.event-title {
  display: block;
  font-weight: 500;
}

/* Sessions List */
.upcoming-sessions {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.upcoming-sessions h3 {
  margin: 0 0 1.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.sessions-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.session-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  background: rgba(102, 126, 234, 0.05);
  border-radius: 12px;
  border-left: 4px solid #667eea;
}

.session-info h4 {
  margin: 0 0 0.3rem 0;
  color: #1a202c;
  font-weight: 600;
}

.session-info p {
  margin: 0 0 0.5rem 0;
  color: #718096;
  font-size: 0.9rem;
}

.session-meta {
  display: flex;
  gap: 1rem;
  font-size: 0.8rem;
  color: #718096;
}

.session-meta span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.join-session-btn {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border: none;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 500;
  transition: transform 0.3s ease;
}

.join-session-btn:hover {
  transform: translateY(-2px);
}

/* Tests Grid */
.tests-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.test-subject-card {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  transition: transform 0.3s ease;
}

.test-subject-card:hover {
  transform: translateY(-4px);
}

.test-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}

.test-header h3 {
  margin: 0;
  color: #1a202c;
  font-weight: 600;
}

.accuracy-badge {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
  padding: 0.3rem 0.8rem;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 500;
}

.test-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.stat {
  text-align: center;
}

.stat-number {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  color: #1a202c;
}

.stat-label {
  display: block;
  font-size: 0.8rem;
  color: #718096;
  margin-top: 0.2rem;
}

.start-test-btn {
  width: 100%;
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 500;
  transition: transform 0.3s ease;
}

.start-test-btn:hover {
  transform: translateY(-2px);
}

/* Mock Test Banner */
.mock-test-banner {
  background: linear-gradient(135deg, #667eea, #764ba2);
  border-radius: 16px;
  padding: 2rem;
  margin-bottom: 2rem;
  color: white;
  text-align: center;
}

.banner-content h3 {
  font-size: 1.5rem;
  margin: 0 0 0.5rem 0;
}

.banner-content p {
  margin: 0 0 1.5rem 0;
  opacity: 0.9;
}

.banner-cta {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: 2px solid rgba(255, 255, 255, 0.3);
  padding: 0.75rem 1.5rem;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 500;
  transition: all 0.3s ease;
}

.banner-cta:hover {
  background: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}

/* Table Styles */
.mock-test-history {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.mock-test-history h3 {
  margin: 0 0 1.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.history-table {
  width: 100%;
}

.table-header,
.table-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 1rem;
  padding: 1rem;
  align-items: center;
}

.table-header {
  background: rgba(102, 126, 234, 0.1);
  border-radius: 8px;
  font-weight: 600;
  color: #4a5568;
  margin-bottom: 0.5rem;
}

.table-row {
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
  transition: background 0.3s ease;
}

.table-row:hover {
  background: rgba(102, 126, 234, 0.05);
}

.view-btn {
  background: none;
  border: 1px solid #667eea;
  color: #667eea;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.85rem;
  transition: all 0.3s ease;
}

.view-btn:hover {
  background: #667eea;
  color: white;
}

/* Analysis Charts */
.analysis-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.5rem;
}

.performance-chart,
.subject-wise-analysis,
.rank-progress {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.performance-chart h3,
.subject-wise-analysis h3,
.rank-progress h3 {
  margin: 0 0 1.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.rank-stats {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.rank-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  background: rgba(102, 126, 234, 0.05);
  border-radius: 12px;
}

.rank-label {
  color: #718096;
  font-size: 0.9rem;
}

.rank-value {
  font-weight: 600;
  color: #1a202c;
  font-size: 1.1rem;
}

.rank-value.improvement {
  color: #10b981;
}

/* Forum Styles */
.forum-stats {
  display: flex;
  gap: 2rem;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
}

.stat-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: #4a5568;
  font-weight: 500;
}

.recent-discussions {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.recent-discussions h3 {
  margin: 0 0 1.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.discussions-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.discussion-card {
  padding: 1.5rem;
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 12px;
  transition: all 0.3s ease;
}

.discussion-card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  transform: translateY(-2px);
}

.discussion-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.5rem;
}

.discussion-header h4 {
  margin: 0;
  color: #1a202c;
  font-weight: 600;
}

.subject-tag {
  background: #667eea;
  color: white;
  padding: 0.2rem 0.6rem;
  border-radius: 12px;
  font-size: 0.7rem;
}

.discussion-meta {
  color: #718096;
  font-size: 0.85rem;
  margin-bottom: 1rem;
}

.discussion-meta span {
  margin-right: 1rem;
}

.discussion-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.85rem;
  color: #718096;
}

.discussion-actions span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.reply-btn {
  background: none;
  border: 1px solid #667eea;
  color: #667eea;
  padding: 0.3rem 0.8rem;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.8rem;
  transition: all 0.3s ease;
}

.reply-btn:hover {
  background: #667eea;
  color: white;
}

/* Materials Grid */
.materials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
}

.material-card {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: transform 0.3s ease;
}

.material-card:hover {
  transform: translateY(-4px);
}

.material-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, #667eea, #764ba2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.3rem;
}

.material-info {
  flex: 1;
}

.material-info h4 {
  margin: 0 0 0.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.material-meta {
  display: flex;
  gap: 1rem;
  font-size: 0.8rem;
  color: #718096;
}

.material-actions {
  display: flex;
  gap: 0.5rem;
}

.download-btn,
.share-btn {
  background: none;
  border: 1px solid #667eea;
  color: #667eea;
  padding: 0.5rem;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.download-btn:hover,
.share-btn:hover {
  background: #667eea;
  color: white;
}

/* Schedule Styles */
.schedule-calendar {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.calendar-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.calendar-controls h3 {
  margin: 0;
  color: #1a202c;
  font-weight: 600;
}

.nav-btn {
  background: none;
  border: 1px solid #667eea;
  color: #667eea;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.nav-btn:hover {
  background: #667eea;
  color: white;
}

.weekly-schedule {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1rem;
}

.schedule-day {
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 12px;
  padding: 1rem;
  min-height: 120px;
}

.day-header {
  text-align: center;
  margin-bottom: 1rem;
  border-bottom: 1px solid rgba(0, 0, 0, 0.1);
  padding-bottom: 0.5rem;
}

.day-header h4 {
  margin: 0 0 0.3rem 0;
  color: #4a5568;
  font-size: 0.9rem;
  font-weight: 500;
}

.date {
  font-size: 1.2rem;
  font-weight: 600;
  color: #1a202c;
}

.day-events {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.event {
  padding: 0.5rem;
  border-radius: 6px;
  font-size: 0.75rem;
}

.event-class {
  background: rgba(102, 126, 234, 0.1);
  border-left: 3px solid #667eea;
}

.event-test {
  background: rgba(239, 68, 68, 0.1);
  border-left: 3px solid #ef4444;
}

.event-practice {
  background: rgba(16, 185, 129, 0.1);
  border-left: 3px solid #10b981;
}

.event-doubt {
  background: rgba(245, 158, 11, 0.1);
  border-left: 3px solid #f59e0b;
}

.event-time {
  display: block;
  font-weight: 500;
  opacity: 0.8;
}

.event-title {
  display: block;
  font-weight: 600;
}

/* Announcements */
.announcements-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.announcement-card {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  transition: transform 0.3s ease;
}

.announcement-card:hover {
  transform: translateY(-2px);
}

.announcement-card.unread {
  border-left: 4px solid #667eea;
  background: rgba(102, 126, 234, 0.02);
}

.announcement-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.5rem;
}

.announcement-header h3 {
  margin: 0;
  color: #1a202c;
  font-weight: 600;
}

.announcement-date {
  color: #718096;
  font-size: 0.85rem;
}

.announcement-card p {
  color: #4a5568;
  margin: 0 0 1rem 0;
  line-height: 1.6;
}

.announcement-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.read-more-btn {
  background: none;
  border: 1px solid #667eea;
  color: #667eea;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.85rem;
  transition: all 0.3s ease;
}

.read-more-btn:hover {
  background: #667eea;
  color: white;
}

.unread-indicator {
  background: #ef4444;
  color: white;
  padding: 0.2rem 0.6rem;
  border-radius: 12px;
  font-size: 0.7rem;
  font-weight: 500;
}

/* Profile Styles */
.profile-grid {
  display: grid;
  grid-template-columns: 1fr 2fr 1fr;
  gap: 1.5rem;
}

.profile-card,
.profile-form,
.preferences-card {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.profile-avatar {
  text-align: center;
  margin-bottom: 1rem;
}

.avatar-placeholder {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, #667eea, #764ba2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 2rem;
  margin: 0 auto 1rem auto;
}

.change-avatar-btn {
  background: none;
  border: 1px solid #667eea;
  color: #667eea;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.85rem;
  transition: all 0.3s ease;
}

.change-avatar-btn:hover {
  background: #667eea;
  color: white;
}

.profile-info {
  text-align: center;
}

.profile-info h3 {
  margin: 0 0 0.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.profile-info p {
  margin: 0 0 1.5rem 0;
  color: #718096;
}

.profile-stats {
  display: flex;
  justify-content: space-around;
  gap: 1rem;
}

.profile-form h3,
.preferences-card h3 {
  margin: 0 0 1.5rem 0;
  color: #1a202c;
  font-weight: 600;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
}

.form-group label {
  margin-bottom: 0.5rem;
  color: #4a5568;
  font-weight: 500;
  font-size: 0.9rem;
}

.form-group input,
.form-group select {
  padding: 0.75rem;
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.8);
  font-size: 0.9rem;
  outline: none;
  transition: all 0.3s ease;
}

.form-group input:focus,
.form-group select:focus {
  border-color: #667eea;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

/* Preferences */
.preferences-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.preference-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  background: rgba(102, 126, 234, 0.05);
  border-radius: 12px;
}

/* Toggle Switch */
.toggle {
  position: relative;
  display: inline-block;
  width: 50px;
  height: 24px;
}

.toggle input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: .4s;
  border-radius: 24px;
}

.slider:before {
  position: absolute;
  content: "";
  height: 18px;
  width: 18px;
  left: 3px;
  bottom: 3px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}

input:checked+.slider {
  background: linear-gradient(135deg, #667eea, #764ba2);
}

input:checked+.slider:before {
  transform: translateX(26px);
}

/* Logout Card in Profile */
.logout-card {
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);
  margin-top: 1.5rem;
  text-align: center;
}

.logout-profile-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  background: linear-gradient(135deg, #ef4444, #dc2626);
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  width: 100%;
  max-width: 300px;
}

.logout-profile-btn:hover {
  background: linear-gradient(135deg, #dc2626, #b91c1c);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(239, 68, 68, 0.3);
}

.logout-profile-btn svg {
  font-size: 1.1rem;
}

/* View Toggle */
.view-toggle {
  display: flex;
  gap: 0.5rem;
}

.toggle-btn {
  padding: 0.5rem 1rem;
  border: 1px solid rgba(102, 126, 234, 0.3);
  background: transparent;
  color: #667eea;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.toggle-btn:hover,
.toggle-btn.active {
  background: #667eea;
  color: white;
}

/* Responsive Design */
@media (max-width: 1024px) {
  .lms-main {
    margin-left: 0;
  }

  .lms-sidebar {
    transform: translateX(-100%);
  }

  .menu-toggle {
    display: block;
  }

  .search-box input {
    width: 200px;
  }

  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .analysis-grid {
    grid-template-columns: 1fr;
  }

  .profile-grid {
    grid-template-columns: 1fr;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .weekly-schedule {
    grid-template-columns: repeat(3, 1fr);
  }

  .courses-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .course-thumbnail {
    height: 150px;
  }
}

@media (max-width: 768px) {
  .lms-content {
    padding: 1rem;
    width: 100%;
    box-sizing: border-box;
  }

  .lms-header {
    padding: 0.75rem 1rem;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  .header-left {
    flex: 0 0 auto;
    min-width: 0;
    justify-content: flex-start;
  }

  .menu-toggle {
    margin-right: auto;
  }

  .close-sidebar {
    display: block;
  }

  .search-box {
    display: none !important;
  }

  .header-right {
    gap: 0.5rem;
  }

  .dashboard-header h1 {
    font-size: 1.5rem;
    word-wrap: break-word;
  }

  .stats-grid {
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
  }

  .stat-card {
    padding: 1rem;
  }

  .stat-icon {
    width: 40px;
    height: 40px;
    font-size: 1.1rem;
  }

  .stat-info h3 {
    font-size: 1.4rem;
  }

  .courses-grid {
    grid-template-columns: 1fr;
  }

  .course-thumbnail {
    height: 140px;
  }

  .course-actions {
    flex-direction: column;
    gap: 0.5rem;
  }

  .preview-btn {
    min-width: 100%;
  }

  .tests-grid {
    grid-template-columns: 1fr;
  }

  .materials-grid {
    grid-template-columns: 1fr;
  }

  .calendar-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .weekly-schedule {
    grid-template-columns: 1fr;
  }

  .table-header,
  .table-row {
    grid-template-columns: 1fr 1fr 1fr;
    font-size: 0.8rem;
  }

  .table-header span:nth-child(2),
  .table-row span:nth-child(2),
  .table-header span:nth-child(4),
  .table-row span:nth-child(4) {
    display: none;
  }

  .next-step-container {
    margin: 12px 0 20px 0;
  }

  .next-step-container .ns-card {
    max-width: 100%;
  }
}

@media (max-width: 480px) {
  .lms-content {
    padding: 0.75rem;
  }

  .dashboard-header {
    margin-bottom: 1rem;
  }

  .dashboard-header h1 {
    font-size: 1.35rem;
    line-height: 1.3;
  }

  .dashboard-header p {
    font-size: 0.9rem;
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.75rem;
  }

  .section-header h2 {
    font-size: 1.3rem;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 0.5rem;
  }

  .stat-card {
    flex-direction: row;
    text-align: left;
    padding: 0.875rem;
  }

  .stat-icon {
    width: 36px;
    height: 36px;
    font-size: 1rem;
  }

  .stat-info h3 {
    font-size: 1.25rem;
  }

  .stat-info p {
    font-size: 0.8rem;
  }

  .filter-buttons {
    flex-wrap: wrap;
    width: 100%;
  }

  .filter-btn {
    flex: 1;
    min-width: fit-content;
    text-align: center;
    padding: 0.4rem 0.75rem;
    font-size: 0.85rem;
  }

  .forum-stats {
    flex-direction: column;
    gap: 1rem;
  }

  .discussion-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .discussion-actions {
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  .material-card {
    flex-direction: column;
    text-align: center;
  }

  .material-meta {
    justify-content: center;
  }

  .course-card {
    padding: 0;
    border-radius: 12px;
  }

  .course-details {
    padding: 1rem;
  }

  .course-header h3 {
    font-size: 1rem;
  }

  .enroll-btn {
    padding: 0.65rem 0.875rem;
    font-size: 0.85rem;
  }

  .notifications-dropdown {
    width: calc(100vw - 32px);
    right: -50px;
  }
}

/* Sidebar Overlay for Mobile */
.sidebar-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: rgba(0, 0, 0, 0.5);
  z-index: 999;
  display: none;
}

@media (max-width: 1024px) {
  .sidebar-overlay {
    display: block;
  }
}

/* Smooth Transitions */
* {
  box-sizing: border-box;
}

.student-lms * {
  transition: all 0.3s ease;
}

/* Scrollbar Styling */
.lms-sidebar::-webkit-scrollbar {
  width: 6px;
}

.lms-sidebar::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.1);
}

.lms-sidebar::-webkit-scrollbar-thumb {
  background: rgba(102, 126, 234, 0.3);
  border-radius: 3px;
}

.lms-sidebar::-webkit-scrollbar-thumb:hover {
  background: rgba(102, 126, 234, 0.5);
}

/* Custom Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.lms-content>* {
  animation: fadeIn 0.5s ease;
}

/* Focus States for Accessibility */
button:focus,
input:focus,
select:focus {
  outline: 2px solid #667eea;
  outline-offset: 2px;
}

/* Print Styles */
@media print {

  .lms-sidebar,
  .lms-header {
    display: none;
  }

  .lms-main {
    margin-left: 0;
  }

  .lms-content {
    padding: 0;
  }
}

/* Enrolled Course Specific Styles */
.course-card.enrolled {
  border: 2px solid rgba(16, 185, 129, 0.3);
  background: rgba(16, 185, 129, 0.02);
}

.course-card.enrolled:hover {
  border-color: rgba(16, 185, 129, 0.5);
  transform: translateY(-6px);
}

.enrolled-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
  padding: 0.4rem 0.8rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.3rem;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3);
}

.status-badge {
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 500;
}

.status-badge.enrolled {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
}

.course-progress {
  margin: 1rem 0;
}

.progress-text {
  font-size: 0.85rem;
  color: #059669;
  font-weight: 600;
  margin-top: 0.5rem;
  display: block;
}

.continue-btn.primary {
  background: linear-gradient(135deg, #10b981, #059669);
  box-shadow: 0 3px 12px rgba(16, 185, 129, 0.4);
}

.continue-btn.primary:hover {
  box-shadow: 0 5px 20px rgba(16, 185, 129, 0.5);
}

.info-btn {
  background: rgba(16, 185, 129, 0.1);
  color: #059669;
  border: 2px solid rgba(16, 185, 129, 0.2);
  padding: 0.75rem;
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: all 0.3s ease;
  min-width: 48px;
}

.info-btn:hover {
  background: rgba(16, 185, 129, 0.15);
  border-color: rgba(16, 185, 129, 0.3);
  transform: translateY(-2px);
}

/* Study Materials Styles */
.materials-content {
  background: white;
  border-radius: 20px;
  padding: 2rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

.materials-filters {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.materials-filters select {
  padding: 0.75rem 1rem;
  border: 2px solid #e2e8f0;
  border-radius: 12px;
  background: white;
  font-size: 0.9rem;
  color: #4a5568;
  cursor: pointer;
  transition: all 0.3s ease;
  min-width: 150px;
}

.materials-filters select:focus {
  outline: none;
  border-color: #667eea;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.materials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 1.5rem;
}

.material-card {
  background: white;
  border-radius: 16px;
  padding: 1.5rem;
  border: 2px solid #f1f5f9;
  transition: all 0.3s ease;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  position: relative;
  overflow: hidden;
}

.material-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(135deg, #667eea, #764ba2);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.material-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.15);
  border-color: #e2e8f0;
}

.material-card:hover::before {
  opacity: 1;
}

.material-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, #f0f4ff, #e0e7ff);
  color: #5b21b6;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.material-info {
  flex: 1;
  min-width: 0;
}

.material-info h4 {
  margin: 0 0 0.5rem 0;
  color: #1a202c;
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.3;
}

.material-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.material-meta span {
  font-size: 0.8rem;
  color: #64748b;
  font-weight: 500;
}

.material-type {
  background: linear-gradient(135deg, #ede9fe, #ddd6fe);
  color: #5b21b6;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.material-size {
  background: linear-gradient(135deg, #fef3c7, #fde68a);
  color: #92400e;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
}

.material-downloads {
  background: linear-gradient(135deg, #dcfce7, #bbf7d0);
  color: #166534;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
}

.material-description {
  margin: 0.5rem 0;
  color: #64748b;
  font-size: 0.9rem;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.material-subject {
  margin-top: 0.5rem;
}

.material-subject small {
  background: linear-gradient(135deg, #f1f5f9, #e2e8f0);
  color: #475569;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 500;
}

.material-actions {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex-shrink: 0;
}

.download-btn,
.share-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 1rem;
}

.download-btn {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
}

.download-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.4);
}

.download-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
  transform: none;
}

.share-btn {
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
}

.share-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(59, 130, 246, 0.4);
}

.download-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top: 2px solid white;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

.loading-materials {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3rem;
  grid-column: 1 / -1;
  text-align: center;
}

.loading-materials .loading-spinner {
  width: 40px;
  height: 40px;
  border: 4px solid #e2e8f0;
  border-top: 4px solid #667eea;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 1rem;
}

.loading-materials p {
  color: #64748b;
  font-size: 1rem;
  margin: 0;
}

.no-materials {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3rem;
  grid-column: 1 / -1;
  text-align: center;
  color: #64748b;
}

.no-materials svg {
  margin-bottom: 1rem;
  opacity: 0.5;
}

.no-materials h3 {
  margin: 0 0 0.5rem 0;
  color: #374151;
  font-weight: 600;
}

.no-materials p {
  margin: 0;
  font-size: 0.9rem;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

/* Announcements Styles */
.announcements-content {
  background: white;
  border-radius: 20px;
  padding: 2rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

.announcement-filters {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 0.5rem 1rem;
  border: 2px solid #e2e8f0;
  background: white;
  color: #64748b;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.9rem;
  font-weight: 500;
}

.filter-btn.active,
.filter-btn:hover {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border-color: #667eea;
}

.announcements-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.announcement-card {
  background: white;
  border: 2px solid #f1f5f9;
  border-radius: 16px;
  padding: 1.5rem;
  transition: all 0.3s ease;
  cursor: pointer;
}

.announcement-card:hover {
  border-color: #e2e8f0;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
  transform: translateY(-2px);
}

.announcement-card.unread {
  border-color: #667eea;
  background: linear-gradient(135deg, #f8faff, #f0f4ff);
}

.announcement-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 1rem;
  gap: 1rem;
}

.announcement-header h3 {
  margin: 0;
  color: #1a202c;
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.3;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pin-badge {
