/* Material Viewer Modal Styles */
.material-viewer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2000;
  padding: 1rem;
}

.material-viewer-sheet {
  background: white;
  border-radius: 12px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  width: 100%;
  max-width: 1000px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.material-viewer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem;
  border-bottom: 1px solid rgba(0, 0, 0, 0.1);
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.material-viewer-title {
  margin: 0;
  color: white;
  font-size: 1.3rem;
  font-weight: 600;
}

.material-viewer-close {
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s ease;
}

.material-viewer-close:hover {
  transform: scale(1.1);
}

.material-viewer-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem;
}

.material-viewer-loading,
.material-viewer-error {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 400px;
  font-size: 1rem;
  color: #666;
}

.material-viewer-error {
  color: #d32f2f;
}

.material-viewer-content {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 2rem;
}

.material-details {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding-right: 1rem;
  border-right: 1px solid rgba(0, 0, 0, 0.1);
}

.detail-section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.detail-section label {
  font-weight: 600;
  color: #333;
  font-size: 0.9rem;
}

.detail-section span,
.detail-section p {
  color: #666;
  font-size: 0.95rem;
  word-break: break-word;
}

.detail-section.full-width {
  grid-column: 1 / -1;
  border-right: none;
  padding-right: 0;
}

.material-pdf-container {
  flex: 1;
}

.material-pdf-viewer {
  width: 100%;
  height: 500px;
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 8px;
}

.material-viewer-actions {
  display: flex;
  justify-content: flex-end;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-top: 1px solid rgba(0, 0, 0, 0.1);
  background: #f8f9fa;
}

.material-viewer-actions .download-btn,
.material-viewer-actions .close-btn {
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s ease;
}

.material-viewer-actions .download-btn {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
}

.material-viewer-actions .download-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
}

.material-viewer-actions .close-btn {
  background: #e5e7eb;
  color: #333;
}

.material-viewer-actions .close-btn:hover {
  background: #d1d5db;
  transform: translateY(-2px);
}

/* View Button Style */
.view-btn {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s ease;
}

.view-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
}

.view-btn:active {
  transform: translateY(0);
}

/* Responsive Material Viewer */
@media (max-width: 768px) {
