import React, { useState } from 'react';
import { FiInfo, FiPlay, FiVideo } from 'react-icons/fi';
import SubjectChip, { StatusChip } from '../../../../components/shared/SubjectChip/SubjectChip';
import './CourseSubjectMatrix.css';

const CourseSubjectMatrix = ({ 
  matrix = [], 
  loading = false, 
  onCourseClick = null,
  onCellAction = null 
}) => {
  const [tooltipData, setTooltipData] = useState(null);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });

  const showTooltip = (event, cellData) => {
    const rect = event.target.getBoundingClientRect();
    setTooltipPosition({
      x: rect.left + rect.width / 2,
      y: rect.top - 10
    });
    setTooltipData(cellData);
  };

  const hideTooltip = () => {
    setTooltipData(null);
  };

  const getStatusInfo = (cell) => {
    const { done, pending, total } = cell;

    if (total === 0) {
      return { status: 'pending', label: 'No Students' };
    }

    if (done === total) {
      return { status: 'done', label: 'Completed' };
    }

    if (done > 0) {
      return { status: 'in-progress', label: 'In Progress' };
    }

    return { status: 'pending', label: 'Not Started' };
  };

  const formatDate = (date) => {
    if (!date) return 'Never';
    return new Date(date).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit'
    });
  };

  const handleCellClick = (courseId, subject, action = 'toggle') => {
    if (onCellAction) {
      onCellAction(courseId, subject, action);
    }
  };

  if (loading) {
    return (
      <div className="matrix-section">
        <div className="matrix-header">
          <h2>Course-Subject Progress Matrix</h2>
          <p>Loading...</p>
        </div>
        <div className="matrix-container">
          <div className="matrix-skeleton">
            {[...Array(5)].map((_, rowIndex) => (
              <div key={rowIndex} className="matrix-skeleton-row">
                <div className="skeleton-course-name"></div>
                {[...Array(4)].map((_, colIndex) => (
                  <div key={colIndex} className="skeleton-cell"></div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (matrix.length === 0) {
    return (
      <div className="matrix-section">
        <div className="matrix-header">
          <h2>Course-Subject Progress Matrix</h2>
          <p>Track progress across all courses and subjects</p>
        </div>
        <div className="matrix-empty">
          <FiInfo size={48} />
          <h3>No Courses Found</h3>
          <p>Add courses to the selected batch to see progress matrix</p>
        </div>
      </div>
    );
  }

  return (
    <div className="matrix-section">
      <div className="matrix-header">
        <h2>Course-Subject Progress Matrix</h2>
        <p>Track progress across all courses and subjects</p>
      </div>

      <div className="matrix-container">
        <div className="matrix-table">
          {/* Header Row */}
          <div className="matrix-header-row">
            <div className="matrix-cell matrix-course-header">Course</div>
            <div className="matrix-cell matrix-subject-header">
              <SubjectChip subject="A" size="small" />
            </div>
            <div className="matrix-cell matrix-subject-header">
              <SubjectChip subject="B" size="small" />
            </div>
            <div className="matrix-cell matrix-subject-header">
              <SubjectChip subject="C" size="small" />
            </div>
            <div className="matrix-cell matrix-subject-header">
              <SubjectChip subject="D" size="small" />
            </div>
          </div>

          {/* Data Rows */}
          {matrix.map((row) => (
            <div key={row.courseId} className="matrix-data-row">
              <div className="matrix-cell matrix-course-cell">
                <div 
                  className="course-name-wrapper"
                  onClick={() => onCourseClick && onCourseClick(row)}
                >
                  <div className="course-name">{row.courseName}</div>
                  <div className="course-meta">
                    Start: <SubjectChip subject={row.startSubject} size="small" />
                  </div>
                </div>
              </div>

              {['A', 'B', 'C', 'D'].map((subject) => {
                const cell = row.subjects[subject];
                const statusInfo = getStatusInfo(cell);

                return (
                  <div 
                    key={subject} 
                    className="matrix-cell matrix-status-cell"
                    onMouseEnter={(e) => showTooltip(e, {
                      course: row.courseName,
                      subject,
                      ...cell,
                      statusInfo
                    })}
                    onMouseLeave={hideTooltip}
                    onClick={() => handleCellClick(row.courseId, subject)}
                  >
                    <StatusChip 
                      status={statusInfo.status}
                      label={`${cell.done}/${cell.total}`}
                      size="small"
                    />

                    {cell.lastSession && (
                      <div className="cell-actions">
                        {cell.lastSession.recordingUrl ? (
                          <button 
                            className="cell-action-btn"
                            title="View Recording"
                            onClick={(e) => {
                              e.stopPropagation();
                              window.open(cell.lastSession.recordingUrl, '_blank');
                            }}
                          >
                            <FiVideo size={12} />
                          </button>
                        ) : (
                          <button 
                            className="cell-action-btn"
                            title="Live Session"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleCellClick(row.courseId, subject, 'schedule');
                            }}
                          >
                            <FiPlay size={12} />
                          </button>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>

      {/* Tooltip */}
      {tooltipData && (
        <div 
          className="matrix-tooltip"
          style={{
            left: tooltipPosition.x,
            top: tooltipPosition.y,
            transform: 'translate(-50%, -100%)'
          }}
        >
          <div className="tooltip-header">
            <strong>{tooltipData.course}</strong> - Subject {tooltipData.subject}
          </div>
          <div className="tooltip-stats">
            <div>Done: {tooltipData.done} students</div>
            <div>Pending: {tooltipData.pending} students</div>
            <div>Total: {tooltipData.total} students</div>
          </div>
          {tooltipData.lastSession && (
            <div className="tooltip-session">
              <div>Last Session: {formatDate(tooltipData.lastSession.startAt)}</div>
              {tooltipData.lastSession.recordingUrl && (
                <div>Recording Available</div>
              )}
            </div>
          )}
          <div className="tooltip-status">
            Status: {tooltipData.statusInfo.label}
          </div>
        </div>
      )}
    </div>
  );
};

export default CourseSubjectMatrix;

frontend/src/components/MyCourses/Mycour.content:
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import "./Mycourse.css";
import { LazyLoadImage } from "react-lazy-load-image-component";
import "react-lazy-load-image-component/src/effects/blur.css";
import axios from "../../utils/axiosConfig";
import CoursePreviewModal from "../CoursePreviewModal/CoursePreviewModal";

const Mycourse = () => {
  const [courses, setCourses] = useState([]);
  const [showAll, setShowAll] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [previewCourse, setPreviewCourse] = useState(null);
  const [enrolledCourses, setEnrolledCourses] = useState([]);

  const navigate = useNavigate();

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        console.log('🔍 Fetching published courses...');
        const response = await axios.get("/api/courses/student/published-courses");
        console.log('✅ Courses response:', response.data);

        if (response.data.success) {
          setCourses(response.data.courses);
        } else {
          console.error('❌ Failed response:', response.data);
          setError("Failed to load courses");
        }
      } catch (err) {
        console.error("❌ Failed to load courses:", err);
        if (err.response?.status === 403) {
          setError("Access denied - please check your authentication");
        } else {
          setError("");
        }
      } finally {
        setLoading(false);
      }
    };

    const fetchEnrolledCourses = async () => {
      const token = localStorage.getItem('authToken');
      if (!token) return;

      try {
        const res = await axios.get('/api/user/student/my-courses');
        if (res.data.success) {
          setEnrolledCourses(res.data.courses.map(c => c.courseId?._id).filter(Boolean));
        }
      } catch (err) {
        console.error('Error fetching enrolled courses:', err);
      }
    };

    fetchCourses();
    fetchEnrolledCourses();
  }, []);

  const isEnrolled = (courseId) => enrolledCourses.includes(courseId);

  const visibleCourses = showAll ? courses : courses.slice(0, 2);

  return (
    <section className="tsp-programs-section">
      <div className="tsp-programs-header">
        <div className='tsp-llf'>
          <h5>Our Courses</h5>
          <h2>Tailored for Your Success</h2>
        </div>
        <div className='tsp-llr'>
          <p>
            At Tathagat, we offer comprehensive and specialized programs designed to help students excel
            in CAT, XAT, SNAP, GMAT, and other management entrance exams. Whether you're a beginner or
            looking for advanced training, we have the perfect program for you!
          </p>
        </div>
      </div>

      {/* ✅ Added navigate on these buttons */}
      <div className="tsp-programs-actions">
        <button onClick={() => navigate("/mock-test")}><i className="fa fa-filter"></i> CAT & OMET</button>
        <button onClick={() => navigate("/Testimonial")}><i className="fa fa-filter"></i> Year</button>
        <button onClick={() => navigate("/ourBlog")}><i className="fa fa-filter"></i> Online/Offline</button>
        <button onClick={() => navigate("/compare")}><i className="fa fa-balance-scale"></i> Course Comparison</button>
      </div>
      {loading ? (
        <p>Loading courses...</p>
      ) : error ? (
        <p style={{ color: 'red' }}>{error}</p>
      ) : courses.length === 0 ? (
        <div className="tsp-no-courses" style={{ textAlign: 'center', padding: '40px', color: '#666' }}>
          <p>No courses available yet. Please check back later!</p>
        </div>
      ) : (
        <div className="tsp-programs-grid">
          {visibleCourses.map((item) => {
            const getImageUrl = (thumbnail) => {
              if (!thumbnail) return '/images/default-course.jpg';
              if (thumbnail.startsWith('http')) return thumbnail;
              if (thumbnail.startsWith('/uploads')) return thumbnail;
              return `/uploads/${thumbnail}`;
            };

            const parseDescription = (desc) => {
              if (!desc) return [];

              let lines = [];
              if (desc.includes('<li>')) {
                const liMatches = desc.match(/<li[^>]*>(.*?)<\/li>/gi) || [];
                lines = liMatches.map(li => 
                  li.replace(/<[^>]+>/g, '')
                    .replace(/&amp;/g, '&')
                    .replace(/&lt;/g, '<')
                    .replace(/&gt;/g, '>')
                    .replace(/&nbsp;/g, ' ')
                    .replace(/&quot;/g, '"')
                    .trim()
                ).filter(l => l);
              } else {
                let text = desc
                  .replace(/<[^>]+>/g, '')
                  .replace(/&amp;/g, '&')
                  .replace(/&lt;/g, '<')
                  .replace(/&gt;/g, '>')
                  .replace(/&nbsp;/g, ' ')
                  .replace(/&quot;/g, '"');

                if (text.includes('✔') || text.includes('✓')) {
                  lines = text.split(/[✔✓]/).filter(l => l.trim());
                } else if (text.includes('\n')) {
                  lines = text.split('\n').filter(l => l.trim());
                } else {
                  const sentences = text.match(/[^.!?]+[.!?]+/g) || [text];
                  lines = sentences.slice(0, 6).map(s => s.trim()).filter(l => l);
                }
              }
              return lines;
            };

            return (
              <div className="tsp-program-card" key={item._id}>
                <div className="tsp-program-image">
                  <LazyLoadImage
                    effect="blur"
                    src={getImageUrl(item.thumbnail)}
                    alt={item.name}
                    onError={(e) => { e.target.src = '/images/default-course.jpg'; }}
                  />
                  <div className="tsp-badge">{item.name}</div>
                </div>

                <div className="tsp-program-content">
                  <h3>{item.name}</h3>
                  <ul className="desc-list">
                    {parseDescription(item.description).map((feat, idx) => (
                      <li key={idx}>✔ {feat.trim()}</li>
                    ))}
                  </ul>

                  <div className="tsp-program-price-row">
                    <div>
                      <h4>₹{item.price}</h4>
                      {item.oldPrice && <del>₹{item.oldPrice}</del>}
                    </div>
                    <div className="tsp-program-buttons">
                      <button onClick={() => setPreviewCourse(item)} className="preview-btn">
                        <i className="fa fa-eye"></i> Preview
                      </button>
                      <button onClick={() => navigate(`/course-purchase/${item._id}`, { state: item })}>Enroll Now</button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {!showAll && courses.length > 2 && (
        <div className="tsp-show-all-button">
          <button onClick={() => setShowAll(true)}>Show All</button>
        </div>
      )}

      {previewCourse && (
        <CoursePreviewModal
          course={previewCourse}
          onClose={() => setPreviewCourse(null)}
          isEnrolled={isEnrolled(previewCourse._id)}
        />
      )}
    </section>
  );
};

export default Mycourse;

