import React, { useState } from "react";
import "./Cat.css";
import { Bar } from "react-chartjs-2";
import { useNavigate } from "react-router-dom";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend,
} from "chart.js";
import Mycourse from "../../components/MyCourses/Mycourse";
import student4 from "../../images/image 38.png";

