// Add sample study materials
const addSampleMaterials = async () => {
  try {
    // First, get or create an admin user
    let admin = await Admin.findOne();

    if (!admin) {
      // Create a sample admin if none exists
      admin = new Admin({
        name: 'Sample Admin',
        email: 'admin@sample.com',
        password: 'hashedpassword', // This should be properly hashed
        phoneNumber: '1234567890'
      });
      await admin.save();
      console.log('✅ Sample admin created');
    }

    // Clear existing materials to avoid duplicates
    await StudyMaterial.deleteMany({});
    console.log('🗑️ Cleared existing study materials');

    // Add uploadedBy field to each material
    const materialsWithAdmin = sampleMaterials.map(material => ({
      ...material,
      uploadedBy: admin._id,
      isActive: true,
      createdAt: new Date(),
      updatedAt: new Date()
    }));

    // Insert all materials
    const insertedMaterials = await StudyMaterial.insertMany(materialsWithAdmin);

    console.log(`✅ Successfully added ${insertedMaterials.length} study materials:`);
    insertedMaterials.forEach((material, index) => {
      console.log(`${index + 1}. ${material.title} (${material.subject} - ${material.type})`);
    });

    // Display summary
    const totalMaterials = await StudyMaterial.countDocuments();
    console.log(`\n📊 Total study materials in database: ${totalMaterials}`);

    // Group by subject
    const bySubject = await StudyMaterial.aggregate([
      { $group: { _id: '$subject', count: { $sum: 1 } } },
      { $sort: { count: -1 } }
    ]);

    console.log('\n📚 Materials by subject:');
    bySubject.forEach(subject => {
      console.log(`- ${subject._id}: ${subject.count} materials`);
    });

  } catch (error) {
    console.error('❌ Error adding sample materials:', error);
  }
};

// Main function
const main = async () => {
  await connectDB();
  await addSampleMaterials();

  console.log('\n🎉 Sample study materials added successfully!');
  console.log('You can now view them in the admin panel and student dashboard.');

  process.exit(0);
};

// Run the script
main().catch(error => {
  console.error('❌ Script failed:', error);
  process.exit(1);
});

backend/controllers/TestController.js.content:
const Test = require("../models/course/Test");
const mongoose=require("mongoose")

// ✅ Create Test
const createTest = async (req, res) => {
  try {
    const {
      course,
      subject,
      chapter,
      topic,
      title,
      description,
      duration,
      totalMarks,
      instructions
    } = req.body;

    // ✅ Required field check
    if (!course || !subject || !chapter || !topic || !title) {
      return res.status(400).json({ message: "Missing required fields" });
    }

    const exists = await Test.findOne({ topic, title });
    if (exists) {
      return res.status(400).json({ message: "Test already exists with this title in topic" });
    }

    const test = new Test({
      course,
      subject,
      chapter,
      topic,
      title,
      description,
      duration,
      totalMarks,
      instructions
    });

    await test.save();

    res.status(201).json({ success: true, test });
  } catch (err) {
    console.error("❌ Error creating test:", err.message);
    res.status(500).json({ success: false, message: "Failed to create test", error: err.message });
  }
};


// ✅ Get all tests for a topic


// ✅ Update Test
const updateTest = async (req, res) => {
  try {
    const test = await Test.findByIdAndUpdate(req.params.id, req.body, { new: true });
    res.status(200).json({ success: true, test });
  } catch (err) {
    res.status(500).json({ success: false, message: "Update failed" });
  }
};

// ✅ Delete Test
const deleteTest = async (req, res) => {
  try {
    await Test.findByIdAndDelete(req.params.id);
    res.status(200).json({ success: true, message: "Test deleted" });
  } catch (err) {
    res.status(500).json({ success: false, message: "Delete failed" });
  }
};

const getTestsByTopic = async (req, res) => {
  try {
    const { topicId } = req.params;

    if (!mongoose.Types.ObjectId.isValid(topicId)) {
      return res.status(400).json({ success: false, message: "Invalid topic ID" });
    }

    const tests = await Test.find({ topic: topicId });
    res.status(200).json({ success: true, tests });
  } catch (err) {
    console.error("❌ Test fetch error:", err.message);
    res.status(500).json({ success: false, message: "Failed to fetch tests", error: err.message });
  }
};


module.exports = {
  createTest,
  getTestsByTopic,
  updateTest,
  deleteTest,


};

