  /* ---------- Professional Modal Styles ---------- */

.tg-modal-overlay{
  position: fixed;
  inset: 0;
  background: rgba(9, 12, 56, 0.55);
  backdrop-filter: blur(2px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.tg-modal{
  width: clamp(360px, 92vw, 640px);
  max-height: 90vh;
  overflow: auto;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 24px 70px rgba(11,16,81,0.35);
  position: relative;
  animation: tgModalIn .18s ease-out;
}

@keyframes tgModalIn {
  from { transform: translateY(12px); opacity: .6; }
  to   { transform: translateY(0);    opacity: 1; }
}

.tg-modal-header{
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: linear-gradient(90deg, #0b1051 0%, #192086 100%);
  color: #fff;
  border-radius: 16px 16px 0 0;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.tg-modal-header h3{
  margin: 0;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: .2px;
}

.tg-modal-close{
  position: absolute;
  right: 12px;
  top: 12px;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.35);
  background: rgba(255,255,255,0.1);
  color: #fff;
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: all .2s ease;
}
.tg-modal-close:hover{ background: rgba(255,255,255,0.2); transform: translateY(-1px); }

.tg-form{
  padding: 18px 20px 20px;
}

.tg-form-group{
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

.tg-form-row{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-bottom: 6px;
}

/* Labels */
.tg-form-group label{
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .2px;
  color: #0b1051;
}

/* Inputs & Textarea */
.tg-form-group input,
.tg-form-group textarea{
  width: 100%;
  border: 1.5px solid #e7e9fe;
  background: #fafbff;
  border-radius: 12px;
  padding: 10px 12px;
  font-size: 14px;
  outline: none;
  transition: border-color .2s, box-shadow .2s, background .2s;
}

.tg-form-group textarea{
  min-height: 110px;
  resize: vertical;
}

.tg-form-group input::placeholder,
.tg-form-group textarea::placeholder{
  color: #9aa0c3;
}

.tg-form-group input:focus,
.tg-form-group textarea:focus{
  border-color: #6366f1; /* soft indigo */
  background: #fff;
  box-shadow: 0 0 0 3px rgba(99,102,241,.14);
}

/* Actions */
.tg-form-actions{
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 8px;
}

.tg-btn{
  background: linear-gradient(90deg, #192086 0%, #0b1051 100%);
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 10px 16px;
  font-weight: 800;
  letter-spacing: .2px;
  cursor: pointer;
  box-shadow: 0 6px 18px rgba(11,16,81,0.25);
  transition: transform .08s ease, box-shadow .2s ease, opacity .2s ease;
}

.tg-btn:hover{ box-shadow: 0 10px 22px rgba(11,16,81,0.28); }
.tg-btn:active{ transform: translateY(1px); }

.tg-btn.ghost{
  background: #f3f4ff;
  color: #192086;
  box-shadow: none;
  border: 1px solid #e7e9fe;
}

/* Mobile stacking earlier to avoid overflow */
@media (max-width: 640px){
  .tg-form-row{ grid-template-columns: 1fr; }
  .tg-modal{ width: min(94vw, 520px); }
  .tg-modal-close{ width: 32px; height: 32px; }
}

