  font-size: 14px;
  color: #856404;
}

.agreement-section {
  background: white;
  padding: 25px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  border: 2px solid #e9ecef;
}

.agreement-checkbox {
  display: flex;
  align-items: flex-start;
  gap: 15px;
  cursor: pointer;
  font-size: 14px;
  line-height: 1.5;
  color: #2c3e50;
  position: relative;
}

.agreement-checkbox input[type="checkbox"] {
  display: none;
}

.checkmark {
  width: 20px;
  height: 20px;
  background-color: #fff;
  border: 2px solid #ddd;
  border-radius: 4px;
  flex-shrink: 0;
  margin-top: 2px;
  position: relative;
  transition: all 0.2s ease;
}

.agreement-checkbox:hover .checkmark {
  border-color: #667eea;
}

.agreement-checkbox input[type="checkbox"]:checked + .checkmark {
  background-color: #667eea;
  border-color: #667eea;
}

.agreement-checkbox input[type="checkbox"]:checked + .checkmark::after {
  content: '✓';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: white;
  font-size: 12px;
  font-weight: bold;
}

.start-test-section {
  display: flex;
  justify-content: center;
  padding: 30px 0;
}

.start-test-btn {
  background: linear-gradient(135deg, #28a745 0%, #20c997 100%);
  color: white;
  border: none;
  padding: 15px 40px;
  border-radius: 30px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(40, 167, 69, 0.3);
}

.start-test-btn:hover:not(.disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(40, 167, 69, 0.4);
}

.start-test-btn.disabled {
  background: #6c757d;
  cursor: not-allowed;
  box-shadow: none;
}

.loading-spinner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 300px;
  gap: 20px;
}

.spinner {
  width: 40px;
  height: 40px;
  border: 3px solid #e9ecef;
  border-top: 3px solid #667eea;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.error-message {
  text-align: center;
  background: white;
  padding: 40px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  margin-top: 50px;
}

.error-message h2 {
  color: #dc3545;
  margin: 0 0 15px 0;
}

.error-message p {
  color: #6c757d;
  margin: 0 0 25px 0;
}

.error-message button {
  background: #667eea;
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
}

/* Responsive Design */
@media (max-width: 768px) {
  .instructions-container {
    padding: 15px;
  }

  .instructions-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 15px;
  }

  .instructions-header h1 {
    font-size: 24px;
  }

  .overview-grid {
    grid-template-columns: 1fr;
  }

  .sections-grid {
    grid-template-columns: 1fr;
  }

  .overview-item {
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
  }

  .overview-item div {
    align-items: flex-start;
  }

  .test-overview,
  .sections-overview,
  .test-instructions,
  .agreement-section {
    padding: 20px;
  }

  .start-test-btn {
    width: 100%;
    justify-content: center;
  }
}

@media (max-width: 480px) {
  .instructions-header h1 {
    font-size: 20px;
  }

  .test-overview h2,
  .sections-overview h2,
  .test-instructions h2 {
    font-size: 18px;
  }

  .default-instructions h3 {
    font-size: 15px;
  }

  .agreement-checkbox {
    font-size: 13px;
  }

  .start-test-btn {
    padding: 12px 30px;
    font-size: 15px;
  }
}

backend/routes/Otp.js.content:
const express = require("express");
const { sendOtpEmailUtil, sendOtpPhoneUtil } = require("../utils/SendOtp");
const User = require("../models/UserSchema");
const OTP = require("../models/OtpSchema");
const { authMiddleware, adminAuth } = require("../middleware/authMiddleware");
const jwt = require("jsonwebtoken");
const { sendWelcomeEmail, sendLoginNotificationEmail } = require("../services/authEmailService");

const mongoose=require("mongoose")


const router = express.Router();





router.post("/update-details", authMiddleware, async (req, res) => {
  try {
    console.log("✅ Token Decoded User:", req.user);

    // ✅ Extract userId - handle both id and _id
    const userId = req.user.id || req.user._id;
    if (!userId) {
      console.error("❌ No userId found in token");
      return res.status(400).json({ message: "Invalid token - no user ID found" });
    }

    const { name, email, phoneNumber, city, gender, dob, profilePic } = req.body;

    let user = await User.findById(userId);
    if (!user) {
      console.error("❌ User not found:", userId);
      return res.status(404).json({ message: "User not found" });
    }

    // ✅ Only update fields that are provided
    if (name) user.name = name;
    if (email) user.email = email;
    if (phoneNumber) user.phoneNumber = phoneNumber;
    if (city) user.city = city;
    if (gender) user.gender = gender;
    if (dob) user.dob = dob;
    if (profilePic) user.profilePic = profilePic;

    await user.save();
    console.log("✅ User details updated:", user._id);

    res.json({ message: "User details updated successfully", user, redirectTo: "/exam-category" });
  } catch (error) {
    console.error("❌ Error updating user details:", error);
    res.status(500).json({ message: "Server error", error: error.message });
  }
});


router.post("/save-category", authMiddleware, async (req, res) => {
  try {
    const userId = req.user.id;
    const { category } = req.body;

    const user = await User.findById(userId);
    if (!user) return res.status(404).json({ message: "❌ User not found" });

    user.selectedCategory = category;
    await user.save();

    res.status(200).json({
      message: "✅ Exam category saved successfully",
      redirectTo: `/exam-selection/${category}`
    });
  } catch (error) {
    console.error("❌ Error saving category:", error);
    res.status(500).json({ message: "Server error" });
  }
});




router.post("/save-exam", authMiddleware, async (req, res) => {
  try {
    const userId = req.user.id; // ✅ Get from token
    const { category, exam } = req.body;

    if (!category || !exam) {
      return res.status(400).json({ message: "❌ Category and Exam are required" });
    }

    let user = await User.findById(userId);
    if (!user) {
      return res.status(404).json({ message: "❌ User not found" });
    }

    user.selectedCategory = category;
    user.selectedExam = exam;
    user.isOnboardingComplete = true; // ✅ Mark onboarding as complete
    await user.save();

    res.status(200).json({
      message: "✅ Exam saved successfully",
      redirectTo: "/study-zone"
    });
  } catch (error) {
    console.error("❌ Error saving exam:", error);
    res.status(500).json({ message: "Server error" });
  }
});




router.post("/send-email", async (req, res) => {
  try {
    const { email } = req.body;

    if (!email) {
      return res.status(400).json({ message: "Email is required" });
    }

    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();

    // ✅ Delete Old OTP Before Creating New One
    await OTP.deleteMany({ email });

    let user = await User.findOne({ email });
    if (!user) {
      user = new User({ email, isEmailVerified: false });
      await user.save();
    }

    await OTP.create({ userId: user._id, otpCode });

    await sendOtpEmailUtil(email, otpCode);

    res.status(200).json({ message: "OTP sent successfully" });
  } catch (error) {
    res.status(500).json({ message: "Server Error", error });
  }
});

// Send OTP to Phone
router.post("/send-phone", async (req, res) => {
  try {
    const { phoneNumber } = req.body;

    if (!phoneNumber) {
      return res.status(400).json({ message: "Phone number is required" });
    }

    // **Check if User Exists**
    let user = await User.findOne({ phoneNumber });
    if (!user) {
      user = await User.create({ phoneNumber, isPhoneVerified: false });
    }

    // **Generate OTP**
    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();

    // **Save OTP in Database**
    await OTP.create({ userId: user._id, otpCode });

    // **Send OTP via Fast2SMS**

    await sendOtpPhoneUtil(phoneNumber, otpCode);

    res.status(200).json({ message: "OTP sent successfully to Phone" });
  } catch (error) {
    res.status(500).json({ message: "Server Error", error });
  }
});



router.post("/verify", async (req, res) => {
  try {
    console.log("🔍 Verifying OTP for:", req.body.email); // Debugging
    const { email, otpCode } = req.body;

    if (!otpCode || !email) {
        console.error("❌ Missing OTP or Email");
      return res.status(400).json({ message: "Email and OTP are required" });
    }

    let user = await User.findOne({ email });

    if (!user) {
        console.error("❌ User Not Found:", email);
      return res.status(400).json({ message: "User not found" });
    }

    const otpRecord = await OTP.findOne({ userId: user._id }).sort({ createdAt: -1 });

    if (!otpRecord || otpRecord.otpCode !== otpCode) {
        console.error("❌ Invalid OTP:", otpCode);
      return res.status(400).json({ message: "Invalid or Expired OTP" });
    }
    console.log("✅ OTP Verified Successfully for:", email);

    user.isEmailVerified = true;
    await user.save({ validateBeforeSave: false });

    user = await User.findById(user._id);

    // ✅ Generate JWT Token
    const token = jwt.sign(
        { id: user._id, role: user.role },
        process.env.JWT_SECRET || "default_secret_key", // ✅ Ensure JWT_SECRET is always available
        { expiresIn: "1h" }
      );

    // ✅ Determine Redirect Path - Check if returning user
    let redirectTo = "/user-details";  
    const adminEmails = ["takoria2204@gmail.com", "superadmin@lms.com"];

    if (adminEmails.includes(user.email)) {
      redirectTo = "/admin-dashboard"; 
    } else if (user.role === "subadmin") {
      redirectTo = "/subadmin-dashboard"; 
    } else if (user.isOnboardingComplete) {
      // ✅ Returning user - direct to dashboard (no need to fill details again)
      redirectTo = "/student/dashboard";
    } else {
      // ✅ New user - go to user-details flow
      redirectTo = "/user-details";
    }

    res.status(200).json({
        message: "OTP verified successfully",
        token,  // ✅ Send token in response
        user,
        redirectTo,
    });

    // ✅ Send email notification (async, don't block response)
    if (!user.welcomeEmailSent) {
      // First time signup - send welcome email
      sendWelcomeEmail(user).then(async (sent) => {
        if (sent) {
          await User.findByIdAndUpdate(user._id, { welcomeEmailSent: true });
        }
      }).catch(err => console.log('Welcome email error:', err.message));
    } else {
      // Returning user - send login notification
      sendLoginNotificationEmail(user).catch(err => console.log('Login email error:', err.message));
    }

  } catch (error) {
    console.error("❌ Server Error in OTP Verification:", error);
    res.status(500).json({ message: "Server error", error });
  }
});



