router.post("/send-otp", async (req, res) => {
    try {
      const { phoneNumber } = req.body;

      if (!phoneNumber || phoneNumber.length !== 10) {
        return res.status(400).json({ message: "❌ Valid phone number required!" });
      }

      // ✅ 2️⃣ Check if User Already Exists
      let user = await User.findOne({ phoneNumber });
      if (!user) {
        user = new User({ phoneNumber, isPhoneVerified: false });
        await user.save();
      }

      // ✅ 3️⃣ Generate OTP
      const otpCode = Math.floor(100000 + Math.random() * 900000).toString();

      // ✅ 4️⃣ OTP Database Me Store Karo
      await OTP.create({ userId: user._id, otpCode });

      // ✅ 5️⃣ OTP SMS Ke Through Bhejo
      await sendOtpPhoneUtil(phoneNumber, otpCode);

      res.status(200).json({ message: "✅ OTP sent successfully!" }); // ❌ Don't expose ID

    } catch (error) {
      console.error("❌ Error sending OTP:", error);
      res.status(500).json({ message: "Server error", error });
    }
  });


router.post("/mobileVerify-otp", async (req, res) => {
    try {

      const { phoneNumber, otpCode } = req.body;

      if (!phoneNumber || !otpCode) {
        return res.status(400).json({ message: "❌ Phone number and OTP required!" });
      }

      // ✅ 1️⃣ Check if User Exists
      let user = await User.findOne({ phoneNumber });
      if (!user) {
        return res.status(404).json({ message: "❌ User not found!" });
      }

      // ✅ 2️⃣ Get Latest OTP from Database
      const otpRecord = await OTP.findOne({ userId: user._id }).sort({ createdAt: -1 });

      if (!otpRecord || otpRecord.otpCode !== otpCode) {
        return res.status(400).json({ message: "❌ Invalid or expired OTP!" });
      }

      // ✅ 3️⃣ Mark User as Verified
      user.isPhoneVerified = true;
      await user.save({ validateBeforeSave: false });

      // ✅ 4️⃣ Generate JWT Token
      const token = jwt.sign(
        { id: user._id, role: user.role },
        process.env.JWT_SECRET || "default_secret_key",
        { expiresIn: "1h" }
      );

      // ✅ 5️⃣ Smart Redirect Logic - Check if returning user
      let redirectTo = "/user-details";  
      const adminPhone = ["7015242845", "7015242846"];

      if (adminPhone.includes(user.phoneNumber)) {
        redirectTo = "/admin-dashboard"; 
      } else if (user.role === "subadmin") {
        redirectTo = "/subadmin-dashboard"; 
      } else if (user.isOnboardingComplete) {
        // ✅ Returning user - direct to dashboard (no need to fill details again)
        redirectTo = "/student/dashboard";
      } else {
        // ✅ New user - go to user-details flow
        redirectTo = "/user-details";
      }

      res.status(200).json({
        message: "✅ Mobile number verified successfully!",
        token,
        user,
        redirectTo,
      });

      // ✅ Send email notification (async, don't block response)
      if (user.email) {
        if (!user.welcomeEmailSent) {
          // First time signup - send welcome email
          sendWelcomeEmail(user).then(async (sent) => {
            if (sent) {
              await User.findByIdAndUpdate(user._id, { welcomeEmailSent: true });
            }
          }).catch(err => console.log('Welcome email error:', err.message));
        } else {
          // Returning user - send login notification
          sendLoginNotificationEmail(user).catch(err => console.log('Login email error:', err.message));
        }
      }

    } catch (error) {
      console.error("❌ Error verifying OTP:", error);
      res.status(500).json({ message: "Server error", error });
    }
  });


  router.get("/verify-token", async (req, res) => {
  try {
    const authHeader = req.headers.authorization;

    // ✅ Token Missing
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ message: "❌ Token missing or invalid!" });
    }

    // ✅ Decode Token
    const token = authHeader.split(" ")[1];
    const decoded = jwt.verify(token, process.env.JWT_SECRET || "default_secret_key");

    // ✅ Find User
    const user = await User.findById(decoded.id)

    if (!user) {
      return res.status(404).json({ message: "❌ User not found!" });
    }

    // ✅ Return User + Optional redirect suggestion
    let redirectTo = "/user-details";

    // ✅ Auto-fix: Set isOnboardingComplete for existing users who have all fields filled
    if (!user.isOnboardingComplete && user.name && user.city && user.gender &&
        user.dob && user.selectedCategory && user.selectedExam) {
      user.isOnboardingComplete = true;
      await user.save({ validateBeforeSave: false });
      console.log("✅ Auto-fixed isOnboardingComplete for user:", user._id);
    }

    if (user.isOnboardingComplete) {
      // ✅ Returning user - direct to dashboard
      redirectTo = "/student/dashboard";
    } else {
      // ✅ New user - go to user-details flow
      redirectTo = "/user-details";
    }

    return res.status(200).json({ user, redirectTo });

  } catch (err) {
    console.error("❌ Token verify error:", err);
    return res.status(401).json({ message: "❌ Token expired or invalid!" });
  }
});








module.exports = router;

