  // ✅ Safe navigate for internal/external links
  const go = (to, options = {}) => {
    if (!to) return;
    if (/^https?:\/\//i.test(to)) {
      window.open(to, options.target || "_blank", "noopener,noreferrer");
    } else {
      navigate(to, options);
