frontend/src/pages/mainAdmin/TopperFeedb.content:
import React, { useState, useEffect } from "react";
import http from "../../../utils/http";
import AdminLayout from '../AdminLayout/AdminLayout';
import "./TopperFeedbackManagement.css";

const TopperFeedbackManagement = () => {
  const [feedbacks, setFeedbacks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentFeedback, setCurrentFeedback] = useState(null);
  const [formData, setFormData] = useState({
    studentName: "",
    order: 0,
    isActive: true
  });
  const [selectedImage, setSelectedImage] = useState(null);
  const [previewUrl, setPreviewUrl] = useState("");

  useEffect(() => {
    fetchFeedbacks();
  }, []);

  const fetchFeedbacks = async () => {
    try {
      setLoading(true);
      const res = await http.get("/topper-feedback/all");
      if (res.data?.success) {
        setFeedbacks(res.data.feedbacks || []);
      }
    } catch (error) {
      console.error("Error fetching feedbacks:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value
    }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setSelectedImage(file);
      setPreviewUrl(URL.createObjectURL(file));
    }
  };

  const resetForm = () => {
    setFormData({
      studentName: "",
      order: 0,
      isActive: true
    });
    setSelectedImage(null);
    setPreviewUrl("");
    setCurrentFeedback(null);
    setEditMode(false);
  };

  const openAddModal = () => {
    resetForm();
    setShowModal(true);
  };

  const openEditModal = (feedback) => {
    setCurrentFeedback(feedback);
    setFormData({
      studentName: feedback.studentName || "",
      order: feedback.order || 0,
      isActive: feedback.isActive
    });
    setPreviewUrl(feedback.imageUrl);
    setEditMode(true);
    setShowModal(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formPayload = new FormData();
    formPayload.append("studentName", formData.studentName);
    formPayload.append("order", formData.order);
    formPayload.append("isActive", formData.isActive);

    if (selectedImage) {
      formPayload.append("image", selectedImage);
    }

    try {
      if (editMode && currentFeedback) {
        await http.put(`/topper-feedback/update/${currentFeedback._id}`, formPayload, {
          headers: { "Content-Type": "multipart/form-data" }
        });
      } else {
        if (!selectedImage) {
          alert("Please select an image");
          return;
        }
        await http.post("/topper-feedback/create", formPayload, {
          headers: { "Content-Type": "multipart/form-data" }
        });
      }

      setShowModal(false);
      resetForm();
      fetchFeedbacks();
    } catch (error) {
      console.error("Error saving feedback:", error);
      alert("Error saving feedback");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this feedback?")) return;

    try {
      await http.delete(`/topper-feedback/delete/${id}`);
      fetchFeedbacks();
    } catch (error) {
      console.error("Error deleting feedback:", error);
      alert("Error deleting feedback");
    }
  };

  const handleToggleActive = async (id) => {
    try {
      await http.patch(`/topper-feedback/toggle-active/${id}`);
      fetchFeedbacks();
    } catch (error) {
      console.error("Error toggling status:", error);
    }
  };

  const getImageUrl = (url) => {
    if (!url) return "";
    if (url.startsWith("http")) return url;
    return url;
  };

  return (
    <AdminLayout>
    <div className="feedback-mgmt-container">
      <div className="feedback-mgmt-header">
        <h1>Toppers' Feedback Management</h1>
        <button className="add-btn" onClick={openAddModal}>
          + Add Feedback
        </button>
      </div>

      <p className="feedback-info">
        Manage the testimonial images shown in the "TathaGat Toppers' Feedback" section on the Score Card page.
      </p>

      {loading ? (
        <div className="loading">Loading...</div>
      ) : (
        <div className="feedback-mgmt-grid">
          {feedbacks.length === 0 ? (
            <div className="no-data">No feedback images found. Add some from the button above.</div>
          ) : (
            feedbacks.map((feedback) => (
              <div key={feedback._id} className={`feedback-mgmt-card ${!feedback.isActive ? "inactive" : ""}`}>
                <div className="card-image">
                  <img src={getImageUrl(feedback.imageUrl)} alt={feedback.studentName || "Feedback"} />
                </div>
                <div className="card-info">
                  {feedback.studentName && <p className="student-name">{feedback.studentName}</p>}
                  <p className="order">Order: {feedback.order}</p>
                  <span className={`status ${feedback.isActive ? "active" : "inactive"}`}>
                    {feedback.isActive ? "Active" : "Inactive"}
                  </span>
                </div>
                <div className="card-actions">
                  <button className="edit-btn" onClick={() => openEditModal(feedback)}>Edit</button>
                  <button className="toggle-btn" onClick={() => handleToggleActive(feedback._id)}>
                    {feedback.isActive ? "Deactivate" : "Activate"}
                  </button>
                  <button className="delete-btn" onClick={() => handleDelete(feedback._id)}>Delete</button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h2>{editMode ? "Edit Feedback" : "Add Feedback"}</h2>
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label>Student Name (optional)</label>
                <input 
                  type="text" 
                  name="studentName" 
                  value={formData.studentName} 
                  onChange={handleInputChange}
                  placeholder="Enter student name"
                />
              </div>

              <div className="form-group">
                <label>Display Order</label>
                <input 
                  type="number" 
                  name="order" 
                  value={formData.order} 
                  onChange={handleInputChange}
                />
              </div>

              <div className="form-group">
                <label>Feedback Image *</label>
                <input 
                  type="file" 
                  accept="image/*" 
                  onChange={handleImageChange}
                  required={!editMode}
                />
                {previewUrl && (
                  <div className="image-preview">
                    <img src={previewUrl} alt="Preview" />
                  </div>
                )}
              </div>

              <div className="form-group checkbox-group">
                <label>
                  <input 
                    type="checkbox" 
                    name="isActive" 
                    checked={formData.isActive} 
                    onChange={handleInputChange}
                  />
                  Active
                </label>
              </div>

              <div className="form-actions">
                <button type="button" className="cancel-btn" onClick={() => setShowModal(false)}>
                  Cancel
                </button>
                <button type="submit" className="submit-btn">
                  {editMode ? "Update" : "Add"} Feedback
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
    </AdminLayout>
  );
};

export default TopperFeedbackManagement;

backend/routes/successStoryRoutes.js.content:
const express = require("express");
const SuccessStory = require("../models/SuccessStory");
const { adminAuth } = require("../middleware/authMiddleware");

const router = express.Router();

router.get("/all", async (req, res) => {
  try {
    const { activeOnly } = req.query;
    let query = {};

    if (activeOnly === "true") {
      query.isActive = true;
    }

    const stories = await SuccessStory.find(query).sort({ order: 1, createdAt: -1 });
    res.status(200).json({ success: true, stories });
  } catch (error) {
    console.error("Error fetching success stories:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

router.get("/public", async (req, res) => {
  try {
    const stories = await SuccessStory.find({ isActive: true }).sort({ order: 1, createdAt: -1 });
    res.status(200).json({ success: true, stories });
  } catch (error) {
    console.error("Error fetching public success stories:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

router.post("/create", adminAuth, async (req, res) => {
  try {
    const { studentName, university, youtubeUrl, order, isActive } = req.body;

    if (!studentName || !university || !youtubeUrl) {
      return res.status(400).json({ 
        success: false, 
        message: "Student name, university, and YouTube URL are required" 
      });
    }

    const videoId = extractYouTubeId(youtubeUrl);
    const thumbnailUrl = videoId ? `https://img.youtube.com/vi/${videoId}/hqdefault.jpg` : "";

    const newStory = new SuccessStory({
      studentName,
      university,
      youtubeUrl,
      thumbnailUrl,
      order: order || 0,
      isActive: isActive !== false
    });

    await newStory.save();
    res.status(201).json({ 
      success: true, 
      message: "Success story created successfully", 
      story: newStory 
    });
  } catch (error) {
    console.error("Error creating success story:", error);
    res.status(500).json({ success: false, message: error.message || "Server Error" });
  }
});

router.put("/update/:id", adminAuth, async (req, res) => {
  try {
    const { studentName, university, youtubeUrl, order, isActive } = req.body;
    const story = await SuccessStory.findById(req.params.id);

    if (!story) {
      return res.status(404).json({ success: false, message: "Success story not found" });
    }

    if (studentName) story.studentName = studentName;
    if (university) story.university = university;
    if (youtubeUrl) {
      story.youtubeUrl = youtubeUrl;
      const videoId = extractYouTubeId(youtubeUrl);
      story.thumbnailUrl = videoId ? `https://img.youtube.com/vi/${videoId}/hqdefault.jpg` : "";
    }
    if (order !== undefined) story.order = order;
    if (isActive !== undefined) story.isActive = isActive;

    story.updatedAt = Date.now();
    await story.save();

    res.status(200).json({ 
      success: true, 
      message: "Success story updated successfully", 
      story 
    });
  } catch (error) {
    console.error("Error updating success story:", error);
    res.status(500).json({ success: false, message: error.message || "Server Error" });
  }
});

router.delete("/delete/:id", adminAuth, async (req, res) => {
  try {
    const story = await SuccessStory.findById(req.params.id);

    if (!story) {
      return res.status(404).json({ success: false, message: "Success story not found" });
    }

    await story.deleteOne();
    res.status(200).json({ success: true, message: "Success story deleted successfully" });
  } catch (error) {
    console.error("Error deleting success story:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

router.patch("/toggle-active/:id", adminAuth, async (req, res) => {
  try {
    const story = await SuccessStory.findById(req.params.id);
    if (!story) {
      return res.status(404).json({ success: false, message: "Success story not found" });
    }

    story.isActive = !story.isActive;
    story.updatedAt = Date.now();
    await story.save();

    res.status(200).json({ 
      success: true, 
      message: `Story ${story.isActive ? 'activated' : 'deactivated'} successfully`, 
      story 
    });
  } catch (error) {
    console.error("Error toggling story status:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

function extractYouTubeId(url) {
  if (!url) return null;
  const patterns = [
    /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/|youtube\.com\/live\/)([^&\n?#]+)/,
    /^([a-zA-Z0-9_-]{11})$/
  ];
  for (const pattern of patterns) {
    const match = url.match(pattern);
    if (match) return match[1];
  }
  return null;
}

module.exports = router;

