frontend/src/pages/mainAdmin/BatchManage.content:
.batch-management {
  padding: 20px;
  max-width: 1200px;
  margin: 0 auto;
}

.batch-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 30px;
  border-bottom: 2px solid #e5e7eb;
  padding-bottom: 15px;
}

.batch-header h1 {
  color: #1f2937;
  margin: 0;
  font-size: 2rem;
  font-weight: 700;
}

.batch-tabs {
  display: flex;
  gap: 10px;
}

.tab-btn {
  padding: 10px 20px;
  border: 2px solid #e5e7eb;
  background: white;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 600;
  transition: all 0.2s;
}

.tab-btn:hover {
  border-color: #3b82f6;
  color: #3b82f6;
}

.tab-btn.active {
  background: #3b82f6;
  color: white;
  border-color: #3b82f6;
}

/* Form Cards */
.batch-form-card,
.session-form-card {
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 25px;
  margin-bottom: 30px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.batch-form-card h3,
.session-form-card h3 {
  margin: 0 0 20px 0;
  color: #374151;
  font-size: 1.25rem;
  font-weight: 600;
}

.batch-form,
.session-form {
  display: grid;
  gap: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-group label {
  font-weight: 600;
  color: #374151;
  font-size: 0.9rem;
}

.form-group input,
.form-group select {
  padding: 12px;
  border: 2px solid #e5e7eb;
  border-radius: 8px;
  font-size: 0.95rem;
  transition: border-color 0.2s;
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59,130,246,0.1);
}

.course-selection {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px;
  max-height: 120px;
  overflow-y: auto;
  padding: 10px;
  border: 2px solid #e5e7eb;
  border-radius: 8px;
}

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  cursor: pointer;
  padding: 5px;
  border-radius: 4px;
  transition: background-color 0.2s;
}

.checkbox-label:hover {
  background-color: #f3f4f6;
}

.checkbox-label input[type="checkbox"] {
  width: auto;
  margin: 0;
}

.submit-btn {
  background: #16a34a;
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  justify-self: start;
}

.submit-btn:hover {
  background: #15803d;
}

/* Batch Grid */
.batches-list,
.sessions-list {
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 25px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.batches-list h3,
.sessions-list h3 {
  margin: 0 0 20px 0;
  color: #374151;
  font-size: 1.25rem;
  font-weight: 600;
}

.batch-grid,
.sessions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
}

.batch-card,
.session-card {
  border: 2px solid #e5e7eb;
  border-radius: 12px;
  padding: 20px;
  background: white;
  transition: all 0.2s;
}

.batch-card:hover,
.session-card:hover {
  border-color: #3b82f6;
  box-shadow: 0 4px 12px rgba(59,130,246,0.1);
}

.batch-card-header,
.session-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
}

.batch-card-header h4 {
  margin: 0;
  color: #1f2937;
  font-size: 1.1rem;
  font-weight: 600;
}

.subject-chip {
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
}

.subject-A {
  background: #dbeafe;
  color: #1d4ed8;
}

.subject-B {
  background: #fef3c7;
  color: #d97706;
}

.subject-C {
  background: #f3e8ff;
  color: #7c3aed;
}

.subject-D {
  background: #d1fae5;
  color: #059669;
}

.batch-courses {
  margin-bottom: 15px;
}

.batch-courses p {
  margin: 0 0 8px 0;
  color: #6b7280;
  font-size: 0.9rem;
}

.course-names {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.course-tag {
  background: #f3f4f6;
  color: #374151;
  padding: 3px 8px;
  border-radius: 12px;
  font-size: 0.75rem;
  border: 1px solid #e5e7eb;
}

.batch-actions {
  display: flex;
  gap: 10px;
  align-items: center;
}

.subject-select {
  flex: 1;
  padding: 8px;
  border: 2px solid #e5e7eb;
  border-radius: 6px;
  font-size: 0.85rem;
}

.mark-done-btn {
  background: #f59e0b;
  color: white;
  border: none;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  white-space: nowrap;
}

.mark-done-btn:hover {
  background: #d97706;
}

/* Session specific styles */
.session-time {
  color: #6b7280;
  font-size: 0.85rem;
}

.session-details {
  margin-bottom: 15px;
}

.session-details p {
  margin: 5px 0;
  font-size: 0.9rem;
  color: #374151;
}

.session-details a {
  color: #3b82f6;
  text-decoration: none;
}

.session-details a:hover {
  text-decoration: underline;
}

.session-actions {
  display: flex;
  gap: 10px;
}

.recording-input {
  flex: 1;
  padding: 8px 12px;
  border: 2px solid #e5e7eb;
  border-radius: 6px;
  font-size: 0.85rem;
}

.recording-input:focus {
  outline: none;
  border-color: #3b82f6;
}

/* Responsive */
@media (max-width: 768px) {
  .batch-management {
    padding: 15px;
  }

  .batch-header {
    flex-direction: column;
    align-items: stretch;
    gap: 15px;
  }

  .batch-tabs {
    justify-content: center;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .batch-grid,
  .sessions-grid {
    grid-template-columns: 1fr;
  }

  .batch-actions {
    flex-direction: column;
    align-items: stretch;
  }
}

/* Loading state */
.batch-management .loading {
  text-align: center;
  padding: 40px;
  color: #6b7280;
  font-style: italic;
}

frontend/src/components/FirstPage/ThirdP.content:
.catresults-container {
  padding: 60px;
  background-color: #ffffff;
  font-family: "Clash Display", serif;
}

/* Top Row for heading + stats side by side */
.catresults-top-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
}

/* Left Heading Block */
.catresults-heading-block {
  flex-shrink: 0;
}

.catresults-year {
  font-size: 24px;
  font-weight: 400;
  font-family: "Manrope", sans-serif;
  color: #1a237e;
  display: flex;
}

.catresults-year .arrow {
  font-size: 24px;
  margin-left: 4px;
  font-weight: 400;
  font-family: "Manrope", sans-serif;
  color: #1a237e;
}

.catresults-title {
  font-size: 58px;
  font-weight: 400;
  color: #070a22;
  margin-top: 5px;
  text-align: left;
  font-family: DM serif Display;
}

/* Right Stats Grid */
.catresults-stats {
  display: flex;
  gap: 80px;
  align-items: center;
  flex-wrap: wrap;
}

.catresults-box {
  text-align: center;
  min-width: 100px;
}

.catresults-number {
  font-size: 38px;
  font-weight: 700;
  color: #f25c54;
  font-family: "Manrope", sans-serif;
}

.catresults-label {
  font-size: 24px;
  font-weight: 500;
  color: #070a22;
  font-family: "Manrope", sans-serif;
  margin-top: 6px;
}

.tt-student-showcase-wrapper {
  padding: 0 60px;
  background-color: #ffffff;
}

.tt-student-cards-scroll {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: 20px;
  padding-bottom: 10px;
  scroll-behavior: smooth;
}

.tt-student-cards-scroll::-webkit-scrollbar {
  display: none; /* Hide scrollbar for Chrome, Safari */
}

.tt-student-cards-scroll {
  -ms-overflow-style: none; /* Hide scrollbar for IE/Edge */
  scrollbar-width: none; /* Hide scrollbar for Firefox */
}

.tt-student-card {
  flex: 0 0 180px;
  width: 180px;
  min-height: 360px;
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);
  background: #fff;
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}

.tt-student-card:hover {
  transform: translateY(-4px);
}

.tt-student-card img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  border-radius: 16px 16px 0 0;
  flex-shrink: 0;
}

.tt-student-name {
  position: absolute;
  left: 16px;
  bottom: 60px;
  display: none;
  color: white;
  font-weight: 600;
  font-size: 16px;
  z-index: 1;
}

.tt-student-percentile {
  margin-top: 10px;
  font-weight: 700;
  font-size: 18px;
  color: #1b1ba3;
  padding: 0 16px 16px;
}

.tt-student-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 280px;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.2));
  color: white;
  padding: 20px;
  opacity: 0;
  transition: opacity 0.3s ease;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.tt-student-card:hover .tt-student-overlay {
  opacity: 1;
}

.tt-student-overlay h4 {
  font-size: 18px;
  margin-bottom: 8px;
  font-weight: 700;
}

.tt-student-overlay p {
  font-size: 14px;
  line-height: 1.4;
}

.tt-overlay-content {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  width: 100%;
  height: 100%;
}

.tt-student-footer-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 30px;
}

.tt-student-nav {
  display: flex;
  align-items: center;
  margin-top: -50px;
  /* gap: 16px; */
  /* margin-left: 50px; */
}

.tt-circle-btn {
  /* background: #ea580c; */
  border: none;
  border-radius: 50%;
  background-color: white;
