  font-size: 28px;
  margin-bottom: 20px;
  color: #1a237e;
  text-align: center;
  font-family: "Manrope", sans-serif;
}

.ts-demo-form {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.ts-demo-form input {
  padding: 12px;
  font-size: 14px;
  border: 1px solid #ddd;
  border-radius: 4px;
  outline: none;
  transition: border-color 0.3s ease;
}

.ts-demo-form input:focus {
  border-color: #ee6a4d;
}

.ts-demo-form button {
  padding: 12px 24px;
  font-size: 15px;
  border-radius: 6px;
  background-color: #ee6a4d;
  color: #fff;
  border: none;
  cursor: pointer;
  font-weight: 600;
  transition: background-color 0.3s ease;
}

.ts-demo-form button:hover {
  background-color: #d9583d;
}

/* ===== TESTIMONIALS SECTION ===== */
.ts-scrolling-wrapper {
  overflow: hidden;
  position: relative;
}

.ts-scrolling-track {
  display: flex;
  gap: 20px;
  animation: scroll 20s linear infinite;
}

.ts-scrolling-wrapper:hover .ts-scrolling-track {
  animation-play-state: paused;
}

@keyframes scroll {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-100%);
  }
}

.ts-testimonial-card {
  min-width: 300px;
  max-width: 300px;
  background: #ffc107;
  color: #000;
  border-radius: 15px;
  overflow: hidden;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.ts-testimonial-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.ts-testimonial-image {
  width: 100%;
  height: 150px;
  object-fit: contain;
  border-radius: 15px;
  margin-bottom: 15px;
}

.ts-testimonial-content {
  padding: 15px;
  text-align: center;
  width: 100%;
}

.ts-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
}

.ts-testimonial-message {
  font-style: italic;
}

.ts-author {
  margin-top: 10px;
  font-weight: bold;
}

/* ===== TEAM SECTION ===== */
.ts-team-wrapper {
  background-color: #ffc107;
  display: flex;
  padding: 60px 40px;
  gap: 40px;
  flex-wrap: wrap;
  justify-content: space-between;
  font-family: "Manrope", sans-serif;
}

.ts-team-left {
  flex: 1;
  min-width: 330px;
}

.ts-team-heading {
  font-size: 48px;
  color: #000;
  font-weight: 600;
  margin-bottom: 30px;
  font-family: "DM Serif Display", serif;
  text-align: left;
}

.ts-contact-btn {
  background-color: #f45e4b;
  color: white;
  padding: 12px 24px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  font-size: 16px;
  display: inline-flex;
  transition: background-color 0.3s ease;
}

.ts-contact-btn:hover {
  background-color: #e04a37;
}

.ts-team-right {
  flex: 1;
  min-width: 320px;
  padding: 20px;
  position: relative;
}

.ts-team-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: white;
  font-weight: 600;
  margin-bottom: 15px;
}

.ts-team-box {
  position: relative;
  overflow: hidden;
  border-radius: 15px;
  /* background-color: #1a237e; */
  width: 300px;
  background-color: #1a237e;
  height: 500px; /* 👈 Add this */
}
.ts-team-image {
  width: 500px;
  height: 250px;
  border-radius: 10px;
  display: block;
  object-fit: cover;
}

.ts-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background-color: white;
  color: black;
  border-radius: 50%;
  padding: 6px 12px;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  border: none;
  transition: background-color 0.3s ease;
}

.ts-arrow:hover {
  background-color: #f0f0f0;
}

.ts-arrow.left {
  left: 10px;
}

.ts-arrow.right {
  right: 10px;
}

/* ===== FAQ SECTION ===== */
.tg-faq-section {
  display: flex;
  background-color: #0c0f25;
  color: white;
  padding: 80px 78px;
  font-family: "Poppins", sans-serif;
  justify-content: space-between;
  gap: 60px;
  flex-wrap: wrap;
}

.tg-faq-left {
  flex: 1;
  max-width: 500px;
}

.tg-faq-left h5 {
  color: #ee6a4d;
  text-transform: uppercase;
  font-size: 20px;
  font-weight: 500;
  margin-bottom: 20px;
}

.tg-faq-left h2 {
  font-size: 52px;
  font-weight: bold;
  color: #fff;
  line-height: 0.9;
  margin-bottom: 10px;
  font-family: "DM Serif Display", serif;
}

.tg-faq-left p {
  font-size: 16px;
  font-weight: 500;
  color: #d0d3f2;
  margin-bottom: 30px;
  text-align: left;
}

.tg-faq-left button {
  background: #d8583f;
  color: white;
  font-weight: 600;
  font-size: 15px;
  border: none;
  padding: 14px 24px;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.tg-faq-left button:hover {
  background: #c04a31;
}

.tg-faq-right {
  flex: 1.2;
  display: flex;
  flex-direction: column;
  gap: 18px;
  max-width: 750px;
}

.tg-faq-item {
  background: transparent;
  border-bottom: 1px solid #2e314e;
  padding-bottom: 14px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.tg-faq-item.open .tg-faq-answer {
  margin-top: 10px;
  font-size: 15px;
  color: #d0d3f2;
  line-height: 1.6;
  display: block;
  text-align: left;
}

.tg-faq-question {
  font-size: 20px;
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: white;
}

.tg-faq-toggle {
  font-size: 26px;
