/* ===== MOBILE RESPONSIVE ===== */
@media (max-width: 768px) {
  /* Global image reset */
  img,
  iframe {
    max-width: 100%;
    height: auto;
    display: block;
  }

  /* Success Story Section */
  .success-container {
    padding: 20px 15px;
  }

  .success-heading {
    font-size: 28px;
    font-family: "DM Serif Display", serif;
    font-weight: 700;
