  .ts-achievers-subtitle {
    font-size: 16px;
    line-height: 1.5;
    text-align: center;
    max-width: 100%;
  }

  .ts-achievers-grid {
    overflow-x: auto;
    gap: 15px;
    padding-bottom: 20px;
    justify-content: flex-start;
  }

  .ts-achiever-card {
    width: 280px;
    min-width: 280px;
  }

  .ts-image-container {
    height: 180px;
  }

  .ts-card-footer {
    padding: 15px;
    font-size: 14px;
  }

  /* Demo Section */
  .ts-demo-wrapper {
    flex-direction: column;
    padding: 40px 15px;
    gap: 30px;
  }

  .ts-demo-left,
  .ts-demo-right {
    width: 100%;
    max-width: 100%;
    min-width: unset;
  }

  .ts-demo-heading {
    font-size: 28px;
    text-align: center;
  }

  .ts-demo-subtext {
    font-size: 16px;
    text-align: center;
    line-height: 1.5;
  }

  .ts-demo-right {
    margin: 0 auto;
    max-width: 400px;
  }

  .ts-demo-right h3 {
    font-size: 22px;
  }

  /* Testimonials Section */
  .ts-scrolling-wrapper {
    overflow-y: auto;
    overflow-x: hidden;
    max-height: 500px;
  }

  .ts-scrolling-track {
    display: block;
    animation: none;
    gap: 15px;
  }

  .ts-testimonial-card {
    min-width: 100%;
    max-width: 100%;
    margin-bottom: 15px;
    max-width: 350px;
    margin-left: auto;
    margin-right: auto;
  }

  .ts-scrolling-wrapper::-webkit-scrollbar {
    width: 4px;
  }

  .ts-scrolling-wrapper::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 2px;
  }

  /* Team Section */
  .ts-team-wrapper {
    flex-direction: column;
    text-align: center;
    padding: 40px 15px;
    gap: 30px;
  }

  .ts-team-left,
  .ts-team-right {
    width: 100%;
    max-width: 100%;
    min-width: unset;
  }

  .ts-team-heading {
    font-size: 28px;
    text-align: center;
  }

  .ts-team-box {
    margin: 0 auto;
    max-width: 300px;
    position: relative;
  }

  .ts-team-image {
    height: 170px;
  }

  .ts-arrow {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    font-size: 16px;
    padding: 8px 12px;
  }

  .ts-arrow.left {
    left: 10px;
  }

  .ts-arrow.right {
    right: 10px;
  }

  .ts-contact-btn {
    margin: 20px auto 0;
    display: block;
    width: fit-content;
  }

  /* FAQ Section */
  .tg-faq-section {
    flex-direction: column;
    padding: 40px 15px;
    gap: 30px;
  }

  .tg-faq-left,
  .tg-faq-right {
