    text-align: center;
  }

  .tg-faq-left p {
    text-align: center;
  }

  .tg-faq-left button {
    margin: 0 auto;
    display: block;
  }

  .tg-faq-question {
    font-size: 16px;
  }

  .tg-faq-toggle {
    font-size: 20px;
  }

  /* Button alignment */
  .ts-view-all-btn {
    margin: 20px auto;
    display: block;
  }
}

/* ===== SMALL MOBILE RESPONSIVE ===== */
@media (max-width: 480px) {
  .success-container {
    padding: 15px 10px;
