    padding: 30px 10px;
  }

  .tg-faq-section {
    padding: 30px 10px;
  }

  .ts-demo-right {
    padding: 20px 15px;
  }
}

frontend/src/components/StudentInformati.content:
/* ✅ Student Information Page Styling */
.student-container {
    padding: 30px;
    background: #f4f4f4;
    font-family: 'Poppins', sans-serif;
}

/* ✅ Back Button */
.back-button {
    background: #2C3E50;
    color: white;
    border: none;
    padding: 10px 15px;
    font-size: 14px;
    font-weight: bold;
    border-radius: 5px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 15px;
}

.back-button:hover {
    background: #1abc9c;
}

/* ✅ Page Heading */
.student-container h2 {
    text-align: center;
    margin-bottom: 20px;
    font-size: 24px;
    font-weight: bold;
    color: #2C3E50;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ✅ Table Container */
.student-table-container {
    overflow-x: auto;
    background: white;
    padding: 20px;
    border-radius: 12px;
    box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.1);
    min-height: 400px; /* ✅ Fix Height */
}

/* ✅ Loading Spinner */
.loading-spinner {
    text-align: center;
    font-size: 18px;
    font-weight: bold;
    color: #2C3E50;
    margin-top: 50px;
    animation: blink 1s infinite;
}

/* ✅ Animation for Loading */
@keyframes blink {
    50% { opacity: 0.5; }
}

/* ✅ Student Table */
.student-table {
    width: 100%;
    border-collapse: collapse;
    border-radius: 10px;
    overflow: hidden;
}

/* ✅ Table Header */
.student-table thead {
    background: #2C3E50;
    color: white;
}

.student-table th {
    padding: 14px;
    text-align: center;
    font-size: 16px;
    font-weight: bold;
}

/* ✅ Table Rows */
.student-table td {
    padding: 12px;
    text-align: center;
    border-bottom: 1px solid #ddd;
    font-size: 14px;
    color: #333;
}

/* ✅ Profile Image */
.profile-image {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    border: 2px solid #2C3E50;
    object-fit: cover;
}

/* ✅ Hover Effect on Rows */
.student-table tbody tr:hover {
    background: #f1f1f1;
    transition: 0.3s;
}

/* ✅ No Data Message */
.no-data {
    text-align: center;
    font-size: 16px;
    color: #555;
    margin-top: 20px;
    font-weight: bold;
}

/* ✅ Responsive Table */
@media (max-width: 1024px) {
    .student-table-container {
        padding: 15px;
    }

    .student-table th, .student-table td {
        font-size: 14px;
        padding: 10px;
    }

    .student-table img {
        width: 40px;
        height: 40px;
    }
}

@media (max-width: 768px) {
    .student-container h2 {
        font-size: 20px;
    }

    .student-table th, .student-table td {
        font-size: 12px;
        padding: 8px;
    }

    .student-table img {
        width: 35px;
        height: 35px;
    }
}

@media (max-width: 480px) {
    .student-container {
        padding: 20px;
    }

    .student-table th, .student-table td {
        font-size: 11px;
        padding: 6px;
    }

    .student-table img {
        width: 30px;
        height: 30px;
    }
}


/* ✅ Action Icons */
.icon {
    cursor: pointer;
    font-size: 16px;
    margin: 5px;
    padding: 6px;
    border-radius: 50%;
    transition: 0.3s;
}

.icon.edit {
    color: #3498db;
}

.icon.update {
    color: #27ae60;
}

.icon.cancel {
    color: #e74c3c;
}

.icon.delete {
    color: #e74c3c;
}

/* ✅ Hover Effects */
.icon:hover {
    background: rgba(0, 0, 0, 0.1);
}

/* ✅ Input Fields */
.student-table input {
    width: 100%;
    padding: 5px;
    border: 1px solid #ccc;
    border-radius: 5px;
}

/* ✅ Responsive Design */
@media (max-width: 1024px) {
    .student-table-container {
        padding: 15px;
    }

    .student-table th, .student-table td {
        font-size: 14px;
        padding: 10px;
    }
}

@media (max-width: 768px) {
    .student-table th, .student-table td {
        font-size: 12px;
        padding: 8px;
    }
}

@media (max-width: 480px) {
    .student-table th, .student-table td {
        font-size: 11px;
        padding: 6px;
    }
}

frontend/src/pages/mainAdmin/Announcemen.content:
.announcements-container {
  padding: 24px;
  max-width: 1400px;
  margin: 0 auto;
  background-color: #f8f9fa;
  min-height: 100vh;
}

/* Header */
.announcements-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
  background: white;
  padding: 24px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.header-left h1 {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 8px 0;
  color: #2c3e50;
  font-size: 28px;
  font-weight: 600;
}

.header-left p {
  margin: 0;
  color: #6c757d;
  font-size: 16px;
}

.create-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #007bff, #0056b3);
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
}

.create-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(0, 123, 255, 0.3);
}

/* Statistics Cards */
.stats-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

.stat-card {
  background: white;
  padding: 24px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
  gap: 16px;
  transition: transform 0.3s ease;
}

.stat-card:hover {
  transform: translateY(-2px);
}

.stat-icon {
  width: 56px;
  height: 56px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: white;
}

.stat-icon.total {
  background: linear-gradient(135deg, #667eea, #764ba2);
}

.stat-icon.active {
  background: linear-gradient(135deg, #10b981, #059669);
}

.stat-icon.pinned {
  background: linear-gradient(135deg, #f59e0b, #d97706);
}

.stat-icon.views {
  background: linear-gradient(135deg, #8b5cf6, #7c3aed);
}

.stat-info h3 {
  margin: 0 0 4px 0;
  font-size: 28px;
  font-weight: 700;
  color: #1f2937;
}

.stat-info p {
  margin: 0;
  color: #6b7280;
  font-size: 14px;
  font-weight: 500;
}

/* Filters */
.announcements-filters {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
  background: white;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  align-items: center;
  flex-wrap: wrap;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: 8px;
  position: relative;
}

.filter-group select {
  padding: 10px 16px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  background: white;
  font-size: 14px;
  color: #495057;
  cursor: pointer;
  transition: border-color 0.3s ease;
  min-width: 150px;
}

.filter-group select:focus {
  outline: none;
  border-color: #007bff;
}

.filter-icon {
  color: #6c757d;
  font-size: 16px;
}

.search-group {
  display: flex;
  align-items: center;
  position: relative;
  margin-left: auto;
}

.search-icon {
  position: absolute;
  left: 12px;
  color: #6c757d;
  font-size: 14px;
}

.search-group input {
  padding: 10px 16px 10px 40px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  background: white;
  font-size: 14px;
  color: #495057;
  transition: border-color 0.3s ease;
  min-width: 250px;
}

.search-group input:focus {
  outline: none;
  border-color: #007bff;
}

/* Table */
.announcements-table-container {
  background: white;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  margin-bottom: 24px;
}

.announcements-table {
  width: 100%;
  border-collapse: collapse;
}

.announcements-table th {
  background: #f8f9fa;
  padding: 16px;
  text-align: left;
  font-weight: 600;
  color: #495057;
  border-bottom: 2px solid #e9ecef;
  font-size: 14px;
}

.announcements-table td {
  padding: 16px;
  border-bottom: 1px solid #e9ecef;
  vertical-align: middle;
}

.announcements-table tr:hover {
  background-color: #f8f9fa;
}

.announcement-info .announcement-details {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.type-icon {
  font-size: 20px;
  min-width: 24px;
}

.announcement-details h4 {
  margin: 0 0 4px 0;
  color: #2c3e50;
  font-size: 16px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pin-icon {
  color: #f59e0b;
  font-size: 14px;
}

.announcement-details p {
  margin: 0;
  color: #6c757d;
  font-size: 14px;
  line-height: 1.4;
}

.type-badge,
.priority-badge,
.audience-badge,
.status-badge {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.type-badge {
  background: linear-gradient(135deg, #e3f2fd, #bbdefb);
  color: #1976d2;
}

.priority-badge {
  color: white;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.audience-badge {
  background: linear-gradient(135deg, #f3e5f5, #e1bee7);
  color: #7b1fa2;
}

.status-badge.active {
  background: linear-gradient(135deg, #d4edda, #c3e6cb);
  color: #155724;
}

.status-badge.inactive {
  background: linear-gradient(135deg, #f8d7da, #f5c6cb);
  color: #721c24;
}

.actions {
  display: flex;
  gap: 8px;
}

.action-btn {
  padding: 8px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 14px;
  min-width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.view-btn {
  background: #e3f2fd;
  color: #1976d2;
}

.view-btn:hover {
  background: #bbdefb;
}

.edit-btn {
  background: #fff3e0;
  color: #f57c00;
}

.edit-btn:hover {
  background: #ffe0b2;
}

.delete-btn {
  background: #ffebee;
  color: #d32f2f;
}

.delete-btn:hover {
  background: #ffcdd2;
}

.no-data {
  text-align: center;
  padding: 48px;
  color: #6c757d;
  font-style: italic;
}

/* Loading */
.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px;
  gap: 16px;
}

.loading-spinner {
  width: 40px;
  height: 40px;
  border: 4px solid #e9ecef;
  border-top: 4px solid #007bff;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  background: white;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.pagination button {
  padding: 8px 16px;
  border: 2px solid #e9ecef;
  background: white;
  color: #495057;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.pagination button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.pagination button:not(:disabled):hover {
  border-color: #007bff;
  color: #007bff;
}

.page-info {
  color: #6c757d;
  font-weight: 500;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;
}

.announcement-modal {
  background: white;
  border-radius: 16px;
  max-width: 700px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px;
  border-bottom: 1px solid #e9ecef;
}

.modal-header h2 {
  margin: 0;
  color: #2c3e50;
  font-size: 24px;
  font-weight: 600;
}

.close-btn {
  background: none;
  border: none;
  font-size: 24px;
  color: #6c757d;
  cursor: pointer;
  padding: 4px;
  line-height: 1;
  transition: color 0.3s ease;
}

.close-btn:hover {
  color: #495057;
}

.announcement-form {
  padding: 24px;
}

.form-group {
  margin-bottom: 20px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: #495057;
  font-weight: 500;
  font-size: 14px;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  font-size: 14px;
  color: #495057;
  transition: border-color 0.3s ease;
  box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: #007bff;
}

.form-group textarea {
  resize: vertical;
  min-height: 120px;
}

.checkbox-group {
  margin-top: 24px;
}

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  font-size: 16px;
  color: #495057;
}

.checkbox-label input[type="checkbox"] {
  width: auto;
  margin: 0;
}

.checkmark {
  font-weight: 500;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 32px;
  padding-top: 20px;
  border-top: 1px solid #e9ecef;
}

.cancel-btn {
  padding: 12px 24px;
  border: 2px solid #e9ecef;
  background: white;
  color: #495057;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 14px;
  font-weight: 500;
}

.cancel-btn:hover {
  border-color: #6c757d;
  color: #6c757d;
}

.submit-btn {
  padding: 12px 24px;
  border: none;
  background: linear-gradient(135deg, #28a745, #20c997);
  color: white;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 14px;
  font-weight: 500;
}

.submit-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(40, 167, 69, 0.3);
}

.submit-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* Responsive */
@media (max-width: 768px) {
  .announcements-container {
    padding: 16px;
  }

  .announcements-header {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .announcements-filters {
    flex-direction: column;
    align-items: stretch;
  }

  .search-group {
    margin-left: 0;
  }

  .search-group input {
    min-width: 100%;
  }

  .announcements-table-container {
    overflow-x: auto;
  }

  .announcements-table {
    min-width: 800px;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .modal-overlay {
    padding: 10px;
  }

  .announcement-modal {
    max-height: 95vh;
  }

  .stats-cards {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  }
}

@media (max-width: 480px) {
  .header-left h1 {
    font-size: 24px;
  }

  .create-btn {
    width: 100%;
    justify-content: center;
  }

  .announcements-filters {
    padding: 16px;
  }

  .announcement-form {
    padding: 16px;
  }

  .modal-header {
    padding: 16px;
  }

  .stats-cards {
    grid-template-columns: 1fr;
  }

  .stat-card {
    padding: 16px;
  }
}

