@media (max-width: 768px) {
  /* Original grid ko mobile par hide karo */
  .tt-team-grid-desktop {
    display: none !important;
  }

  /* Mobile scroller container visible */
  .tt-team-scroller {
    display: flex;
    flex-direction: column;
    gap: 14px;
    width: 100%;
  }

  /* Each strip horizontally scrollable */
  .tt-team-strip {
    display: flex;
    gap: 12px;
    overflow-x: auto;
    padding: 2px 2px 8px;
