frontend/src/pages/MockTest/MockTest.css.content:
/* ============ Base Reset ============ */
body { margin: 0; }
#app { height: auto; width: 100%; background-color: white; }
#page1 { height: auto; width: 100%; }

/* ============ Hero / Lead Section ============ */
.mock-container {
  display: flex;
  flex-wrap: wrap;
  background-color: #0a0f3c;
  color: white;
  padding: 60px;
  justify-content: space-between;
  gap: 40px;
  top: 125px;
}

.mock-left { flex: 1; min-width: 300px; max-width: 600px; }

.tagline {
  color: #D8583F;
  margin-bottom: 10px;
  font-size: 20px;
  font-weight: 500;
  font-family: "Manrope", sans-serif;
  margin-top: 2px;
  text-align: left;
}

.heading {
  font-size: 58px;
  font-weight: 700;
  font-family: "Manrope", sans-serif;
  line-height: 1;
  margin-bottom: 15px;
  margin-top: 20px;
  text-align: left;
  color: #FFFFFF;
  width: max-content;
}

.description {
  font-size: 20px;
  margin-bottom: 20px;
  font-weight: 500;
  font-family: "Manrope", sans-serif;
  margin-top: 30px;
  color: #fff;
  text-align: left;
}

.stats {
  display: flex;
  gap: 80px;
  font-size: 58px;
  margin-bottom: 15px;
  font-weight: 500;
  font-family: "Manrope", sans-serif;
  color: #9747FF;
}
.stats span {
  color: #fff;
  font-weight: 500;
  font-size: 16px;
  font-family: "Manrope", sans-serif;
}

.success-title {
  font-weight: 700;
  margin-bottom: 10px;
  font-size: 20px;
  color: #FFFFFF;
  text-align: left;
  font-family: "Manrope", sans-serif;
}

/* ============ Videos ============ */
.videos {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 10px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}
.videos::before,
.videos::after {
  content: "";
  position: sticky;
  top: 0;
  width: 24px;
  flex: 0 0 auto;
  pointer-events: none;
  z-index: 1;
  height: 0; /* just to keep sticky context */
}
.videos::-webkit-scrollbar { display: none; }

.video { flex: 0 0 auto; width: 320px; scroll-snap-align: start; }

.video iframe {
  width: 100%;
  height: 200px;
  border-radius: 12px;
  border: none;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.2);
}

/* Mobile Responsive */
@media (max-width: 600px) {
  .video { width: 280px; }
  .video iframe { height: 180px; }
}
@media (max-width: 768px) {
  .video iframe { height: 160px; }
}
@media (max-width: 480px) {
  .video iframe { height: 140px; }
}

.mock-right {
  background: white;
  color: #FFFFFF;
  padding: 40px;
  border-radius: 8px;
  flex: 1;
  max-width: 430px;
  height: 600px;
  min-width: 280px;
  box-shadow: 0 0 10px #787878;
}

.mock-right h2 {
  font-size: 28px;
  margin-bottom: 20px;
  color: #1A237E;
  font-weight: 700;
  font-family: "Manrope", sans-serif;
  margin-bottom: 20px;
} 

.form-box input,
.form-box select {
  width: 100%;
  padding: 12px;
  margin-bottom: 15px;
  border: 1px solid gray;
  color: black;
  border-radius: 8px;
  font-size: 15px;
}

.form-box button {
  width: 100%;
  padding: 12px;
  background-color: #D8583F;
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 16px;
  font-family: "Manrope", sans-serif;
  cursor: pointer;
  transition: 0.3s;
  font-weight: 700;
  margin-top: 40px;
}
.form-box button:hover { background-color: #d3421c; }

/* ============ Page / Filters ============ */
.cat-mock-container {
  padding: 40px;
  background-color: #ffffff;
  max-width: 1600px;
  margin: auto;
  font-family: 'Segoe UI', sans-serif;
}

.page-title {
  color: #000000;
  font-size: 48px;
  font-weight: 400;
  font-family: "DM Serif Display", serif;
  margin-bottom: 24px;
  text-align: left;
}

.tgv-scroll-wrapper {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  width: 100%;
  padding-bottom: 5px;
}
.tgv-scroll-wrapper::-webkit-scrollbar { display: none; }

.filter-buttons {
  display: inline-flex;
  flex-wrap: nowrap !important;
  gap: 10px;
  width: max-content;
  margin-bottom: 30px;
  font-weight: 600;
  font-size: 16px;
}

.filter-buttons button {
  flex-shrink: 0;
  white-space: nowrap;
  padding: 8px 18px;
  border-radius: 20px;
  border: 1px solid #1A237E;
  background-color: white;
  color: #1A237E;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.3s;
}
.filter-buttons button.active {
  background-color: #1A237E;
  color: white;
}

/* Optional wrapper (used on mobile sometimes) */
.filter-scroll-wrapper {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.filter-scroll-wrapper::-webkit-scrollbar { display: none; }

/* ============ Test Grid & Cards ============ */
.test-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  color: #cdcfd426;
}

.test-card {
  position: relative;
  isolation: isolate;          /* ensure overlay stacks on top */
  overflow: hidden;
  background: #E5E7EB;         /* light grey */
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 0 6px rgba(161, 159, 159, 0.05);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.test-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #1A237E26;
}

.labels { display: flex; gap: 8px; }
.label {
  padding: 4px 10px;
  font-size: 14px;
  color: #121850;
  border-radius: 12px;
  font-weight: 500;
}
.label.free,
.label.must {
  background: #fff;
  color: #121850;
  font-weight: 500;
  font-size: 14px;
  border-radius: 0px;
}

.attempt-btn {
  padding: 6px 12px;
  background: transparent;
  border: 1.5px solid #EE6A4D;
  color: #EE6A4D;
  background-color: #FFFFFF;
  border-radius: 6px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s ease-in-out;
  font-size: 16px;
}
.attempt-btn:hover { background-color: #f04f23; color: white; }
.attempt-btn:disabled,
.attempt-btn[aria-disabled="true"] {
  opacity: 0.6;
  cursor: not-allowed;
  border-color: #9ca3af;
  color: #9ca3af;
}
.attempt-btn:disabled:hover { background: #FFFFFF; color: #9ca3af; }

.test-title {
  font-size: 20px;
  font-weight: 500;
  margin: 16px 0 10px;
  color: #05071A;
  margin-top: 12px;
  text-align: left;
  font-family: "Manrope", sans-serif;
}

.test-meta {
  font-size: 14px;
  display: flex;
  gap: 16px;
  color: #05071A;
  margin-bottom: 12px;
  font-weight: 500;
  margin-top: 12px;
}

/* ✅ FINAL Coming Soon State — blur + dim + overlay text */
.test-card.soon > * {
  filter: blur(2px);
  opacity: 0.35;
  pointer-events: none;        /* block clicks on children */
}

/* dark glass layer */
.test-card.soon::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(7, 10, 34, 0.55);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  z-index: 50;
}

/* centered label */
.test-card.soon::after {
  content: "Coming Soon";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #fff;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 22px;
  text-shadow: 0 2px 8px rgba(0,0,0,0.35);
  z-index: 60;
}

.footer {
  background-color: #1A237E;
  color: white;
  padding: 6px 14px;
  border-radius: 6px;
  font-size: 13px;
  display: inline-block;
  margin-top: 10px;
  text-align: left;
  font-family: "Manrope", sans-serif;
}

/* ============ CTA Buttons ============ */
.course-buttons { display: flex; gap: 10px; }

.enquire-btn, .proceed-btn {
  padding: 8px 16px;
  font-weight: 600;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}
.enquire-btn { background: #081c59; color: #fff; }
.proceed-btn { background: #4caf50; color: #fff; }
.enquire-btn:hover { background: #0b256b; }
.proceed-btn:hover { background: #45a049; }








/* ============ Info / Right Section ============ */
.cat-info-container {
