}

.status-card-clickable {
  cursor: pointer;
}

.status-card-clickable:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.status-card-content {
  display: flex;
  align-items: center;
  width: 100%;
  gap: 16px;
}

.status-card-icon {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
