}

.status-card-value {
  font-size: 28px;
  font-weight: 700;
  color: #1f2937;
  margin: 0 0 4px 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.status-card-subtitle {
  font-size: 13px;
  color: #9ca3af;
  margin: 0;
  line-height: 1.4;
}

.status-card-trend {
  font-size: 14px;
  font-weight: 600;
  padding: 2px 6px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.trend-up {
  color: #16a34a;
  background: #dcfce7;
}

.trend-down {
  color: #dc2626;
  background: #fee2e2;
}

.trend-neutral {
  color: #6b7280;
  background: #f3f4f6;
}

/* Variants */
.status-card-primary .status-card-icon {
  background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
}

.status-card-success .status-card-icon {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
}

.status-card-warning .status-card-icon {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
}

.status-card-danger .status-card-icon {
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
}

.status-card-info .status-card-icon {
  background: linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%);
}

/* Loading skeleton */
.status-card-loading {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  cursor: default;
}

.status-card-loading:hover {
  transform: none;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.status-card-skeleton {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
}

.skeleton-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
}

.skeleton-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.skeleton-title {
  height: 12px;
  width: 60%;
  border-radius: 6px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
}

.skeleton-value {
  height: 20px;
  width: 40%;
  border-radius: 6px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
}

.skeleton-subtitle {
  height: 10px;
  width: 80%;
  border-radius: 6px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
}

@keyframes skeleton-loading {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* Responsive */
@media (max-width: 768px) {
  .status-card {
    padding: 16px;
    min-height: 100px;
  }

  .status-card-content {
    gap: 12px;
  }

  .status-card-icon {
    width: 40px;
    height: 40px;
    font-size: 20px;
  }

  .status-card-value {
    font-size: 24px;
  }
}

