.academics-overview {
  padding: 24px;
  max-width: 1400px;
  margin: 0 auto;
  min-height: 100vh;
  background: #f9fafb;
}

.overview-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 32px;
  padding-bottom: 20px;
  border-bottom: 2px solid #e5e7eb;
}

.overview-header-content h1 {
  font-size: 2rem;
  font-weight: 700;
  color: #1f2937;
  margin: 0 0 8px 0;
}

.overview-header-content p {
  color: #6b7280;
  font-size: 1.1rem;
  margin: 0;
}

.overview-header-actions {
  display: flex;
  gap: 12px;
}

.btn {
  padding: 10px 16px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 2px solid transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  text-decoration: none;
}

.btn-primary {
  background: #3b82f6;
  color: white;
  border-color: #3b82f6;
}

.btn-primary:hover {
  background: #2563eb;
  border-color: #2563eb;
  transform: translateY(-1px);
}

.btn-primary:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* KPI Grid */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 40px;
}

/* Batch Overview Section */
.batch-overview-section,
.quick-stats-section {
  margin-bottom: 40px;
}

.section-header {
  margin-bottom: 24px;
}

.section-header h2 {
  font-size: 1.5rem;
  font-weight: 600;
  color: #1f2937;
  margin: 0 0 8px 0;
}

.section-header p {
  color: #6b7280;
  margin: 0;
}

.batch-chips-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 16px;
}

/* Batch Chip Skeleton */
.batch-chip-skeleton {
  background: white;
  border: 2px solid #e5e7eb;
  border-radius: 12px;
  padding: 12px;
  min-width: 140px;
}

.skeleton-header {
  height: 16px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
  border-radius: 4px;
  margin-bottom: 8px;
  width: 80%;
}

.skeleton-subject {
  height: 20px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
  border-radius: 10px;
  margin-bottom: 6px;
  width: 60%;
}

.skeleton-meta {
  height: 12px;
  background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
  border-radius: 4px;
  width: 90%;
}

@keyframes skeleton-loading {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 60px 20px;
  background: white;
  border: 2px dashed #e5e7eb;
  border-radius: 16px;
  color: #6b7280;
}

.empty-state svg {
  margin-bottom: 16px;
  color: #9ca3af;
}

.empty-state h3 {
  font-size: 1.25rem;
  font-weight: 600;
  color: #374151;
  margin: 0 0 8px 0;
}

.empty-state p {
  margin: 0 0 20px 0;
  color: #6b7280;
}

/* Quick Stats */
.quick-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
}

.quick-stat-card {
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 16px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  transition: all 0.2s ease;
}

.quick-stat-card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  transform: translateY(-1px);
}

.quick-stat-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  flex-shrink: 0;
}

.quick-stat-content {
  flex: 1;
}

.quick-stat-content h3 {
  font-size: 16px;
  font-weight: 600;
  color: #1f2937;
  margin: 0 0 4px 0;
}

.quick-stat-content p {
  font-size: 14px;
  color: #6b7280;
  margin: 0;
}

.trend-positive {
  color: #16a34a !important;
  font-weight: 600;
}

.trend-negative {
  color: #dc2626 !important;
  font-weight: 600;
}

/* Responsive Design */
@media (max-width: 1024px) {
  .academics-overview {
    padding: 20px;
  }

  .overview-header {
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
  }

  .overview-header-actions {
    justify-content: flex-start;
  }

  .kpi-grid {
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 16px;
  }
}

@media (max-width: 768px) {
  .academics-overview {
    padding: 16px;
  }

  .overview-header-content h1 {
    font-size: 1.75rem;
  }

  .overview-header-content p {
    font-size: 1rem;
  }

  .kpi-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .batch-chips-grid {
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px;
  }

  .quick-stats-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .quick-stat-card {
    padding: 16px;
  }

  .quick-stat-icon {
    width: 40px;
    height: 40px;
    font-size: 20px;
  }
}

@media (max-width: 480px) {
  .section-header h2 {
    font-size: 1.25rem;
  }

  .empty-state {
    padding: 40px 16px;
  }

  .batch-chips-grid {
    grid-template-columns: 1fr;
  }
}

/* Focus states for accessibility */
.batch-chip:focus,
.btn:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Animation for loading states */
.loading-enter {
  opacity: 0;
  transform: translateY(10px);
}

.loading-enter-active {
  opacity: 1;
  transform: translateY(0);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  .quick-stat-card {
    border-width: 2px;
  }

  .empty-state {
    border-width: 3px;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  .quick-stat-card,
  .btn-primary,
  .batch-chip-skeleton * {
    transition: none;
    animation: none;
  }
}

