      },
      selectedOptionIndex: {
        type: Number,
        default: null, // For unattempted
      },
      isCorrect: Boolean,
      marksEarned: Number
    }
  ],
  totalScore: {
    type: Number,
    default: 0,
  },
  attemptedAt: {
    type: Date,
    default: Date.now,
  }
}, { timestamps: true });

module.exports = mongoose.models.Response || mongoose.model("Response", responseSchema);

