frontend/src/pages/Student/Onboarding/St.content:
.onboarding-page {
  min-height: 100vh;
  background: linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px 20px;
}

.onboarding-container {
  max-width: 600px;
  width: 100%;
  background: white;
  border-radius: 20px;
  padding: 40px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);
}

.onboarding-header {
  text-align: center;
  margin-bottom: 30px;
}

.onboarding-logo {
  width: 60px;
  height: auto;
  margin-bottom: 15px;
}

.onboarding-header h1 {
  font-size: 24px;
  font-weight: 700;
  color: #1a1a2e;
  margin: 0 0 8px 0;
}

.onboarding-header p {
  font-size: 14px;
  color: #64748b;
  margin: 0;
}

.progress-bar {
  margin-bottom: 30px;
  position: relative;
}

.progress-steps {
  display: flex;
  justify-content: space-between;
  position: relative;
  z-index: 1;
}

.progress-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.step-circle {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #e2e8f0;
  color: #64748b;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  transition: all 0.3s;
}

.progress-step.active .step-circle {
  background: linear-gradient(135deg, #ff6b35 0%, #f7931e 100%);
  color: white;
}

.progress-step.completed .step-circle {
  background: #10b981;
  color: white;
}

.step-label {
  font-size: 12px;
  color: #64748b;
  font-weight: 500;
}

.progress-step.active .step-label {
  color: #1a1a2e;
}

.progress-line {
  position: absolute;
  top: 20px;
  left: 60px;
  right: 60px;
  height: 4px;
  background: #e2e8f0;
  border-radius: 2px;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(135deg, #ff6b35 0%, #f7931e 100%);
  border-radius: 2px;
  transition: width 0.3s;
}

.onboarding-error {
  background: #fff5f5;
  border: 1px solid #feb2b2;
  color: #c53030;
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 13px;
  margin-bottom: 20px;
  text-align: center;
}

.onboarding-form {
  margin-bottom: 30px;
}

.form-step h2 {
  font-size: 18px;
  font-weight: 600;
  color: #1a1a2e;
  margin: 0 0 25px 0;
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-size: 14px;
  font-weight: 500;
  color: #374151;
  margin-bottom: 8px;
}

.form-group input,
.form-group select {
  width: 100%;
  padding: 14px 16px;
  border: 2px solid #e2e8f0;
  border-radius: 10px;
  font-size: 15px;
  transition: border-color 0.3s;
  box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: #ff6b35;
}

.form-group input.disabled-input {
  background: #f8fafc;
  color: #64748b;
  cursor: not-allowed;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}

.gender-options {
  display: flex;
  gap: 10px;
}

.gender-btn {
  flex: 1;
  padding: 12px 20px;
  border: 2px solid #e2e8f0;
  background: white;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 500;
  color: #64748b;
  cursor: pointer;
  transition: all 0.3s;
}

.gender-btn:hover {
  border-color: #ff6b35;
}

.gender-btn.active {
  background: linear-gradient(135deg, #ff6b35 0%, #f7931e 100%);
  border-color: #ff6b35;
  color: white;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.category-card {
  padding: 20px;
  border: 2px solid #e2e8f0;
  background: white;
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  transition: all 0.3s;
}

.category-card:hover {
  border-color: #ff6b35;
  transform: translateY(-2px);
}

.category-card.active {
  background: linear-gradient(135deg, #fff7ed 0%, #ffedd5 100%);
  border-color: #ff6b35;
}

.category-icon {
  font-size: 28px;
}

.category-name {
  font-size: 13px;
  font-weight: 600;
  color: #374151;
}

.exam-chips,
.year-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.exam-chip,
.year-chip {
  padding: 10px 20px;
  border: 2px solid #e2e8f0;
  background: white;
  border-radius: 25px;
  font-size: 13px;
  font-weight: 500;
  color: #64748b;
  cursor: pointer;
  transition: all 0.3s;
}

.exam-chip:hover,
.year-chip:hover {
  border-color: #ff6b35;
}

.exam-chip.active,
.year-chip.active {
  background: linear-gradient(135deg, #ff6b35 0%, #f7931e 100%);
  border-color: #ff6b35;
  color: white;
}

.onboarding-actions {
  display: flex;
  justify-content: space-between;
  gap: 15px;
}

.back-btn {
  padding: 14px 30px;
  background: #f8fafc;
  border: 2px solid #e2e8f0;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 500;
  color: #64748b;
  cursor: pointer;
  transition: all 0.2s;
}

.back-btn:hover {
  background: #e2e8f0;
}

.next-btn {
  flex: 1;
  padding: 14px 30px;
  background: linear-gradient(135deg, #ff6b35 0%, #f7931e 100%);
  border: none;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 600;
  color: white;
  cursor: pointer;
  transition: all 0.2s;
}

.next-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(255, 107, 53, 0.35);
}

.next-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

@media (max-width: 600px) {
  .onboarding-container {
    padding: 25px 20px;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .category-grid {
    grid-template-columns: 1fr;
  }

  .progress-line {
    left: 40px;
    right: 40px;
  }
}

frontend/src/pages/mainAdmin/AdminTopbar.content:
import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./AdminTopbar.css";
import { FaUser, FaSignOutAlt, FaCog, FaChevronDown } from "react-icons/fa";

const AdminTopbar = () => {
  const [admin, setAdmin] = useState(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchAdmin = async () => {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      try {
        const res = await axios.get("/api/admin/me", {
          headers: { Authorization: `Bearer ${token}` }
        });
        setAdmin(res.data.admin);
      } catch (err) {
        console.error("Failed to fetch admin", err);
      }
    };

    fetchAdmin();
  }, []);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    navigate("/admin/login");
  };

  const getInitials = (name) => {
    if (!name) return 'AD';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  };

  return (
    <div className="admin-topbar">
      <h2 className="topbar-title">Welcome, {admin?.name || 'Admin'}</h2>
      <div className="topbar-actions">
        <input type="text" className="topbar-search" placeholder="Search..." />
        <div className="topbar-profile-wrapper" ref={dropdownRef}>
          <button 
            className="topbar-profile-btn"
            onClick={() => setDropdownOpen(!dropdownOpen)}
          >
            {admin?.profilePic ? (
              <img 
                src={admin.profilePic} 
                alt={admin.name || 'Admin'} 
                className="topbar-avatar"
              />
            ) : (
              <div className="topbar-avatar-placeholder">
                {getInitials(admin?.name)}
              </div>
            )}
            <span className="topbar-admin-name">{admin?.name || 'Admin'}</span>
            <FaChevronDown className={`dropdown-arrow ${dropdownOpen ? 'open' : ''}`} />
          </button>

          {dropdownOpen && (
            <div className="topbar-dropdown">
              <div className="dropdown-header">
                {admin?.profilePic ? (
                  <img 
                    src={admin.profilePic} 
                    alt={admin.name || 'Admin'} 
                    className="dropdown-avatar"
                  />
                ) : (
                  <div className="dropdown-avatar-placeholder">
                    {getInitials(admin?.name)}
                  </div>
                )}
                <div className="dropdown-info">
                  <span className="dropdown-name">{admin?.name || 'Admin'}</span>
                  <span className="dropdown-email">{admin?.email || ''}</span>
                  <span className="dropdown-role">Administrator</span>
                </div>
              </div>
              <div className="dropdown-divider"></div>
              <button 
                className="dropdown-item"
                onClick={() => {
                  setDropdownOpen(false);
                  navigate("/admin/profile");
                }}
              >
                <FaUser /> My Profile
              </button>
              <button 
                className="dropdown-item"
                onClick={() => {
                  setDropdownOpen(false);
                  navigate("/admin/settings");
                }}
              >
                <FaCog /> Settings
              </button>
              <div className="dropdown-divider"></div>
              <button className="dropdown-item logout" onClick={handleLogout}>
                <FaSignOutAlt /> Logout
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdminTopbar;

backend/routes/topperFeedbackRoutes.js.content:
const express = require("express");
const multer = require("multer");
const path = require("path");
const fs = require("fs");
const TopperFeedback = require("../models/TopperFeedback");
const { adminAuth } = require("../middleware/authMiddleware");

const router = express.Router();

const uploadDir = path.join(__dirname, "../uploads/topper-feedback");
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueName = `${Date.now()}-${Math.round(Math.random() * 1e9)}${path.extname(file.originalname)}`;
    cb(null, uniqueName);
  }
});

const upload = multer({
  storage,
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    const allowedTypes = /jpeg|jpg|png|gif|webp/;
    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    const mimetype = allowedTypes.test(file.mimetype);
    if (extname && mimetype) {
      cb(null, true);
    } else {
      cb(new Error("Only image files are allowed"));
    }
  }
});

router.get("/all", async (req, res) => {
  try {
    const { activeOnly } = req.query;
    let query = {};

    if (activeOnly === "true") {
      query.isActive = true;
    }

    const feedbacks = await TopperFeedback.find(query).sort({ order: 1, createdAt: -1 });
    res.status(200).json({ success: true, feedbacks });
  } catch (error) {
    console.error("Error fetching topper feedbacks:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

router.get("/public", async (req, res) => {
  try {
    const feedbacks = await TopperFeedback.find({ isActive: true }).sort({ order: 1, createdAt: -1 });
    res.status(200).json({ success: true, feedbacks });
  } catch (error) {
    console.error("Error fetching public topper feedbacks:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

router.post("/create", adminAuth, upload.single("image"), async (req, res) => {
  try {
    const { studentName, order, isActive } = req.body;

    if (!req.file) {
      return res.status(400).json({ success: false, message: "Image is required" });
    }

    const imageUrl = `/uploads/topper-feedback/${req.file.filename}`;

    const newFeedback = new TopperFeedback({
      imageUrl,
      studentName: studentName || "",
      order: order || 0,
      isActive: isActive !== "false"
    });

    await newFeedback.save();
    res.status(201).json({ 
      success: true, 
      message: "Topper feedback created successfully", 
      feedback: newFeedback 
    });
  } catch (error) {
    console.error("Error creating topper feedback:", error);
    res.status(500).json({ success: false, message: error.message || "Server Error" });
  }
});

router.put("/update/:id", adminAuth, upload.single("image"), async (req, res) => {
  try {
    const { studentName, order, isActive } = req.body;
    const feedback = await TopperFeedback.findById(req.params.id);

    if (!feedback) {
      return res.status(404).json({ success: false, message: "Topper feedback not found" });
    }

    if (req.file) {
      if (feedback.imageUrl) {
        const oldPath = path.join(__dirname, "..", feedback.imageUrl);
        if (fs.existsSync(oldPath)) {
          fs.unlinkSync(oldPath);
        }
      }
      feedback.imageUrl = `/uploads/topper-feedback/${req.file.filename}`;
    }

    if (studentName !== undefined) feedback.studentName = studentName;
    if (order !== undefined) feedback.order = parseInt(order) || 0;
    if (isActive !== undefined) feedback.isActive = isActive === "true" || isActive === true;

    feedback.updatedAt = Date.now();
    await feedback.save();

    res.status(200).json({ 
      success: true, 
      message: "Topper feedback updated successfully", 
      feedback 
    });
  } catch (error) {
    console.error("Error updating topper feedback:", error);
    res.status(500).json({ success: false, message: error.message || "Server Error" });
  }
});

router.delete("/delete/:id", adminAuth, async (req, res) => {
  try {
    const feedback = await TopperFeedback.findById(req.params.id);

    if (!feedback) {
      return res.status(404).json({ success: false, message: "Topper feedback not found" });
    }

    if (feedback.imageUrl) {
      const imagePath = path.join(__dirname, "..", feedback.imageUrl);
      if (fs.existsSync(imagePath)) {
        fs.unlinkSync(imagePath);
      }
    }

    await feedback.deleteOne();
    res.status(200).json({ success: true, message: "Topper feedback deleted successfully" });
  } catch (error) {
    console.error("Error deleting topper feedback:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

router.patch("/toggle-active/:id", adminAuth, async (req, res) => {
  try {
    const feedback = await TopperFeedback.findById(req.params.id);
    if (!feedback) {
      return res.status(404).json({ success: false, message: "Topper feedback not found" });
    }

    feedback.isActive = !feedback.isActive;
    feedback.updatedAt = Date.now();
    await feedback.save();

    res.status(200).json({ 
      success: true, 
      message: `Feedback ${feedback.isActive ? 'activated' : 'deactivated'} successfully`, 
      feedback 
    });
  } catch (error) {
    console.error("Error toggling feedback status:", error);
    res.status(500).json({ success: false, message: "Server Error" });
  }
});

module.exports = router;

