const express = require("express");
const router = express.Router();

const practiceTestController = require("../controllers/PracticeTestController");
const practiceQuestionController = require("../controllers/PracticeQuestionController");
const studentPracticeResponseController = require("../controllers/StudentPracticeResponseController");
const { authMiddleware } = require("../middleware/authMiddleware");
const { checkPermission } = require("../middleware/permissionMiddleware");

// ==================== ADMIN ROUTES ====================

// Practice Test Management
router.post("/admin/create",
  authMiddleware,
  checkPermission("admin"),
  practiceTestController.createPracticeTest
);

router.get("/admin/all",
  authMiddleware,
  checkPermission("admin"),
  practiceTestController.getAllPracticeTests
);

router.get("/admin/:id",
  authMiddleware,
  checkPermission("admin"),
  practiceTestController.getPracticeTestById
);

router.put("/admin/:id",
  authMiddleware,
  checkPermission("admin"),
  practiceTestController.updatePracticeTest
);

router.delete("/admin/:id",
  authMiddleware,
  checkPermission("admin"),
  practiceTestController.deletePracticeTest
);

router.put("/admin/:id/publish",
  authMiddleware,
  checkPermission("admin"),
  practiceTestController.publishPracticeTest
);

// Question Management
router.post("/admin/:practiceTestId/questions",
  authMiddleware,
  checkPermission("admin"),
  practiceQuestionController.addQuestionToPracticeTest
);

router.get("/admin/:practiceTestId/questions",
  authMiddleware,
  checkPermission("admin"),
  practiceQuestionController.getQuestionsByPracticeTest
);

router.post("/admin/:practiceTestId/questions/bulk",
  authMiddleware,
  checkPermission("admin"),
  practiceQuestionController.bulkUploadQuestions
);

router.put("/admin/questions/:id",
  authMiddleware,
  checkPermission("admin"),
  practiceQuestionController.updateQuestion
);

router.delete("/admin/questions/:id",
  authMiddleware,
  checkPermission("admin"),
  practiceQuestionController.deleteQuestion
);

// ==================== STUDENT ROUTES ====================

// Practice Test Access
router.get("/student/published", 
  authMiddleware, 
  practiceTestController.getPublishedPracticeTests
);

router.get("/student/:id", 
  authMiddleware, 
  practiceTestController.getPracticeTestForStudent
);

router.get("/student/:practiceTestId/questions", 
  authMiddleware, 
  practiceQuestionController.getQuestionsForTest
);

// Test Taking
router.post("/student/:practiceTestId/start", 
  authMiddleware, 
  studentPracticeResponseController.startPracticeTest
);

router.put("/student/:practiceTestId/questions/:questionId/response", 
  authMiddleware, 
  studentPracticeResponseController.saveResponse
);

router.put("/student/:practiceTestId/switch-section", 
  authMiddleware, 
  studentPracticeResponseController.switchSection
);

router.post("/student/:practiceTestId/submit", 
  authMiddleware, 
  studentPracticeResponseController.submitTest
);

// Results and History
router.get("/student/:practiceTestId/result", 
  authMiddleware, 
  studentPracticeResponseController.getTestResult
);

router.get("/student/history", 
  authMiddleware, 
  studentPracticeResponseController.getStudentTestHistory
);

module.exports = router;

backend/models/StudyMaterial.js.content:
const mongoose = require('mongoose');

const studyMaterialSchema = new mongoose.Schema({
  title: {
    type: String,
    required: true,
    trim: true
  },
  description: {
    type: String,
    trim: true
  },
  subject: {
    type: String,
    required: true,
    enum: ['Quantitative Aptitude', 'Verbal Ability', 'Data Interpretation', 'Logical Reasoning', 'General Knowledge', 'All Subjects']
  },
  category: {
    type: String,
    required: true,
    enum: ['Study Materials', 'Video Lectures', 'Previous Year Papers'],
    default: 'Study Materials'
  },
  type: {
    type: String,
    required: true,
    enum: ['PDF', 'Video', 'Practice Sets', 'Notes', 'Other']
  },
  fileName: {
    type: String,
    required: true
  },
  filePath: {
    type: String,
    required: true
  },
  fileSize: {
    type: String, // e.g., "5.2 MB"
  },
  downloadCount: {
    type: Number,
    default: 0
  },
  isActive: {
    type: Boolean,
    default: true
  },
  courseId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Course',
    required: false
  },
  uploadedBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Admin',
    required: true
  },
  tags: [{
    type: String,
    trim: true
  }],
  createdAt: {
    type: Date,
    default: Date.now
  },
  updatedAt: {
    type: Date,
    default: Date.now
  }
});

// Update the updatedAt field before saving
studyMaterialSchema.pre('save', function(next) {
  this.updatedAt = Date.now();
  next();
});

// Virtual for formatted file size
studyMaterialSchema.virtual('formattedSize').get(function() {
  return this.fileSize || '0 MB';
});

// Virtual for download count text
studyMaterialSchema.virtual('downloadText').get(function() {
  return `${this.downloadCount} downloads`;
});

// Instance method to increment download count
studyMaterialSchema.methods.incrementDownload = function() {
  this.downloadCount += 1;
  return this.save();
};

// Static method to find materials by subject
studyMaterialSchema.statics.findBySubject = function(subject) {
  return this.find({ subject, isActive: true }).populate('uploadedBy', 'name');
};

// Static method to find materials by type
studyMaterialSchema.statics.findByType = function(type) {
  return this.find({ type, isActive: true }).populate('uploadedBy', 'name');
};

const StudyMaterial = mongoose.model('StudyMaterial', studyMaterialSchema);

module.exports = StudyMaterial;

