/* --- DESKTOP HOVER ZOOM FOR SCORECARDS --- */
@media (min-width: 1025px) {
  .scorecard-grid {
    overflow: visible;              /* zoom pe clipping na ho */
  }

  .student-card.small {
    position: relative; 
    overflow: visible;              /* image bahar aa sake */
    transition: transform 0.25s ease, box-shadow 0.25s ease;
    will-change: transform;
  }

  /* Hover par card ko thoda elevate karo */
  .student-card.small:hover {
    z-index: 5;
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(0,0,0,0.12);
  }

  /* Image ko smoothly zoom karna */
  .student-card.small .student-scorecard {
    transition: transform 0.25s ease, filter 0.25s ease;
    transform-origin: center center;
    will-change: transform;
    display: block;
  }

  /* Actual zoom */
  .student-card.small:hover .student-scorecard {
    transform: scale(1.650);         /* need ho to 1.25 bhi kar sakte ho */
    filter: none;
  }
}

/* Optional: thoda crisp dikhane ke liye (hi-res images me helpful) */
.student-card.small .student-scorecard {
  image-rendering: -webkit-optimize-contrast;
}

.scorecard-loading {
  text-align: center;
  padding: 60px 20px;
  font-size: 18px;
  color: #666;
  font-family: "Manrope", sans-serif;
}

.no-scorecards {
  text-align: center;
  padding: 60px 20px;
  font-size: 16px;
  color: #888;
  font-family: "Manrope", sans-serif;
  grid-column: 1 / -1;
}








.tss-demo-form select {
  padding: 4px 5px;
  font-size: 14px;
  font-family: "Manrope", sans-serif;
  border: 1px solid #ccc;
  border-radius: 6px;
  width: 100%;
  box-sizing: border-box;
  height: 42px; /* same as input */
  line-height: 42px; /* centers text vertically */
  background-color: #fff;
  color: #333;
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, #555 50%),
                    linear-gradient(135deg, #555 50%, transparent 50%);
  background-position: calc(100% - 20px) center,
                       calc(100% - 15px) center;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  cursor: pointer;
}

/* On focus highlight same as input */
.tss-demo-form select:focus,
.tss-demo-form input:focus {
  outline: none;
  border-color: #ee6a4d;
  box-shadow: 0 0 0 2px rgba(238, 106, 77, 0.2);
}

