                <option value="online">Online</option>
                <option value="Offline">Offline</option>
              </select>
              <button type="submit" disabled={sending}>
                {sending ? "Submitting..." : "Submit"}
              </button>

              {status && (
                <p style={{ marginTop: 8, textAlign: "center", color: "#000" }}>
                  {status}
                </p>
