/* eslint-disable no-console */

// Fix DNS resolution for IPv4 (required for Karix API in Replit environment)
const dns = require("dns");
dns.setDefaultResultOrder("ipv4first");

const fs = require("fs");
const path = require("path");
const express = require("express");
const mongoose = require("mongoose");
const cors = require("cors");
const dotenv = require("dotenv");
const bodyParser = require("body-parser");
const helmet = require("helmet");
const xss = require("xss-clean");
const mongoSanitize = require("express-mongo-sanitize");
const rateLimit = require("express-rate-limit");
const multer = require("multer");

const envPath = path.join(__dirname, ".env");
dotenv.config({ path: envPath });


/* -------------------- Environment Debug -------------------- */
console.log("🔍 Environment Debug:");
console.log("NODE_ENV:", process.env.NODE_ENV);
console.log("MONGO_URI exists:", !!process.env.MONGO_URI);
console.log("MONGO_URI length:", process.env.MONGO_URI ? process.env.MONGO_URI.length : 0);
console.log("🔑 RAZORPAY_KEY_ID exists:", !!process.env.RAZORPAY_KEY_ID);
console.log("🔑 RAZORPAY_KEY_ID value:", process.env.RAZORPAY_KEY_ID ? process.env.RAZORPAY_KEY_ID.substring(0, 15) + "..." : "NOT SET");
console.log("🔑 RAZORPAY_KEY_SECRET exists:", !!process.env.RAZORPAY_KEY_SECRET);
console.log("🔑 RAZORPAY_KEY_SECRET length:", process.env.RAZORPAY_KEY_SECRET ? process.env.RAZORPAY_KEY_SECRET.length : 0);

/* -------------------- DB Connection -------------------- */
const Connection = require("./dbConnection");
Connection();

/* -------------------- App Init -------------------- */
const app = express();
app.set("trust proxy", 1); // for fly.dev / proxies

/* -------------------- Security / Parsers -------------------- */
// Configure helmet with proper CSP for development
const isDev = process.env.NODE_ENV === 'development';
app.use(helmet({
  contentSecurityPolicy: isDev ? false : {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "https://checkout.razorpay.com", "https://maxcdn.bootstrapcdn.com"],
      styleSrc: ["'self'", "'unsafe-inline'", "https://maxcdn.bootstrapcdn.com"],
      imgSrc: ["'self'", "data:", "https:", "http:"],
      connectSrc: ["'self'", "https:", "http:"],
    }
  },
  crossOriginEmbedderPolicy: false,
  crossOriginOpenerPolicy: false,
  crossOriginResourcePolicy: { policy: "cross-origin" },
}));
app.use(xss());
app.use(mongoSanitize());
app.use(express.json({ limit: "10mb" }));
app.use(bodyParser.json({ limit: "10mb" }));
app.use(bodyParser.urlencoded({ limit: "10mb", extended: true }));

/* -------------------- Optional Auth (safe fallback) -------------------- */
let optionalAuth;
try {
  ({ optionalAuth } = require("./middleware/authMiddleware"));
  if (typeof optionalAuth !== "function") throw new Error("optionalAuth not a function");
} catch (e) {
  console.log("⚠️ optionalAuth not found/invalid, using safe stub.", e.message);
  optionalAuth = (req, _res, next) => next();
}

/* -------------------- Rate Limiter (API scope) -------------------- */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: process.env.NODE_ENV === "production" ? 3000 : 1000000,
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req, _res) => (req.user && req.user.id) || req.ip,
  skip: (req, _res) => {
    if (process.env.NODE_ENV !== "production") return true;
    const url = req.originalUrl || req.path || "";
    if (url.startsWith("/api/health") || url.startsWith("/api/test")) return true;
    if (req.method === "GET" && (url.startsWith("/api/live-classes") || url.includes("/live-classes"))) return true;
    if (req.method === "GET" && url.startsWith("/api/courses/student/published-courses")) return true;
    if (req.method === "GET" && (url === "/api/courses" || url.startsWith("/api/courses?"))) return true;
    return false;
  },
  message: "Too many requests from this client, please try again after 15 minutes.",
});
app.use("/api", optionalAuth, limiter);

/* -------------------- CORS -------------------- */
const allowedOrigins = [
  "http://localhost:3000",
  "http://localhost:3001",
  "http://localhost:3001/",
  "http://localhost:3002",
   "http://localhost:5000",
  "http://localhost:5001",
  "http://127.0.0.1:3000",
  "https://tathagat.satyaka.in",
  "https://602013ebf633402e8096c9cab19561d7-38235a13d63b4a5991fa93f6f.fly.dev",
  "https://56e17d465c834696b5b3654be57883bc-f85b5f4c5dc640488369d7da4.fly.dev",
];

app.use(
  cors({
    origin: (origin, cb) => {
      // In development, allow all origins including Replit domains
      if (process.env.NODE_ENV !== 'production') {
        return cb(null, true);
      }

      const allowedOrigins = [
        "http://localhost:3000",
        "http://localhost:3001",
        "http://localhost:3001/",
        "http://localhost:3002",
        "http://localhost:5000",
        "http://localhost:5001",
        "http://127.0.0.1:3000",
        "https://tathagat.satyaka.in",
        "https://tathagat.co.in",
        "https://www.tathagat.co.in",
        "https://602013ebf633402e8096c9cab19561d7-38235a13d63b4a5991fa93f6f.fly.dev",
        "https://56e17d465c834696b5b3654be57883bc-f85b5f4c5dc640488369d7da4.fly.dev",
      ];

      if (!origin) return cb(null, true); // Allow Postman / curl
      if (allowedOrigins.includes(origin)) return cb(null, true);
      // Allow any Replit domain
      if (origin && origin.includes('.replit.dev')) return cb(null, true);

      console.log("❌ CORS blocked:", origin);
      return cb(new Error("Not allowed by CORS"));
    },
    credentials: true,
    methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  })
);


// Enquiries
const enquiryRoutes = require("./routes/enquiryRoutes");
app.use("/api/enquiries", enquiryRoutes);

/* -------------------- Static: uploads (ensure dir) -------------------- */
const uploadsDir = path.join(__dirname, "uploads");
if (!fs.existsSync(uploadsDir)) {
  fs.mkdirSync(uploadsDir, { recursive: true });
}
app.use("/uploads", (req, res, next) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Cross-Origin-Resource-Policy", "cross-origin");
  res.setHeader("Cache-Control", "public, max-age=3600");
  next();
});
app.use("/uploads", express.static(uploadsDir, { 
  dotfiles: 'deny',
  fallback: true 
}));
// 404 handler for missing uploads - silently fail instead of logging
app.use("/uploads", (_req, res) => {
  res.status(404).type("image/png").send(Buffer.alloc(0));
});

/* -------------------- Health/Test -------------------- */
app.get("/api/health", (_req, res) => {
  res.status(200).json({
    status: "ok",
    message: "Backend server is running",
    timestamp: new Date().toISOString(),
  });
});

app.get("/api/test", (_req, res) => {
  res.status(200).json({
    success: true,
