frontend/src/components/Chat/Chatbox.css.content:
.floating-chat {
  position: fixed;
  bottom: 25px;
  right: 25px;
  z-index: 99999;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

/* 💜 Floating Button */
.chat-toggle {
  background-color: #9747FF;
  border: none;
  border-radius: 50%;
  width: 60px;
  height: 60px;
  cursor: pointer;
  /* box-shadow: 0 0 25px rgba(123, 60, 255, 0.8),
              0 0 50px rgba(123, 60, 255, 0.5); */
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.chat-toggle:hover {
  transform: scale(1.08);
}

.chat-icon-img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}

.close-icon {
  color: white;
  font-size: 36px;
  line-height: 0;
}

/* ⚪ Chat Menu Box */
.chat-options {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
  transition: all 0.35s ease;
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.15);
  padding: 12px 0;
  margin-bottom: 12px;
  width: 240px;
  overflow: hidden;
}

.chat-options.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

/* 🧩 Each Option (Text Left + Icon Right) */
.chat-option {
  display: flex;
  flex-direction: row;
  justify-content: space-between; /* text left, icon right */
  align-items: center;
  text-decoration: none;
  padding: 12px 18px;
  color: #222;
  font-size: 15px;
  font-family: "Manrope", sans-serif;
  font-weight: 500;
  transition: background 0.25s;
  gap: 12px; /* space between text & icon */
}

.chat-option:hover {
  background-color: #f5f5f5;
  transform: translateX(2px);
}

/* 🖼️ Right-side Icons */
.chat-img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  margin-left: 8px;
}

/* 🎨 Color accents */
.chat-option.whatsapp .chat-text { color: #25D366; }
.chat-option.telegram .chat-text { color: #0088cc; }
.chat-option.ask .chat-text { color: #ff5c5c; }
.chat-option.call .chat-text { color: #e91e63; }

/* ✨ Smooth animation when opening */
.chat-options.show .chat-option {
  animation: fadeUp 0.3s ease forwards;
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

