import React from 'react';
import { useNavigate } from 'react-router-dom';

const StudentLoginButton = () => {
  const navigate = useNavigate();

  const handleQuickLogin = async () => {
    try {
      const response = await fetch('/api/dev/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();

      if (data.success && data.token) {
        // Store auth data
        localStorage.setItem('authToken', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));

        alert('✅ Logged in as Demo Student!');

        // Redirect to student dashboard
        navigate('/student/dashboard');
        window.location.reload(); // Refresh to update authentication state
      } else {
        alert('❌ Login failed');
      }
    } catch (error) {
      console.error('Login error:', error);
      alert('❌ Login error: ' + error.message);
    }
  };

  return (
    <button 
      onClick={handleQuickLogin}
      style={{
        position: 'fixed',
        top: '10px',
        right: '10px',
        zIndex: 9999,
        backgroundColor: '#4CAF50',
        color: 'white',
        border: 'none',
        padding: '10px 15px',
        borderRadius: '5px',
        cursor: 'pointer',
        fontSize: '12px'
      }}
    >
      🔧 Quick Student Login
    </button>
  );
};

export default StudentLoginButton;

backend/models/Discussion.js.content:
const mongoose = require('mongoose');

const discussionSchema = new mongoose.Schema({
  title: {
    type: String,
    required: [true, 'Title is required'],
    trim: true,
    maxlength: [200, 'Title cannot exceed 200 characters']
  },
  content: {
    type: String,
    required: [true, 'Content is required'],
    trim: true
  },
  category: {
    type: String,
    enum: ['general', 'quantitative-aptitude', 'verbal-ability', 'data-interpretation', 'logical-reasoning', 'current-affairs', 'technical'],
    default: 'general'
  },
  tags: [{
    type: String,
    trim: true
  }],
  askedBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true
  },
  status: {
    type: String,
    enum: ['pending', 'approved', 'rejected', 'resolved'],
    default: 'pending'
  },
  priority: {
    type: String,
    enum: ['low', 'medium', 'high', 'urgent'],
    default: 'medium'
  },
  isPublished: {
    type: Boolean,
    default: false
  },
  isPinned: {
    type: Boolean,
    default: false
  },
  views: {
    type: Number,
    default: 0
  },
  upvotes: [{
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  }],
  downvotes: [{
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  }],
  replies: [{
    type: mongoose.Schema.Types.ObjectId,
    ref: 'DiscussionReply'
  }],
  moderatedBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Admin'
  },
  moderationNote: {
    type: String,
    trim: true
  },
  moderatedAt: {
    type: Date
  },
  resolvedAt: {
    type: Date
  },
  resolvedBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  }
}, {
  timestamps: true
});

// Index for better query performance
discussionSchema.index({ askedBy: 1, createdAt: -1 });
discussionSchema.index({ status: 1, isPublished: 1 });
discussionSchema.index({ category: 1, createdAt: -1 });
discussionSchema.index({ tags: 1 });

// Virtual for reply count
discussionSchema.virtual('replyCount').get(function() {
  return this.replies.length;
});

// Virtual for upvote count
discussionSchema.virtual('upvoteCount').get(function() {
  return this.upvotes.length;
});

// Virtual for downvote count
discussionSchema.virtual('downvoteCount').get(function() {
  return this.downvotes.length;
});

module.exports = mongoose.model('Discussion', discussionSchema);

backend/routes/batchesAdmin.js.content:
const express = require('express');
const router = express.Router();
const Batch = require('../models/Batch');
const Session = require('../models/Session');
const Course = require('../models/course/Course');
const { adminAuth } = require('../middleware/authMiddleware');

// All endpoints admin-auth
router.use(adminAuth);

router.get('/batches', async (_req, res) => {
  const items = await Batch.find({}).sort({ updatedAt: -1 }).populate('courseIds','name');
  res.json({ success:true, items });
});

router.post('/batches', async (req, res) => {
  const { name, currentSubject='A', courseIds=[] } = req.body;
  const item = await Batch.create({ name, currentSubject, courseIds });
  res.status(201).json({ success:true, item });
});

router.patch('/batch/:id', async (req, res) => {
  const { currentSubject, courseIds } = req.body;
  const patch = {};
  if (currentSubject) patch.currentSubject = currentSubject;
  if (courseIds) patch.courseIds = courseIds;
  const item = await Batch.findByIdAndUpdate(req.params.id, patch, { new:true });
  res.json({ success:true, item });
});

router.post('/sessions', async (req, res) => {
  const { batchId, subject, startAt, endAt, joinUrl } = req.body;
  if (!batchId || !subject || !startAt || !endAt || !joinUrl) return res.status(400).json({ success:false, message:'Missing fields' });
  const batch = await Batch.findById(batchId);
  if (!batch) return res.status(404).json({ success:false, message:'Batch not found' });
  const item = await Session.create({ batchId, subject, startAt, endAt, joinUrl });
  res.status(201).json({ success:true, item });
});

router.patch('/sessions/:id', async (req, res) => {
  const item = await Session.findByIdAndUpdate(req.params.id, req.body, { new:true });
  res.json({ success:true, item });
});

module.exports = router;

frontend/src/pages/mainAdmin/CourseConte.content:
import React, { useEffect, useState } from "react";
import axios from "axios";
import AdminLayout from "../AdminLayout/AdminLayout";
import "./CourseContentManager.css";
import { FaEdit, FaTrash, FaCopy } from "react-icons/fa";
import ChapterTab from "./ChapterTab/ChapterTab";
import TopicTab from "./TopicTab/TopicTab";
import AddTest from "./AddTest/AddTest";
import AddQuestion from "./AddQuestion/AddQuestion";
import BulkQuestionUpload from "./BulkQuestionUpload/BulkQuestionUpload";


const CourseContentManager = () => {
  const [courses, setCourses] = useState([]);
  const [selectedCourseId, setSelectedCourseId] = useState("");
  const [subjects, setSubjects] = useState([]);
  const [subjectName, setSubjectName] = useState("");
  const [editingSubject, setEditingSubject] = useState(null);
  const [editSubjectName, setEditSubjectName] = useState("");
  const [activeTab, setActiveTab] = useState("subject");

  // Copy subject modal state
  const [copyingSubject, setCopyingSubject] = useState(null);
  const [targetCourseId, setTargetCourseId] = useState("");
  const [isCopying, setIsCopying] = useState(false);

  // ✅ Fetch all courses for dropdown
  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const token = localStorage.getItem("adminToken");
        const res = await axios.get("/api/courses", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setCourses(res.data.courses || []);
      } catch (error) {
        console.error("Error fetching courses", error);
      }
    };
    fetchCourses();
  }, []);

  // ✅ Fetch subjects when course selected
useEffect(() => {
  if (!selectedCourseId) return;
  const fetchSubjects = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const res = await axios.get(
        `/api/subjects/${selectedCourseId}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setSubjects(res.data.subjects || []);
    } catch (error) {
      console.error("Error fetching subjects", error);
    }
  };
  fetchSubjects();
}, [selectedCourseId]);


  // ✅ Handle subject add
  const handleAddSubject = async () => {
    if (!subjectName || !selectedCourseId) return alert("Fill all fields!");
    try {
      const token = localStorage.getItem("adminToken");
      const res = await axios.post(
        "/api/subjects",
        {
          name: subjectName,
          courseId: selectedCourseId,
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      alert("✅ Subject added!");
      console.log("Sending:", {
        courseId: selectedCourseId,
        name: subjectName,
      });

      setSubjectName("");
      // Force re-fetch all subjects for the selected course
      //   const refetch = async () => {
      //     const token = localStorage.getItem("adminToken");
      //     const res = await axios.get(
      //       `/api/subjects/${selectedCourseId}`,
      //       {
      //         headers: { Authorization: `Bearer ${token}` },
      //       }
      //     );
      //     setSubjects(res.data.subjects || []);
      //   };
      //   refetch();
      fetchSubjects();
    } catch (error) {
      console.error("Add subject failed", error);
      alert("Error adding subject");
    }
  };

  const fetchSubjects = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const res = await axios.get(
        `/api/subjects/${selectedCourseId}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setSubjects(res.data.subjects || []);
    } catch (error) {
      console.error("Error fetching subjects", error);
    }
  };

  const handleDeleteSubject = async (id) => {
    if (!window.confirm("Are you sure you want to delete this subject?"))
      return;
    try {
      const token = localStorage.getItem("adminToken");
      await axios.delete(`/api/subjects/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      alert("Subject deleted ✅");
      fetchSubjects();
    } catch (err) {
      alert("Delete failed");
      console.error(err);
    }
  };

  // Handle copy subject to another course
  const handleCopySubject = async () => {
    if (!targetCourseId) {
      alert("Please select a target course!");
      return;
    }

    setIsCopying(true);
    try {
      const token = localStorage.getItem("adminToken");
      const res = await axios.post(
        `/api/subjects/${copyingSubject._id}/copy`,
        { targetCourseId },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (res.data.success) {
        const { counts, newSubjectName } = res.data.data;
        alert(
          `Subject "${newSubjectName}" copied successfully!\n\n` +
          `Copied:\n` +
          `- ${counts.chapters} Chapters\n` +
          `- ${counts.topics} Topics\n` +
          `- ${counts.tests} Tests\n` +
          `- ${counts.questions} Questions`
        );
        setCopyingSubject(null);
        setTargetCourseId("");
      }
    } catch (err) {
      console.error("Copy failed:", err);
      alert(err.response?.data?.message || "Failed to copy subject");
    } finally {
      setIsCopying(false);
    }
  };

  return (
    <AdminLayout>
      <div className="content-manager">
        <h2 className="page-title">📚 Course Content Manager</h2>

        {/* 🔥 Tabs for Subject & Chapter */}
        <div className="tab-buttons">
          <button
            className={activeTab === "subject" ? "active-tab" : ""}
            onClick={() => setActiveTab("subject")}
          >
            Subjects
          </button>
          <button
            className={activeTab === "chapter" ? "active-tab" : ""}
            onClick={() => setActiveTab("chapter")}
          >
            Chapters
          </button>
          <button
  className={activeTab === "topic" ? "active-tab" : ""}
  onClick={() => setActiveTab("topic")}
>
  Topics
</button>
<button
  className={activeTab === "test" ? "active-tab" : ""}
  onClick={() => setActiveTab("test")}
>
  Tests
</button>
<button
  className={activeTab === "question" ? "active-tab" : ""}
  onClick={() => setActiveTab("question")}
>
  Questions
</button>
<button
  className={activeTab === "bulkUpload" ? "active-tab" : ""}
  onClick={() => setActiveTab("bulkUpload")}
>
  Bulk Upload
</button>


        </div>

        {/* Course Dropdown */}
        <div className="form-group">
          <label>Select Course</label>
          <select
            value={selectedCourseId}
            onChange={(e) => setSelectedCourseId(e.target.value)}
          >
            <option value="">-- Select Course --</option>
            {courses.map((course) => (
              <option key={course._id} value={course._id}>
                {course.name}
              </option>
            ))}
          </select>
        </div>

        {/* Add Subject Form */}
        {selectedCourseId && activeTab === "subject" && (
          <>
            <div className="form-group">
              <label>New Subject Name</label>
              <input
                type="text"
                value={subjectName}
                onChange={(e) => setSubjectName(e.target.value)}
                placeholder="Enter subject name"
              />
              <button className="add-btn" onClick={handleAddSubject}>
                ➕ Add Subject
              </button>
            </div>

            {/* Subjects List */}
            <div className="table-wrapper">
              <h3>📖 Subjects List</h3>
              <table>
                <thead>
                  <tr>
                    <th>Sr.no</th>
                    <th>Subject Name</th>
                    <th>Created</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {subjects.map((sub, idx) => (
                    <tr key={sub._id}>
                      <td>{idx + 1}</td>
                      <td>{sub.name}</td>
                      <td>{new Date(sub.createdAt).toLocaleDateString()}</td>
                      <td className="icon-actions">
                        <FaEdit
                          title="Edit"
                          style={{
                            cursor: "pointer",
                            marginRight: "10px",
                            color: "#007bff",
                          }}
                          onClick={() => {
                            setEditingSubject(sub);
                            setEditSubjectName(sub.name);
                          }}
                        />
                        <FaCopy
                          title="Copy to Another Course"
                          style={{
                            cursor: "pointer",
                            marginRight: "10px",
                            color: "#28a745",
                          }}
                          onClick={() => {
                            setCopyingSubject(sub);
                            setTargetCourseId("");
                          }}
                        />
                        <FaTrash
                          title="Delete"
                          style={{ cursor: "pointer", color: "red" }}
                          onClick={() => handleDeleteSubject(sub._id)}
                        />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {selectedCourseId && activeTab === "chapter" && (
          <ChapterTab selectedCourseId={selectedCourseId} />
        )}

        {selectedCourseId && activeTab === "topic" && (
        <TopicTab />
         )}
{selectedCourseId && activeTab === "test" && (
  <AddTest selectedCourseId={selectedCourseId} subjects={subjects} />
)}

{selectedCourseId && activeTab === "question" && (
  <AddQuestion selectedCourseId={selectedCourseId} subjects={subjects} />
)}

{activeTab === "bulkUpload" && (
  <BulkQuestionUpload />
)}

      </div>
      {editingSubject && (
        <div className="edit-modal">
          <div className="edit-modal-content">
            <h3>Edit Subject</h3>
            <input
              type="text"
              value={editSubjectName}
              onChange={(e) => setEditSubjectName(e.target.value)}
            />
            <button
              onClick={async () => {
                try {
                  const token = localStorage.getItem("adminToken");
                  await axios.put(
                    `/api/subjects/${editingSubject._id}`,
                    {
                      name: editSubjectName,
                    },
                    {
                      headers: { Authorization: `Bearer ${token}` },
                    }
                  );
                  alert("Subject updated ✅");
                  setEditingSubject(null);
                  fetchSubjects(); 
                } catch (err) {
                  console.error("Edit failed", err);
                  alert("Update failed");
                }
              }}
            >
              Update
            </button>
            <button onClick={() => setEditingSubject(null)}>Cancel</button>
          </div>
        </div>
      )}

      {/* Copy Subject Modal */}
      {copyingSubject && (
        <div className="edit-modal">
          <div className="edit-modal-content" style={{ minWidth: '400px' }}>
            <h3>Copy Subject to Another Course</h3>
            <p style={{ marginBottom: '15px', color: '#666' }}>
              Copying: <strong>{copyingSubject.name}</strong>
            </p>
            <p style={{ marginBottom: '10px', fontSize: '14px', color: '#888' }}>
              This will copy all chapters, topics, tests, and questions to the selected course.
            </p>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold' }}>
              Select Target Course:
            </label>
            <select
              value={targetCourseId}
              onChange={(e) => setTargetCourseId(e.target.value)}
              style={{ 
                width: '100%', 
                padding: '10px', 
                marginBottom: '15px',
                borderRadius: '5px',
                border: '1px solid #ccc'
              }}
            >
              <option value="">-- Select Course --</option>
              {courses
                .filter(c => c._id !== selectedCourseId)
                .map((course) => (
                  <option key={course._id} value={course._id}>
                    {course.name}
                  </option>
                ))}
            </select>
            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
              <button
                onClick={handleCopySubject}
                disabled={isCopying || !targetCourseId}
                style={{
                  backgroundColor: isCopying ? '#ccc' : '#28a745',
                  color: 'white',
                  padding: '10px 20px',
                  border: 'none',
                  borderRadius: '5px',
                  cursor: isCopying ? 'not-allowed' : 'pointer'
                }}
              >
                {isCopying ? 'Copying...' : 'Copy Subject'}
              </button>
              <button 
                onClick={() => {
                  setCopyingSubject(null);
                  setTargetCourseId("");
                }}
                style={{
                  backgroundColor: '#6c757d',
                  color: 'white',
                  padding: '10px 20px',
                  border: 'none',
                  borderRadius: '5px',
                  cursor: 'pointer'
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminLayout>
  );
};

export default CourseContentManager;

