}

.start-test-btn {
  width: calc(100% - 40px);
  margin: 0 20px 20px 20px;
  padding: 14px 24px;
  background: linear-gradient(135deg, #1e3a5f 0%, #2563eb 100%);
  color: white;
  border: none;
  border-radius: 12px;
