  }

  .test-description {
    padding: 10px 14px;
    font-size: 13px;
  }

  .test-meta {
    padding: 0 14px 12px;
    gap: 8px;
  }

  .test-meta span {
    padding: 5px 10px;
    font-size: 12px;
  }

  .start-test-btn {
    width: calc(100% - 28px);
    margin: 0 14px 14px;
    padding: 12px 20px;
    min-height: 46px;
    font-size: 14px;
    border-radius: 10px;
  }

  /* Loading/Empty states */
  .loading-state,
  .empty-state {
    padding: 50px 16px;
    border-radius: 14px;
  }
}

@media (max-width: 400px) {
  .sub-tab {
    flex: 1 1 100%;
  }

  .page-header h1 {
    font-size: 22px;
  }

  .exam-title,
  .subject-title,
  .year-title {
    font-size: 16px;
  }
}

