  font-weight: 600;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}

/* Subject Colors */
.subject-a {
  background: #dbeafe;
  color: #1e40af;
  border-color: #bfdbfe;
}

.subject-b {
  background: #fef3c7;
  color: #d97706;
  border-color: #fed7aa;
}

.subject-c {
  background: #ede9fe;
  color: #7c3aed;
  border-color: #ddd6fe;
}

.subject-d {
  background: #dcfce7;
  color: #16a34a;
  border-color: #bbf7d0;
}

/* Status variations */
.status-done.subject-a { background: #dcfce7; color: #16a34a; border-color: #bbf7d0; }
.status-done.subject-b { background: #dcfce7; color: #16a34a; border-color: #bbf7d0; }
.status-done.subject-c { background: #dcfce7; color: #16a34a; border-color: #bbf7d0; }
.status-done.subject-d { background: #dcfce7; color: #16a34a; border-color: #bbf7d0; }

.status-pending.subject-a { background: #f3f4f6; color: #6b7280; border-color: #e5e7eb; }
.status-pending.subject-b { background: #f3f4f6; color: #6b7280; border-color: #e5e7eb; }
.status-pending.subject-c { background: #f3f4f6; color: #6b7280; border-color: #e5e7eb; }
.status-pending.subject-d { background: #f3f4f6; color: #6b7280; border-color: #e5e7eb; }

/* Sizes */
.size-small {
  padding: 4px 8px;
  font-size: 11px;
}

.size-large {
  padding: 8px 16px;
  font-size: 14px;
}

/* Interactive */
.subject-chip.interactive {
  cursor: pointer;
}

.subject-chip.interactive:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.subject-chip.interactive:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Count badge */
.subject-chip-count {
  background: rgba(255, 255, 255, 0.8);
  color: inherit;
  padding: 2px 6px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
  margin-left: 4px;
}

/* Status Chips */
.status-chip {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 12px;
  font-weight: 500;
  font-size: 12px;
  text-transform: capitalize;
  border: 1px solid transparent;
}

.status-success {
  background: #dcfce7;
  color: #16a34a;
  border-color: #bbf7d0;
}

.status-warning {
  background: #fef3c7;
  color: #d97706;
  border-color: #fed7aa;
}

.status-danger {
  background: #fee2e2;
  color: #dc2626;
  border-color: #fecaca;
}

.status-primary {
  background: #dbeafe;
  color: #1e40af;
  border-color: #bfdbfe;
}

.status-neutral {
  background: #f3f4f6;
  color: #6b7280;
  border-color: #e5e7eb;
}

/* Batch Chips */
.batch-chip {
  background: white;
  border: 2px solid #e5e7eb;
  border-radius: 12px;
  padding: 12px;
  transition: all 0.2s ease;
  min-width: 140px;
}

.batch-chip.interactive {
  cursor: pointer;
}

.batch-chip.interactive:hover,
.batch-chip.active {
  border-color: #3b82f6;
  box-shadow: 0 2px 8px rgba(59, 130, 246, 0.1);
}

.batch-chip.interactive:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.batch-chip-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.batch-chip-name {
  font-weight: 600;
  color: #1f2937;
  font-size: 14px;
}

.batch-chip-meta {
  font-size: 12px;
  color: #6b7280;
}

/* Responsive */
@media (max-width: 768px) {
  .subject-chip {
    padding: 4px 8px;
    font-size: 11px;
  }

  .size-small {
    padding: 3px 6px;
    font-size: 10px;
  }

  .batch-chip {
    min-width: 120px;
    padding: 10px;
  }

  .batch-chip-name {
    font-size: 13px;
  }
}

/* Animation for status changes */
.subject-chip, .status-chip {
  animation: chipIn 0.2s ease-out;
}

@keyframes chipIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

backend/models/Payment.js.content:
const mongoose = require("mongoose");

const paymentSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },
    courseId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Course",
      required: true,
    },
    // Razorpay transaction details
    razorpay_order_id: {
      type: String,
      required: true,
    },
    razorpay_payment_id: {
      type: String,
      default: null,
    },
    razorpay_signature: {
      type: String, 
      default: null,
    },
    // Payment details
    amount: {
      type: Number,
      required: true, // Amount in paise
    },
    currency: {
      type: String,
      default: "INR",
    },
    status: {
      type: String,
      enum: ["created", "paid", "failed", "refunded", "pending_offline", "rejected"],
      default: "created",
    },
    // Receipt details
    receiptNumber: {
      type: String,
      unique: true,
      sparse: true, // Only for successful payments
    },
    paymentMethod: {
      type: String,
      enum: ["razorpay", "offline", "manual"],
      default: "razorpay",
    },
    // Metadata
    validityPeriod: {
      type: Number,
      default: 365, // Days
    },
    validityStartDate: {
      type: Date,
      default: Date.now,
    },
    validityEndDate: {
      type: Date,
    },
    // Discounts/Coupons
    originalAmount: {
      type: Number,
    },
    discountAmount: {
      type: Number,
      default: 0,
    },
    couponCode: {
      type: String,
      default: null,
    },
    // Additional details
    notes: {
      type: String,
      default: "",
    },
    isDemo: {
      type: Boolean,
      default: false,
    },
    // Offline payment fields
    offlineSlipFilename: {
      type: String,
      default: null,
    },
    offlineSlipUrl: {
      type: String,
      default: null,
    },
    offlineNote: {
      type: String,
      default: "",
    },
    offlineReviewedAt: {
      type: Date,
    },
    offlineReviewedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Admin",
    },
    uploadedByRole: {
      type: String,
      enum: ["student", "admin", "system"],
      default: "student",
    },
  },
  {
    timestamps: true, // Adds createdAt and updatedAt
  }
);

// Pre-save middleware to set validity end date and receipt number
paymentSchema.pre("save", function (next) {
  // Set validity end date if not set
  if (!this.validityEndDate && this.validityPeriod) {
    this.validityEndDate = new Date(
      this.validityStartDate.getTime() + this.validityPeriod * 24 * 60 * 60 * 1000
    );
  }

  // Generate receipt number for successful payments
  if (this.status === "paid" && !this.receiptNumber) {
    const timestamp = Date.now();
    this.receiptNumber = `RCP${timestamp}${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
  }

  next();
});

// Instance methods
paymentSchema.methods.isExpired = function() {
  return this.validityEndDate && new Date() > this.validityEndDate;
};

paymentSchema.methods.getDaysRemaining = function() {
  if (!this.validityEndDate) return null;
  const today = new Date();
  const diffTime = this.validityEndDate - today;
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

// Static methods
paymentSchema.statics.getUserPayments = function(userId) {
  return this.find({ userId })
    .populate('courseId', 'name description price thumbnail')
    .sort({ createdAt: -1 });
};

paymentSchema.statics.getCoursePayments = function(courseId) {
  return this.find({ courseId, status: 'paid' })
    .populate('userId', 'name email phone')
    .sort({ createdAt: -1 });
};

// Indexes for better performance
paymentSchema.index({ userId: 1, courseId: 1 });
paymentSchema.index({ razorpay_order_id: 1 });
paymentSchema.index({ receiptNumber: 1 });
paymentSchema.index({ status: 1 });
paymentSchema.index({ createdAt: -1 });

module.exports = mongoose.model("Payment", paymentSchema);

frontend/src/pages/Student/OMR/StudentOM.content:
import React, { useEffect, useState } from 'react';
import http from '../../../utils/http';
import '../../../components/LiveClasses/liveClasses.css';

const key = 'student-omr-cache';

const StudentOMRUpload = () => {
  const [rows, setRows] = useState([]);
  const [offline, setOffline] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  useEffect(()=>{ try { setRows(JSON.parse(sessionStorage.getItem(key))||[]); } catch {} }, []);
  useEffect(()=>{ try { sessionStorage.setItem(key, JSON.stringify(rows)); } catch {} }, [rows]);

  const onUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!/pdf|jpg|jpeg|png$/i.test(file.name)) { alert('Only jpg, png, pdf allowed'); return; }
    const form = new FormData(); form.append('file', file); form.append('testId','unknown');
    setSubmitting(true);
    try {
      const r = await http.post('/omr/check', form, { headers: { 'Content-Type': 'multipart/form-data' } });
      setRows([{ ...r.data.result, name: file.name, offline:false }, ...rows]);
      setOffline(false);
    } catch {
      setRows([{ name: file.name, totalQuestions: 0, correct:0, incorrect:0, score:0, offline:true }, ...rows]);
      setOffline(true);
    } finally { setSubmitting(false); e.target.value=''; }
  };

  return (
    <div className="lc-container">
      {offline && <div className="lc-banner">API offline — OMR saved locally.</div>}
      <div className="lc-card lc-section">
        <div className="lc-title">Upload OMR Sheet (jpg/png/pdf)</div>
        <input type="file" accept=".jpg,.jpeg,.png,.pdf" onChange={onUpload} disabled={submitting} />
      </div>
      <div className="lc-card lc-section">
        <table className="lc-table">
          <thead><tr><th>File</th><th>Total</th><th>Correct</th><th>Incorrect</th><th>Score</th></tr></thead>
          <tbody>
            {rows.map((r,idx)=>(
              <tr key={idx}>
                <td>{r.name} {r.offline && <span className="lc-badge local">offline</span>}</td>
                <td>{r.totalQuestions}</td>
                <td>{r.correct}</td>
                <td>{r.incorrect}</td>
                <td>{Math.round(r.score*100)/100}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default StudentOMRUpload;

