  border-radius: 6px;
}

/* Grid list for long sets */
.IPU-grid{
  list-style: disc;
  padding-left: 20px;
  column-gap: 36px;
}
@media (min-width: 900px){
  .IPU-grid{ columns: 2; }
}
@media (min-width: 1280px){
  .IPU-grid{ columns: 3; }
}

/* Links */
.IPU-link{ color:#0b278f; text-decoration: underline; }

/* Mobile */
@media (max-width: 520px){
  .IPU-title{ font-size: 30px; }
  .IPU-h2{ font-size: 22px; }
  .IPU-p, .IPU-list{ font-size: 15px; }
  .IPU-grid{ columns: 1; }
}

frontend/src/pages/Student/Reports/Stude.content:
import React, { useEffect, useState } from 'react';
import { Line, Bar, Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
} from 'chart.js';
import http from '../../../utils/http';
import './StudentReports.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const StudentReports = () => {
  const [loading, setLoading] = useState(true);
  const [summary, setSummary] = useState(null);
  const [attempts, setAttempts] = useState([]);
  const [performanceTrend, setPerformanceTrend] = useState([]);
  const [sectionAnalysis, setSectionAnalysis] = useState([]);
  const [selectedTest, setSelectedTest] = useState(null);
  const [leaderboard, setLeaderboard] = useState(null);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [userRank, setUserRank] = useState(null);
  const [totalParticipants, setTotalParticipants] = useState(0);

  useEffect(() => {
    fetchReportsData();
  }, []);

  const fetchReportsData = async () => {
    try {
      setLoading(true);
      console.log('📊 StudentReports: Fetching reports data...');
      
      const [summaryRes, sectionRes] = await Promise.all([
        http.get('/mock-tests/reports/summary'),
        http.get('/mock-tests/reports/section-analysis')
      ]);

      console.log('📊 Summary response:', summaryRes.data);
      console.log('📊 Section response:', sectionRes.data);

      if (summaryRes.data?.success) {
        setSummary(summaryRes.data.summary);
        setAttempts(summaryRes.data.attempts);
        setPerformanceTrend(summaryRes.data.performanceTrend);
        console.log('📊 Set summary:', summaryRes.data.summary);
      }

      if (sectionRes.data?.success) {
        setSectionAnalysis(sectionRes.data.analysis);
        setUserRank(sectionRes.data.userRank);
        setTotalParticipants(sectionRes.data.totalParticipants);
      }
    } catch (error) {
      console.error('Error fetching reports:', error);
    } finally {
      setLoading(false);
      console.log('📊 Finished loading reports');
    }
  };

  const fetchLeaderboard = async (testId, testName) => {
    try {
      const response = await http.get(`/mock-tests/reports/${testId}/leaderboard`);
      if (response.data?.success) {
        setLeaderboard(response.data);
        setSelectedTest({ id: testId, name: testName });
        setShowLeaderboard(true);
      }
    } catch (error) {
      console.error('Error fetching leaderboard:', error);
    }
  };

  const trendChartData = {
    labels: performanceTrend.map(p => p.testName),
    datasets: [{
      label: 'Score',
      data: performanceTrend.map(p => p.score),
      fill: true,
      backgroundColor: 'rgba(45, 140, 255, 0.1)',
      borderColor: '#2d8cff',
      tension: 0.4,
      pointBackgroundColor: '#2d8cff',
      pointRadius: 5
    }]
  };

  const sectionChartData = {
    labels: sectionAnalysis.map(s => s.section),
    datasets: [{
      label: 'Average Score',
      data: sectionAnalysis.map(s => parseFloat(s.averageScore)),
      backgroundColor: ['#FF6384', '#36A2EB', '#FFCE56'],
      borderWidth: 0
    }]
  };

  const accuracyChartData = {
    labels: sectionAnalysis.map(s => s.section),
    datasets: [{
      label: 'Accuracy %',
      data: sectionAnalysis.map(s => parseFloat(s.averageAccuracy)),
      backgroundColor: ['rgba(255, 99, 132, 0.7)', 'rgba(54, 162, 235, 0.7)', 'rgba(255, 206, 86, 0.7)'],
      borderColor: ['#FF6384', '#36A2EB', '#FFCE56'],
      borderWidth: 2
    }]
  };

  console.log('📊 Render - loading state:', loading, 'summary:', summary ? 'present' : 'null');
  
  if (loading) {
    return (
      <div className="reports-container">
        <div className="loading-state">Loading your reports...</div>
      </div>
    );
  }

  return (
    <div className="reports-container">
      <div className="reports-header">
        <h1>Analysis & Reports</h1>
        <p>Track your mock test performance and compare with top students</p>
      </div>

      <div className="stats-cards-row">
        <div className="stat-card blue">
          <div className="stat-icon">
            <span>📝</span>
          </div>
          <div className="stat-info">
            <h3>{summary?.totalAttempts || 0}</h3>
            <p>Tests Taken</p>
          </div>
        </div>
        <div className="stat-card green">
          <div className="stat-icon">
            <span>📊</span>
          </div>
          <div className="stat-info">
            <h3>{summary?.averageScore || 0}</h3>
            <p>Average Score</p>
          </div>
        </div>
        <div className="stat-card orange">
          <div className="stat-icon">
            <span>🏆</span>
          </div>
          <div className="stat-info">
            <h3>{summary?.bestScore || 0}</h3>
            <p>Best Score</p>
          </div>
        </div>
        <div className="stat-card purple">
          <div className="stat-icon">
            <span>⏱️</span>
          </div>
          <div className="stat-info">
            <h3>{summary?.averageTimeMinutes || 0} min</h3>
            <p>Avg. Time</p>
          </div>
        </div>
      </div>

      <div className="charts-row">
        <div className="chart-card">
          <h3>Performance Trend</h3>
          <div className="chart-container">
            {performanceTrend.length > 0 ? (
              <Line 
                data={trendChartData}
                height={150}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: { legend: { display: false } },
                  scales: {
                    y: { beginAtZero: true, max: 200 }
                  }
                }}
              />
            ) : (
              <div className="empty-chart">No data available yet</div>
            )}
          </div>
        </div>
        <div className="chart-card">
          <h3>Section-wise Performance</h3>
          <div className="chart-container">
            {sectionAnalysis.length > 0 ? (
              <Doughnut 
                data={sectionChartData}
                height={150}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: { position: 'bottom', labels: { boxWidth: 10, font: { size: 10 } } }
                  }
                }}
              />
            ) : (
              <div className="empty-chart">No data available yet</div>
            )}
          </div>
        </div>
        <div className="chart-card">
          <h3>Section Accuracy</h3>
          <div className="chart-container">
            {sectionAnalysis.length > 0 ? (
              <Bar 
                data={accuracyChartData}
                height={150}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: { legend: { display: false } },
                  scales: {
                    y: { beginAtZero: true, max: 100 }
                  }
                }}
              />
            ) : (
              <div className="empty-chart">No data available yet</div>
            )}
          </div>
        </div>
      </div>

      {userRank && (
        <div className="rank-progress-card">
          <h3>Your Overall Ranking</h3>
          <div className="rank-stats">
            <div className="rank-item">
              <span className="rank-value">#{userRank}</span>
              <span className="rank-label">Current Rank</span>
            </div>
            <div className="rank-item">
              <span className="rank-value">{totalParticipants}</span>
              <span className="rank-label">Total Participants</span>
            </div>
            <div className="rank-item">
              <span className="rank-value">{totalParticipants > 0 ? ((1 - (userRank / totalParticipants)) * 100).toFixed(1) : 0}%</span>
              <span className="rank-label">Percentile</span>
            </div>
          </div>
        </div>
      )}

      <div className="comparison-section">
        <h2>Subject-wise Performance vs Top 10</h2>
        <p className="section-subtitle">Compare your scores with top 10 performers in each subject</p>
        <div className="section-stats-row">
          {sectionAnalysis.map(section => (
            <div key={section.section} className={`section-stat-card ${section.section.toLowerCase()}`}>
              <h4>{section.section === 'VARC' ? 'Verbal Ability & Reading Comprehension' : section.section === 'DILR' ? 'Data Interpretation & Logical Reasoning' : section.section === 'QA' ? 'Quantitative Aptitude' : section.section}</h4>
              <div className="section-metrics">
                <div className="metric">
                  <span className="value">{section.averageScore}</span>
                  <span className="label">Your Score</span>
                </div>
                <div className="metric">
                  <span className="value">{section.top10AverageScore || 0}</span>
                  <span className="label">Top 10 Avg</span>
                </div>
                <div className="metric">
                  <span className={`value ${parseFloat(section.scoreDifference) >= 0 ? 'positive' : 'negative'}`}>
                    {parseFloat(section.scoreDifference) >= 0 ? '+' : ''}{section.scoreDifference}
                  </span>
                  <span className="label">Difference</span>
                </div>
              </div>
              <div className="accuracy-comparison">
                <div className="accuracy-bar">
                  <div className="accuracy-label">Your Accuracy: {section.averageAccuracy}%</div>
                  <div className="accuracy-progress">
                    <div className="progress-fill user" style={{width: `${Math.min(100, section.averageAccuracy)}%`}}></div>
                  </div>
                </div>
                <div className="accuracy-bar">
                  <div className="accuracy-label">Top 10 Accuracy: {section.top10AverageAccuracy || 0}%</div>
                  <div className="accuracy-progress">
                    <div className="progress-fill top10" style={{width: `${Math.min(100, section.top10AverageAccuracy || 0)}%`}}></div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="attempts-section">
        <h2>Your Test Attempts</h2>
        {attempts.length === 0 ? (
          <div className="empty-state">
            <p>You haven't taken any mock tests yet.</p>
            <a href="/student/mock-tests" className="start-test-btn">Start a Mock Test</a>
          </div>
        ) : (
          <div className="attempts-table-container">
            <table className="attempts-table">
              <thead>
                <tr>
                  <th>Test Name</th>
                  <th>Score</th>
                  <th>Time Taken</th>
                  <th>Date</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {attempts.map(attempt => (
                  <tr key={attempt._id}>
                    <td>
                      <div className="test-name-cell">
                        <span className="test-name">{attempt.testName}</span>
                        {attempt.seriesName && <span className="series-name">{attempt.seriesName}</span>}
                      </div>
                    </td>
                    <td>
                      <span className="score-badge">{attempt.score}/{attempt.maxScore}</span>
                    </td>
                    <td>{attempt.timeTakenMinutes} min</td>
                    <td>{new Date(attempt.completedAt).toLocaleDateString()}</td>
                    <td>
                      <button 
                        className="action-btn leaderboard-btn"
                        onClick={() => fetchLeaderboard(attempt.testId, attempt.testName)}
                      >
                        Leaderboard
                      </button>
                      <a 
                        href={`/student/mock-test/review/${attempt._id}`}
                        className="action-btn review-btn"
                      >
                        Review
                      </a>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showLeaderboard && leaderboard && (
        <div className="modal-overlay" onClick={() => setShowLeaderboard(false)}>
          <div className="leaderboard-modal" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Top 10 - {selectedTest?.name}</h2>
              <button onClick={() => setShowLeaderboard(false)}>x</button>
            </div>
            <div className="modal-content">
              <div className="leaderboard-stats">
                <div className="lb-stat">
                  <span className="lb-value">{leaderboard.totalParticipants}</span>
                  <span className="lb-label">Total Participants</span>
                </div>
                {leaderboard.currentUserRank && (
                  <div className="lb-stat highlight">
                    <span className="lb-value">#{leaderboard.currentUserRank}</span>
                    <span className="lb-label">Your Rank</span>
                  </div>
                )}
                {leaderboard.currentUserScore !== null && (
                  <div className="lb-stat">
                    <span className="lb-value">{leaderboard.currentUserScore}</span>
                    <span className="lb-label">Your Score</span>
                  </div>
                )}
              </div>
              <table className="leaderboard-table">
                <thead>
                  <tr>
                    <th>Rank</th>
                    <th>Student</th>
                    <th>Score</th>
                    <th>Time</th>
                  </tr>
                </thead>
                <tbody>
                  {leaderboard.topTen.map(student => (
                    <tr key={student.rank} className={student.isCurrentUser ? 'current-user' : ''}>
                      <td>
                        <span className={`rank-badge rank-${student.rank}`}>
                          {student.rank <= 3 ? ['🥇', '🥈', '🥉'][student.rank - 1] : `#${student.rank}`}
                        </span>
                      </td>
                      <td>
                        {student.studentName}
                        {student.isCurrentUser && <span className="you-tag">(You)</span>}
                      </td>
                      <td className="score-cell">{student.score}</td>
                      <td>{student.timeTakenMinutes} min</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentReports;

frontend/src/CoursePurchasepage/Cat2026C.content:
:root{
  --cocp-font:"Manrope","Inter","Segoe UI",system-ui,-apple-system,Roboto,Helvetica,Arial,sans-serif;
  --cocp-weight-heading:700; --cocp-weight-strong:600; --cocp-weight-body:500;
  --cocp-size-title:clamp(22px,2.0vw,28px); --cocp-size-h:clamp(20px,1.9vw,26px);
  --cocp-size-sub:18px; --cocp-size-body:16px; --cocp-size-small:14px; --cocp-line:1.55;
  --cocp-primary:#1A237E; --cocp-accent:#D8583F; --cocp-ink:#1d1d1f; --cocp-ink-2:#111; --cocp-muted:#888; --cocp-border:#999;
}

/* reset */
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:var(--cocp-font);font-size:var(--cocp-size-body);font-weight:var(--cocp-weight-body);line-height:var(--cocp-line);background:#f4f6f8;color:var(--cocp-ink)}
.container{max-width:1600px;width:100%;margin:0 auto}
.row{display:flex;gap:30px}

/* page */
.cocp-page{background:#fff;padding-top:40px}

/* left */
.cocp-left{flex:70%;padding-left:50px}
.cocp-video iframe{width:100%;height:400px;border-radius:10px;border:none;margin-bottom:20px}
.cocp-title{text-transform:uppercase;letter-spacing:.4px;color:var(--cocp-primary);font-size:var(--cocp-size-title);font-weight:var(--cocp-weight-heading);margin-bottom:25px}

/* info grid */
.cocp-info-grid{display:flex;gap:0;margin-bottom:30px;flex-wrap:wrap}
.cocp-info-item{display:flex;align-items:center;gap:10px;min-width:220px;flex:1}
.cocp-ico{font-size:22px;color:#005ae0}
.cocp-label{font-size:var(--cocp-size-small);color:var(--cocp-muted);font-weight:var(--cocp-weight-body)}
.cocp-val{font-size:var(--cocp-size-body);color:var(--cocp-ink-2);font-weight:var(--cocp-weight-strong)}

/* right */
.cocp-right{flex:0 0 30%;display:flex;flex-direction:column;gap:30px}
.cocp-course-info{background:#fff;padding:25px;border-radius:12px;border:1px solid var(--cocp-border);box-shadow:0 0 10px rgba(0,0,0,.05)}
.cocp-course-title{background:#EFF0FF;color:var(--cocp-primary);font-weight:var(--cocp-weight-heading);padding:12px 15px;border-radius:8px;font-size:var(--cocp-size-title);text-align:center;margin-bottom:25px}
.cocp-buy-btn{
  width:100%;
  padding:10px 12px;
  background:#1d0a71;
  color:#fff;
  font-weight:var(--cocp-weight-heading);
  border:none;
  border-radius:8px;
  cursor:pointer;
  font-size:var(--cocp-size-body);
  margin-top:15px;
  transition:background .3s ease
}
.cocp-buy-btn:hover{background:#1b0a66}

.cocp-desc-scroll{max-height:220px;overflow-y:auto;padding-right:5px}
.cocp-desc-scroll::-webkit-scrollbar{width:0;background:transparent}
.cocp-material-box{background:#fff;padding:25px;border:1px solid var(--cocp-border);border-radius:12px;box-shadow:0 0 10px rgba(0,0,0,.05)}
.cocp-material-box h4{font-size:var(--cocp-size-sub);font-weight:var(--cocp-weight-heading);color:#000;margin-bottom:12px;text-align:left}
.cocp-material-list{list-style:disc; text-align:left;padding-left:20px;color:#000;font-size:15px;}
.cocp-material-list li{margin-bottom:8px}

/* tabs */
.cocp-tabs{margin-top:40px}
.cocp-tab-buttons{display:flex;gap:15px;margin-bottom:25px;flex-wrap:wrap}
.cocp-tab-btn{border:2px solid var(--cocp-primary);background:transparent;color:var(--cocp-primary);font-weight:var(--cocp-weight-heading);font-size:var(--cocp-size-body);padding:8px 24px;border-radius:16px;cursor:pointer;transition:.3s}
.cocp-tab-btn:hover{background:#eaeaff}
.cocp-tab-btn.active{background:var(--cocp-primary);color:#fff;border-color:var(--cocp-primary)}

.cocp-tab-content h3,
.cocp-curriculum h3,
.cocp-instructors h3,
.cocp-reviews h3{font-size:var(--cocp-size-h);font-weight:var(--cocp-weight-heading);color:#000;text-align:left;margin-bottom:18px}
.cocp-tab-content p{font-size:var(--cocp-size-body);font-weight:var(--cocp-weight-body);color:#000;text-align:left;margin-bottom:18px}

/* curriculum */
.cocp-curriculum{margin-top:40px}
.cocp-curriculum-item{border:1px solid #ddd;border-radius:10px;margin-bottom:15px;background:#fff;padding:15px 20px;cursor:pointer;transition:all .3s ease}
.cocp-curriculum-item:hover{background:#f9f9ff}
.cocp-curriculum-title{display:flex;justify-content:space-between;font-weight:var(--cocp-weight-heading);font-size:18px;color:var(--cocp-primary)}
.cocp-curriculum-content{margin-top:10px;font-size:var(--cocp-size-body);font-weight:var(--cocp-weight-body);color:#000;text-align:left}
.cocp-arrow{font-size:18px;color:#2f2f2f}

/* instructors */
.cocp-instructor-grid{display:flex;gap:20px;flex-wrap:wrap}
.cocp-instructor-card{flex:1 1 30%;border-radius:15px;overflow:hidden;background:#f0f2ff;box-shadow:0 0 8px rgba(0,0,0,.05);text-align:center;display:flex;flex-direction:column;justify-content:space-between}
.cocp-instructor-img{background:#0c1a66;padding:20px}
.cocp-instructor-img img{width:100%;max-height:250px;object-fit:contain;border-radius:8px}
.cocp-instructor-info{padding:15px;background:#f0f2ff;font-size:var(--cocp-size-body);font-weight:var(--cocp-weight-strong);color:var(--cocp-ink);line-height:1.4;text-align:left}

/* reviews */
.cocp-reviews{margin-top:40px}
.cocp-review-layout{display:flex;flex-direction:column;gap:30px}

.cocp-rating-summary{display:flex;align-items:flex-start;gap:20px}
.cocp-rating-score{font-size:40px;font-weight:var(--cocp-weight-heading);line-height:1}
.cocp-rating-stars{position:relative;display:inline-block;line-height:1;color:orange;font-size:18px;margin:5px 0}
.cocp-stars-outer{color:#ddd}
.cocp-stars-inner{position:absolute;top:0;left:0;width:var(--percent,0%);overflow:hidden;color:orange;white-space:nowrap;pointer-events:none}
.cocp-total-rating{font-size:var(--cocp-size-small);color:#555}

.cocp-rating-bars{flex:1}
.cocp-bar-line{display:flex;align-items:center;font-size:var(--cocp-size-small);margin-bottom:10px}
.cocp-bar-line .cocp-bar{flex:1;height:6px;background:#ddd;margin:0 10px;border-radius:5px;overflow:hidden}
.cocp-bar-line .cocp-fill{background:var(--cocp-primary);height:100%}

.cocp-review-image-box{flex:0 0 55%;background:transparent;display:flex;align-items:center}
.cocp-review-image-box img{width:100%;max-width:600px;height:300px;border-radius:12px;object-fit:contain}

/* extra imgs */
.cocp-reviews-gallery{display:flex;gap:16px;margin-top:18px;flex-wrap:wrap}
.cocp-reviews-gallery img{flex:1 1 calc(33.333% - 11px);max-width:calc(33.333% - 11px);height:240px;object-fit:contain;background:#fff;border:1px solid #e6e6e6;border-radius:12px;box-shadow:0 2px 10px rgba(0,0,0,.05);padding:8px}
@media (max-width:992px){.cocp-reviews-gallery img{flex-basis:calc(50% - 8px);max-width:calc(50% - 8px);height:180px}}

/* journey (optional, not used) */
.cocp-journey{margin-top:40px;display:flex;justify-content:center;background:#080A22}
.cocp-journey-image{width:100%;height:auto;object-fit:cover}

/* mobile */
@media (max-width:768px){
  .row{flex-direction:column;gap:40px}
  .cocp-left{padding-left:0}
  .cocp-video iframe{height:250px}
}

frontend/src/components/AdminUI/TableMin.content:
import React from 'react';
import Card from './Card';

const TableMini = ({ title, columns = [], rows = [] }) => (
  <Card>
    <div style={{marginBottom:8, fontWeight:600}}>{title}</div>
    <div style={{maxHeight: 260, overflow:'auto'}}>
      <table className="table-mini">
        <thead>
          <tr>
            {columns.map((c) => (<th key={c.key}>{c.label}</th>))}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr><td colSpan={columns.length} style={{color:'var(--admin-text-muted)', padding:'16px'}}>No data</td></tr>
          )}
          {rows.map((row, i) => (
            <tr key={i}>
              {columns.map((c) => (<td key={c.key}>{c.render ? c.render(row[c.key], row) : row[c.key]}</td>))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  </Card>
);

export default TableMini;

frontend/src/components/CourseComprasion.content:
.ts-compare-container {
  background: #fff;
  width: 100%;
  padding: 60px;
  overflow-x: auto; /* Ensure table scrolls horizontally on small screens */
}

.ts-compare-heading {
  font-size: 58px;
  font-weight: 400;
  color: #000;
  font-family: 'DM Serif Display', serif;
  text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2);
  text-align: center;
}

.ts-compare-scroll-wrapper {
  max-height: 550px; /* Show ~12-15 rows */
  overflow-y: auto;
  scrollbar-width: none; /* Firefox */
}

.ts-compare-scroll-wrapper::-webkit-scrollbar {
  display: none; /* Chrome, Safari */
}

.ts-compare-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 600px; /* Prevent cramping on very small screens */
}

.ts-compare-header th {
  background: #fff;
  color: #000;
  padding: 10px;
  font-size: 14px;
  font-weight: 800;
  text-align: center;
  border: 1px solid #333;
  position: sticky;
  top: 0;
  z-index: 2;
}

.ts-compare-table th,
.ts-compare-table td {
  border: 1px solid #ddd;
  padding: 10px;
  vertical-align: middle;
  font-size: 14px;
}

.ts-compare-feature-cell {
  font-weight: 700;
  text-align: left;
  padding-left: 12px;
  background-color: #f7f7f7;
}

.ts-compare-value-cell {
  font-weight: 600;
  color: #000;
  background-color: #fff;
  text-align: center;
}

.ts-compare-value-cell.buy-now {
  background-color: green;
  color: white;
  font-weight: bold;
}

.ts-sticky-row {
  position: sticky;
  bottom: 0;
  background: #fff;
  z-index: 1;
}

/* Learn More button styling */
.ts-compare-value-cell.learn-more {
  background-color: red;
  color: white;
  font-weight: bold;
}

/* RESPONSIVE MEDIA QUERIES */
@media (max-width: 1024px) {
  .ts-compare-heading {
    font-size: 42px;
  }
}

@media (max-width: 768px) {
  .ts-compare-container {
    padding: 10px;
  }
  .ts-compare-heading {
    font-size: 32px;
  }
  .ts-compare-table th, 
  .ts-compare-table td {
    font-size: 12px;
    padding: 8px;
  }
}

@media (max-width: 480px) {
  .ts-compare-heading {
    font-size: 24px;
  }
  .ts-compare-table {
    min-width: 500px; /* Let it scroll horizontally */
  }
}

backend/routes/downloadRoutes.js.content:
const express = require('express');
const router = express.Router();
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const { authMiddleware, optionalAuthMiddleware } = require('../middleware/authMiddleware');
const { checkPermission } = require('../middleware/permissionMiddleware');

const {
  createCategory,
  getCategories,
  getAllCategories,
  updateCategory,
  deleteCategory,
  reorderCategories,
  createTest,
  getTests,
  getAllTests,
  getTestById,
  updateTest,
  deleteTest,
  toggleTestStatus,
  reorderTests,
  uploadPdf,
  getPublicCategories,
  getPublicTests,
  getFreeMockTests,
  toggleFreeMockTestStatus,
  updateFreeMockTestDownloadSettings,
  getPublicFreeMockTests
} = require('../controllers/DownloadController');

const uploadsDir = path.join(__dirname, '..', 'uploads', 'downloads');
if (!fs.existsSync(uploadsDir)) {
  fs.mkdirSync(uploadsDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadsDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, uniqueSuffix + '-' + file.originalname.replace(/\s+/g, '_'));
  }
});

const fileFilter = (req, file, cb) => {
  if (file.mimetype === 'application/pdf') {
    cb(null, true);
  } else {
    cb(new Error('Only PDF files are allowed'), false);
  }
};

const upload = multer({ 
  storage, 
  fileFilter,
  limits: { fileSize: 50 * 1024 * 1024 }
});

router.get('/public/categories', getPublicCategories);
router.get('/public/tests', getPublicTests);

router.get('/admin/categories', authMiddleware, getAllCategories);
router.post('/admin/categories', authMiddleware, createCategory);
router.put('/admin/categories/:id', authMiddleware, updateCategory);
router.delete('/admin/categories/:id', authMiddleware, deleteCategory);
router.patch('/admin/categories/reorder', authMiddleware, reorderCategories);

router.get('/admin/tests', authMiddleware, getAllTests);
router.post('/admin/tests', authMiddleware, createTest);
router.get('/admin/tests/:id', authMiddleware, getTestById);
router.put('/admin/tests/:id', authMiddleware, updateTest);
router.delete('/admin/tests/:id', authMiddleware, deleteTest);
router.patch('/admin/tests/:id/status', authMiddleware, toggleTestStatus);
router.patch('/admin/tests/reorder', authMiddleware, reorderTests);
router.post('/admin/tests/:id/upload-pdf', authMiddleware, upload.single('pdf'), uploadPdf);

router.get('/admin/free-mock-tests', authMiddleware, getFreeMockTests);
router.patch('/admin/free-mock-tests/:id/status', authMiddleware, toggleFreeMockTestStatus);
router.patch('/admin/free-mock-tests/:id/settings', authMiddleware, updateFreeMockTestDownloadSettings);

router.get('/public/free-mock-tests', getPublicFreeMockTests);

module.exports = router;

