.lc-field input,.lc-field select,.lc-field textarea{width:100%;padding:8px 10px;border:1px solid #e5e7eb;border-radius:8px;background:#fff;transition:box-shadow .15s,border-color .15s;font-size:14px}
.lc-field input:focus,.lc-field select:focus,.lc-field textarea:focus{outline:none;border-color:#1e40af;box-shadow:0 0 0 3px rgba(30,64,175,.12)}
.lc-section-title{grid-column:1 / -1;margin:8px 0 4px;color:#111;font-weight:600;font-size:14px}
.lc-help{margin-top:4px}
.lc-error{color:#b91c1c}
.lc-form-actions{display:flex;justify-content:flex-end;gap:8px;padding-top:8px;border-top:1px solid #f1f5f9}

/* Utilities */
.lc-header-spaced{margin:8px 0}
.lc-margin-8{margin:8px 0}
.lc-mb-8{margin-bottom:8px}

/* Empty state */
.lc-empty{text-align:center;padding:60px 20px;background:#fff;border:1px solid #e5e7eb;border-radius:12px}
.lc-empty-icon{font-size:48px;margin-bottom:16px;opacity:0.6}
.lc-empty h3{margin:0 0 8px;color:#4b5563;font-size:18px}
.lc-empty p{color:#6b7280;margin:0}

/* Loading state */
.lc-loading{text-align:center;padding:60px 20px}
.lc-spinner{width:40px;height:40px;border:3px solid #e5e7eb;border-top-color:#1e40af;border-radius:50%;animation:spin 1s linear infinite;margin:0 auto 16px}
@keyframes spin{to{transform:rotate(360deg)}}

/* Live class card improvements */
.lc-card.live-now{border-color:#22c55e;box-shadow:0 0 0 2px rgba(34,197,94,.2)}
.lc-course-name{color:#6b7280;font-size:13px;margin-bottom:8px}
.lc-schedule{display:flex;gap:12px;color:#374151;font-size:14px;margin-bottom:6px}
.lc-date{font-weight:600}
.lc-countdown{display:flex;align-items:center;gap:6px;margin-top:8px}
.lc-countdown-icon{font-size:14px}
.lc-btn.disabled{opacity:.5;cursor:not-allowed;background:#f3f4f6;color:#9ca3af}
.lc-btn.active{background:#eef2ff;border-color:#6366f1;color:#4f46e5}
.lc-no-recording{color:#9ca3af;font-size:13px;font-style:italic}
.lc-badge.live{background:#22c55e;color:#fff;border-color:#22c55e;animation:pulse 2s infinite}
.lc-badge.completed{background:#f3f4f6;color:#6b7280;border-color:#d1d5db}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.7}}

/* Modal */
.lc-modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;z-index:100;padding:20px}
.lc-modal{background:#fff;border-radius:16px;width:100%;max-width:500px;max-height:90vh;overflow:auto;box-shadow:0 25px 50px rgba(0,0,0,.25)}
.lc-modal-header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid #e5e7eb}
.lc-modal-header h2{margin:0;font-size:18px}
.lc-modal-body{padding:20px}
.lc-modal-footer{display:flex;gap:8px;flex-wrap:wrap;padding:16px 20px;border-top:1px solid #e5e7eb;background:#f9fafb}
.lc-detail-row{margin-bottom:12px;font-size:14px}
.lc-detail-row strong{display:block;color:#6b7280;font-size:12px;margin-bottom:4px}
.lc-detail-row p{margin:4px 0 0;color:#374151}

/* Course selection grid */
.lc-course-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}
.lc-course-card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;cursor:pointer;transition:all .2s;display:flex;align-items:center;gap:16px}
.lc-course-card:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.1);border-color:#1e40af}
.lc-course-thumbnail{width:80px;height:60px;border-radius:8px;overflow:hidden;flex-shrink:0;background:#f3f4f6}
.lc-course-thumbnail img{width:100%;height:100%;object-fit:cover}
.lc-course-placeholder{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:24px;background:#eef2ff}
.lc-course-info{flex:1;min-width:0}
.lc-course-name-card{margin:0 0 4px;font-size:16px;font-weight:600;color:#111;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.lc-course-type{font-size:12px;color:#6b7280;text-transform:capitalize}
.lc-course-arrow{font-size:20px;color:#9ca3af;transition:color .2s}
.lc-course-card:hover .lc-course-arrow{color:#1e40af}

/* Breadcrumb */
.lc-breadcrumb{display:flex;align-items:center;gap:12px;margin-bottom:16px;padding-bottom:16px;border-bottom:1px solid #e5e7eb}
.lc-back-btn{background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px 16px;cursor:pointer;font-weight:600;color:#374151;transition:all .15s}
.lc-back-btn:hover{background:#f9fafb;border-color:#1e40af;color:#1e40af}
.lc-current-course{font-size:14px;color:#6b7280}

/* Batch name */
.lc-batch-name{color:#8b5cf6;font-size:12px;font-weight:500;margin-bottom:6px}

/* Link coming soon button */
.lc-btn.link-coming-soon{background:#f59e0b;color:#fff;border-color:#f59e0b;cursor:default}
.lc-btn.link-coming-soon:hover{box-shadow:none;background:#f59e0b}

@media (max-width: 768px){
  .lc-filters{flex-direction:column}
  .lc-calendar{grid-template-columns:1fr 1fr}
  .lc-grid{grid-template-columns:1fr}
  .lc-form{grid-template-columns:1fr}
  .lc-table th:last-child,.lc-table td:last-child{min-width:240px}
  .lc-card-actions{grid-template-columns:1fr}
  .lc-modal-footer{flex-direction:column}
  .lc-modal-footer .lc-btn{width:100%}
  .lc-course-grid{grid-template-columns:1fr}
  .lc-breadcrumb{flex-direction:column;align-items:flex-start;gap:8px}
}

frontend/src/pages/Student/CourseViewer/.content:
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { FiPlay, FiDownload, FiCheckCircle, FiClock, FiBookOpen, FiArrowLeft, FiChevronDown, FiChevronRight, FiAlertCircle } from 'react-icons/fi';
import axios from '../../../utils/axiosConfig';
import './CourseViewer.css';

const CourseViewer = () => {
  const { courseId } = useParams();
  const navigate = useNavigate();

  // State management
  const [course, setCourse] = useState(null);
  const [courseContent, setCourseContent] = useState([]);
  const [activeLesson, setActiveLesson] = useState(null);
  const [userProgress, setUserProgress] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [expandedSubjects, setExpandedSubjects] = useState({});
  const [expandedChapters, setExpandedChapters] = useState({});
  const [expandedTopics, setExpandedTopics] = useState({});

  // Check if user has access to course
  const [hasAccess, setHasAccess] = useState(false);

  // For recorded_classes type courses
  const [videos, setVideos] = useState([]);
  const [activeVideo, setActiveVideo] = useState(null);

  useEffect(() => {
    loadCourseData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [courseId]);

  const loadCourseData = async () => {
    try {
      setLoading(true);

      // Check user enrollment and access
      const accessCheck = await checkCourseAccess();
      if (!accessCheck) {
        setError('You do not have access to this course');
        setLoading(false);
        return;
      }

      // Load course basic info
      const courseData = await loadCourseInfo();

      // Load content based on course type
      if (courseData?.courseType === 'recorded_classes') {
        await loadRecordedClassVideos();
      } else {
        // Load course structure (subjects → chapters → topics → tests)
        await loadCourseStructure();

        // Load user progress
        await loadUserProgress();

        // Set initial active lesson (resume or first unlocked)
        await setInitialLesson();
      }

    } catch (err) {
      console.error('Error loading course data:', err);
      setError('Failed to load course content');
    } finally {
      setLoading(false);
    }
  };

  const checkCourseAccess = async () => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get('/api/user/student/my-courses', {
        headers: { Authorization: `Bearer ${token}` }
      });

      const unlockedCourse = response.data.courses?.find(
        c => c.courseId._id === courseId && c.status === 'unlocked'
      );

      setHasAccess(!!unlockedCourse);
      return !!unlockedCourse;
    } catch (err) {
      console.error('Error checking course access:', err);
      return false;
    }
  };

  const loadCourseInfo = async () => {
    try {
      const response = await axios.get(`/api/courses/student/published-courses/${courseId}`);
      setCourse(response.data.course);
      return response.data.course;
    } catch (err) {
      console.error('Error loading course info:', err);
      return null;
    }
  };

  const loadRecordedClassVideos = async () => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get(`/api/courses/${courseId}/videos`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        const videoList = response.data.videos || [];
        setVideos(videoList);

        // Set first video as active
        if (videoList.length > 0) {
          const sortedVideos = videoList.sort((a, b) => a.serialNumber - b.serialNumber);
          setActiveVideo(sortedVideos[0]);
        }

        // Group videos by topic for sidebar display
        const groupedByTopic = {};
        videoList.forEach(video => {
          const topic = video.topicName || 'General';
          if (!groupedByTopic[topic]) {
            groupedByTopic[topic] = [];
          }
          groupedByTopic[topic].push(video);
        });

        // Auto-expand all topics
        const expandedState = {};
        Object.keys(groupedByTopic).forEach(topic => {
          expandedState[topic] = true;
        });
        setExpandedTopics(expandedState);
      }
    } catch (err) {
      console.error('Error loading videos:', err);
      setError('Failed to load course videos');
    }
  };

  const loadCourseStructure = async () => {
    try {
      const token = localStorage.getItem('authToken');

      // Use the optimized student course structure endpoint
      const structureRes = await axios.get(`/api/student/course/${courseId}/structure`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (!structureRes.data.success) {
        throw new Error(structureRes.data.message || 'Failed to load course structure');
      }

      const { structure } = structureRes.data;

      // Transform the structure to match the expected format
      const courseStructure = structure.map(subject => ({
        id: subject._id,
        name: subject.name,
        type: 'subject',
        hasContent: subject.chapters?.length > 0,
        chapters: subject.chapters.map(chapter => ({
          id: chapter._id,
          name: chapter.name,
          type: 'chapter',
          hasContent: chapter.topics?.length > 0,
          topics: chapter.topics.map(topic => ({
            id: topic._id,
            name: topic.name,
            type: 'topic',
            hasContent: topic.tests?.length > 0,
            tests: topic.tests.map(test => ({
              id: test._id,
              name: test.title || test.name,
              type: 'test',
              duration: test.duration,
              totalMarks: test.totalMarks,
              instructions: test.instructions
            })),
            materials: []
          }))
        })),
        materials: []
      }));

      // Load study materials for this course
      try {
        const materialsRes = await axios.get(`/api/study-materials/student?courseId=${courseId}`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        const materials = materialsRes.data.materials || [];

        // Add materials to the first subject or create a general section
        materials.forEach(material => {
          const materialNode = {
            id: material._id,
            name: material.title,
            type: material.type.toLowerCase(), // PDF, Video, Notes
            fileName: material.fileName,
            fileSize: material.fileSize,
            downloadUrl: `/api/study-materials/download/${material._id}`
          };

          // Add to first subject if available
          if (courseStructure.length > 0) {
            if (!courseStructure[0].materials) {
              courseStructure[0].materials = [];
            }
            courseStructure[0].materials.push(materialNode);
            courseStructure[0].hasContent = true;
          }
        });
      } catch (materialErr) {
        console.log('No study materials found for this course');
      }

      // Auto-expand subjects that have content
      const initialExpandedSubjects = {};
      const initialExpandedChapters = {};

      courseStructure.forEach(subject => {
        if (subject.hasContent) {
          initialExpandedSubjects[subject.id] = true;
          subject.chapters.forEach(chapter => {
            if (chapter.hasContent) {
              initialExpandedChapters[chapter.id] = true;
            }
          });
        }
      });

      setExpandedSubjects(initialExpandedSubjects);
      setExpandedChapters(initialExpandedChapters);
      setCourseContent(courseStructure);

    } catch (err) {
      console.error('Error loading course structure:', err);
      throw err; // Re-throw to be handled by parent function
    }
  };

  const loadUserProgress = async () => {
    try {
      const token = localStorage.getItem('authToken');
      const response = await axios.get(`/api/progress/course/${courseId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        setUserProgress(response.data.progress);
      }
    } catch (err) {
      console.error('Error loading user progress:', err);
      setUserProgress({});
    }
  };

  const setInitialLesson = async () => {
    try {
      // Try to get resume lesson from API
      const token = localStorage.getItem('authToken');
      const resumeResponse = await axios.get(`/api/progress/course/${courseId}/resume`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (resumeResponse.data.success && resumeResponse.data.resumeLesson) {
        const resumeLesson = resumeResponse.data.resumeLesson;
        const lesson = findLessonById(resumeLesson.lessonId, resumeLesson.lessonType);
        if (lesson) {
          setActiveLesson(lesson);
          return;
        }
      }
    } catch (err) {
      console.log('No resume lesson found, starting with first available lesson');
    }

    // Fallback to first available lesson
    if (courseContent.length > 0) {
      const firstLesson = findFirstAvailableLesson(courseContent);
      if (firstLesson) {
        setActiveLesson(firstLesson);
      }
    }
  };

  const findFirstAvailableLesson = (content) => {
    for (const subject of content) {
      for (const chapter of subject.chapters) {
        for (const topic of chapter.topics) {
          if (topic.tests.length > 0) {
            return topic.tests[0];
          }
          if (topic.materials && topic.materials.length > 0) {
            return topic.materials[0];
          }
        }
      }
      if (subject.materials && subject.materials.length > 0) {
        return subject.materials[0];
      }
    }
    return null;
  };

  const findLessonById = (lessonId, lessonType) => {
    for (const subject of courseContent) {
      for (const chapter of subject.chapters) {
        for (const topic of chapter.topics) {
          // Check tests
          const test = topic.tests.find(t => t.id === lessonId && t.type === lessonType);
          if (test) return test;

          // Check materials
          if (topic.materials) {
            const material = topic.materials.find(m => m.id === lessonId && m.type === lessonType);
            if (material) return material;
          }
        }
      }

      // Check subject-level materials
      if (subject.materials) {
        const material = subject.materials.find(m => m.id === lessonId && m.type === lessonType);
        if (material) return material;
      }
    }
    return null;
  };

  const handleLessonSelect = async (lesson) => {
    setActiveLesson(lesson);

    // Track lesson start
    try {
      const token = localStorage.getItem('authToken');
      await axios.post(`/api/progress/course/${courseId}/start-lesson`, {
        lessonId: lesson.id,
        lessonType: lesson.type
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
    } catch (err) {
      console.error('Error tracking lesson start:', err);
    }
  };

  const getLessonProgress = (lessonId) => {
    if (!userProgress.lessonProgress) return { status: 'not_started', progress: 0 };

    const lesson = userProgress.lessonProgress.find(l => l.lessonId === lessonId);
    return lesson || { status: 'not_started', progress: 0 };
  };

  const toggleSubject = (subjectId) => {
    setExpandedSubjects(prev => ({
      ...prev,
      [subjectId]: !prev[subjectId]
    }));
  };

  const toggleChapter = (chapterId) => {
    setExpandedChapters(prev => ({
      ...prev,
      [chapterId]: !prev[chapterId]
    }));
  };

  const getTotalLessons = () => {
    let count = 0;
    courseContent.forEach(subject => {
      if (subject.materials) count += subject.materials.length;
      subject.chapters.forEach(chapter => {
        chapter.topics.forEach(topic => {
          count += topic.tests.length;
          if (topic.materials) count += topic.materials.length;
        });
      });
    });
    return count;
  };

  const getEmbedUrl = (url) => {
    if (!url) return null;

    // YouTube URL conversion
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
      const videoId = url.includes('youtu.be') 
        ? url.split('youtu.be/')[1]?.split('?')[0]
        : new URLSearchParams(new URL(url).search).get('v');
      return `https://www.youtube.com/embed/${videoId}?rel=0`;
    }

    // Vimeo URL conversion
    if (url.includes('vimeo.com')) {
      const videoId = url.split('vimeo.com/')[1]?.split('?')[0];
      return `https://player.vimeo.com/video/${videoId}`;
    }

    // Direct video file or uploaded file
    if (url.startsWith('http') || url.startsWith('/uploads/')) {
      return url.startsWith('http') ? url : url;
    }

    return url;
  };

  const toggleTopic = (topicName) => {
    setExpandedTopics(prev => ({
      ...prev,
      [topicName]: !prev[topicName]
    }));
  };

  const groupVideosByTopic = () => {
    const grouped = {};
    videos.forEach(video => {
      const topic = video.topicName || 'General';
      if (!grouped[topic]) grouped[topic] = [];
      grouped[topic].push(video);
    });
    return grouped;
  };

  const renderVideoSidebar = () => {
    const groupedVideos = groupVideosByTopic();

    return (
      <div className="course-sidebar">
        <div className="sidebar-header">
          <button className="back-btn" onClick={() => navigate('/student/dashboard')}>
            <FiArrowLeft /> Back to Dashboard
          </button>
        </div>

        <div className="course-modules">
          <h3 style={{ padding: '15px', color: '#2c3e50', borderBottom: '2px solid #ecf0f1' }}>
            📚 Course Videos ({videos.length})
          </h3>

          {videos.length === 0 ? (
            <div className="empty-state" style={{ padding: '20px', textAlign: 'center' }}>
              <FiAlertCircle size={48} style={{ color: '#95a5a6' }} />
              <h3 style={{ color: '#7f8c8d', marginTop: '10px' }}>No Videos Available</h3>
              <p style={{ color: '#95a5a6' }}>Videos will appear here once added by instructor</p>
            </div>
          ) : (
            Object.entries(groupedVideos).map(([topicName, topicVideos]) => (
              <div key={topicName} className="module-section" style={{ marginBottom: '10px' }}>
                <div 
                  className="module-header"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '10px',
                    padding: '12px 15px',
                    backgroundColor: '#f8f9fa',
                    cursor: 'pointer',
                    borderBottom: '1px solid #dee2e6',
                    fontWeight: 'bold'
                  }}
                  onClick={() => toggleTopic(topicName)}
                >
                  {expandedTopics[topicName] ? <FiChevronDown /> : <FiChevronRight />}
                  <FiBookOpen />
                  <span>{topicName}</span>
                  <span style={{ marginLeft: 'auto', fontSize: '12px', color: '#6c757d' }}>
                    ({topicVideos.length} videos)
                  </span>
                </div>

                {expandedTopics[topicName] && (
                  <div className="topic-videos" style={{ backgroundColor: '#fff' }}>
                    {topicVideos
                      .sort((a, b) => a.serialNumber - b.serialNumber)
                      .map((video) => (
                        <div
                          key={video._id}
                          className={`video-lesson-item ${activeVideo?._id === video._id ? 'active' : ''}`}
                          onClick={() => setActiveVideo(video)}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '10px',
                            padding: '12px 15px 12px 40px',
                            cursor: 'pointer',
                            borderLeft: activeVideo?._id === video._id ? '4px solid #3498db' : '4px solid transparent',
                            backgroundColor: activeVideo?._id === video._id ? '#e3f2fd' : 'transparent',
                            transition: 'all 0.2s ease'
                          }}
                          onMouseEnter={(e) => {
                            if (activeVideo?._id !== video._id) {
                              e.currentTarget.style.backgroundColor = '#f8f9fa';
                            }
                          }}
                          onMouseLeave={(e) => {
                            if (activeVideo?._id !== video._id) {
                              e.currentTarget.style.backgroundColor = 'transparent';
                            }
                          }}
                        >
                          <FiPlay style={{ 
                            color: activeVideo?._id === video._id ? '#3498db' : '#95a5a6',
                            flexShrink: 0 
                          }} />
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ 
                              fontWeight: activeVideo?._id === video._id ? '600' : '400',
                              color: activeVideo?._id === video._id ? '#2c3e50' : '#495057',
                              fontSize: '14px',
                              whiteSpace: 'nowrap',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis'
                            }}>
                              #{video.serialNumber} {video.title}
                            </div>
                            {video.duration && (
                              <div style={{ fontSize: '12px', color: '#6c757d', marginTop: '2px' }}>
                                <FiClock style={{ fontSize: '10px' }} /> {video.duration}
                              </div>
                            )}
                          </div>
                          {activeVideo?._id === video._id && (
                            <FiCheckCircle style={{ color: '#27ae60', flexShrink: 0 }} />
                          )}
                        </div>
                      ))}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  const renderVideoContent = () => {
    if (!activeVideo) {
      return (
        <div className="course-main-content">
          <div className="no-lesson-selected" style={{ 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'center', 
            justifyContent: 'center',
            height: '100%',
            padding: '40px',
            textAlign: 'center'
          }}>
            <FiPlay size={64} style={{ color: '#bdc3c7', marginBottom: '20px' }} />
            <h3 style={{ color: '#2c3e50', marginBottom: '10px' }}>Select a video to begin</h3>
            <p style={{ color: '#7f8c8d' }}>
              Choose from {videos.length} available video{videos.length !== 1 ? 's' : ''} on the left to start learning
            </p>
          </div>
        </div>
      );
    }

    const embedUrl = getEmbedUrl(activeVideo.videoUrl);
    const isYouTubeOrVimeo = embedUrl?.includes('youtube.com') || embedUrl?.includes('vimeo.com');

    return (
      <div className="course-main-content">
        <div className="video-player-container" style={{ padding: '20px' }}>
          <div style={{ marginBottom: '20px' }}>
            <h2 style={{ color: '#2c3e50', marginBottom: '10px' }}>
              #{activeVideo.serialNumber} - {activeVideo.title}
            </h2>
            {activeVideo.topicName && (
              <div style={{ 
                display: 'inline-block',
                backgroundColor: '#e3f2fd',
                color: '#1976d2',
                padding: '6px 12px',
                borderRadius: '20px',
                fontSize: '14px',
                fontWeight: '500'
              }}>
                📚 {activeVideo.topicName}
              </div>
            )}
          </div>

          <div className="video-player-wrapper" style={{
            position: 'relative',
            paddingBottom: '56.25%',
            height: 0,
            overflow: 'hidden',
            backgroundColor: '#000',
            borderRadius: '8px',
            marginBottom: '20px'
          }}>
            {isYouTubeOrVimeo ? (
              <iframe
                src={embedUrl}
                title={activeVideo.title}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%'
                }}
              />
            ) : (
              <video 
                controls 
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%'
                }}
              >
                <source src={embedUrl} type="video/mp4" />
                Your browser does not support the video tag.
              </video>
            )}
          </div>

          {activeVideo.description && (
            <div style={{
              backgroundColor: '#f8f9fa',
              padding: '20px',
              borderRadius: '8px',
              marginTop: '20px'
            }}>
              <h4 style={{ color: '#2c3e50', marginBottom: '10px' }}>📝 Description</h4>
              <p style={{ color: '#495057', lineHeight: '1.6' }}>{activeVideo.description}</p>
            </div>
          )}

          {activeVideo.duration && (
            <div style={{ 
              marginTop: '15px',
              color: '#6c757d',
              fontSize: '14px',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}>
              <FiClock /> Duration: {activeVideo.duration}
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderSidebar = () => {
    // Check if this is a recorded_classes course
    if (course?.courseType === 'recorded_classes') {
      return renderVideoSidebar();
    }


    const totalLessons = getTotalLessons();

    return (
      <div className="course-sidebar">
        <div className="sidebar-header">
          <button className="back-btn" onClick={() => navigate('/student/dashboard')}>
            <FiArrowLeft /> Back to Dashboard
          </button>
        </div>

        <div className="course-modules">
          {courseContent.length === 0 ? (
            <div className="empty-state">
              <FiAlertCircle size={48} />
              <h3>No Course Structure Found</h3>
              <p>This course doesn't have any subjects or modules yet.</p>
            </div>
          ) : totalLessons === 0 ? (
            <div className="course-structure-info">
              <h4>Course Structure</h4>
              <p className="structure-note">
                📚 This course has {courseContent.length} subject{courseContent.length !== 1 ? 's' : ''} 
                but no lessons have been added yet.
              </p>

              {courseContent.map((subject) => (
                <div key={subject.id} className="module-section structure-only">
                  <div 
                    className="module-header clickable"
                    onClick={() => toggleSubject(subject.id)}
                  >
                    {expandedSubjects[subject.id] ? <FiChevronDown /> : <FiChevronRight />}
                    <FiBookOpen />
                    <span>{subject.name}</span>
                    <span className="content-count">
                      ({subject.chapters.length} chapter{subject.chapters.length !== 1 ? 's' : ''})
                    </span>
                  </div>

                  {expandedSubjects[subject.id] && (
                    <div className="subject-content">
                      {subject.chapters.length === 0 ? (
                        <div className="empty-chapters">No chapters available</div>
                      ) : (
                        subject.chapters.map((chapter) => (
                          <div key={chapter.id} className="chapter-section structure-only">
                            <div 
                              className="chapter-title clickable"
                              onClick={() => toggleChapter(chapter.id)}
                            >
                              {expandedChapters[chapter.id] ? <FiChevronDown /> : <FiChevronRight />}
                              <span>{chapter.name}</span>
                              <span className="content-count">
                                ({chapter.topics.length} topic{chapter.topics.length !== 1 ? 's' : ''})
                              </span>
                            </div>

                            {expandedChapters[chapter.id] && (
                              <div className="chapter-content">
                                {chapter.topics.length === 0 ? (
                                  <div className="empty-topics">No topics available</div>
                                ) : (
                                  chapter.topics.map((topic) => (
                                    <div key={topic.id} className="topic-section structure-only">
                                      <div className="topic-title">
                                        📝 {topic.name} ({topic.tests.length} test{topic.tests.length !== 1 ? 's' : ''})
                                      </div>
                                    </div>
                                  ))
                                )}
                              </div>
                            )}
                          </div>
                        ))
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          ) : (
            // Render normal course content with lessons
            courseContent.map((subject) => (
              <div key={subject.id} className="module-section">
                <div 
                  className="module-header clickable"
                  onClick={() => toggleSubject(subject.id)}
                >
                  {expandedSubjects[subject.id] ? <FiChevronDown /> : <FiChevronRight />}
                  <FiBookOpen />
                  <span>{subject.name}</span>
                </div>

                {expandedSubjects[subject.id] && (
                  <div className="subject-content">
                    {subject.chapters.map((chapter) => (
                      <div key={chapter.id} className="chapter-section">
                        <div 
                          className="chapter-title clickable"
                          onClick={() => toggleChapter(chapter.id)}
                        >
                          {expandedChapters[chapter.id] ? <FiChevronDown /> : <FiChevronRight />}
                          <span>{chapter.name}</span>
                        </div>

                        {expandedChapters[chapter.id] && (
                          <div className="chapter-content">
                            {chapter.topics.map((topic) => (
                              <div key={topic.id} className="topic-section">
                                <div className="topic-title">{topic.name}</div>

                                {/* Render tests */}
                                {topic.tests.map((test) => {
                                  const progress = getLessonProgress(test.id);
                                  return (
                                    <div
                                      key={test.id}
                                      className={`lesson-item ${activeLesson?.id === test.id ? 'active' : ''} ${progress.status}`}
                                      onClick={() => handleLessonSelect(test)}
                                    >
                                      <div className="lesson-icon">
                                        {progress.status === 'completed' ? (
                                          <FiCheckCircle className="completed" />
                                        ) : progress.status === 'in_progress' ? (
                                          <FiPlay className="in-progress" />
                                        ) : (
                                          <FiClock className="not-started" />
                                        )}
                                      </div>
                                      <div className="lesson-info">
                                        <div className="lesson-title">{test.name}</div>
                                        <div className="lesson-meta">
                                          <FiClock /> {test.duration} min
                                          {progress.progress > 0 && (
                                            <span className="progress-indicator">
                                              {progress.progress}%
                                            </span>
                                          )}
                                        </div>
                                      </div>
                                    </div>
                                  );
                                })}

                                {/* Render materials */}
                                {topic.materials && topic.materials.map((material) => {
                                  const progress = getLessonProgress(material.id);
                                  return (
                                    <div
                                      key={material.id}
                                      className={`lesson-item ${activeLesson?.id === material.id ? 'active' : ''} ${progress.status}`}
                                      onClick={() => handleLessonSelect(material)}
                                    >
                                      <div className="lesson-icon">
                                        {progress.status === 'completed' ? (
                                          <FiCheckCircle className="completed" />
                                        ) : material.type === 'video' ? (
                                          <FiPlay className={progress.status === 'in_progress' ? 'in-progress' : 'not-started'} />
                                        ) : (
                                          <FiDownload className={progress.status === 'in_progress' ? 'in-progress' : 'not-started'} />
                                        )}
                                      </div>
                                      <div className="lesson-info">
                                        <div className="lesson-title">{material.name}</div>
                                        <div className="lesson-meta">
                                          {material.type.toUpperCase()}
                                          {progress.progress > 0 && (
                                            <span className="progress-indicator">
                                              {progress.progress}%
                                            </span>
                                          )}
                                        </div>
                                      </div>
                                    </div>
                                  );
                                })}
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}

                    {/* Subject-level materials */}
                    {subject.materials && subject.materials.map((material) => (
                      <div
                        key={material.id}
                        className={`lesson-item ${activeLesson?.id === material.id ? 'active' : ''}`}
                        onClick={() => handleLessonSelect(material)}
                      >
                        <div className="lesson-icon">
                          {material.type === 'video' ? <FiPlay /> : <FiDownload />}
                        </div>
                        <div className="lesson-info">
                          <div className="lesson-title">{material.name}</div>
                          <div className="lesson-meta">{material.type.toUpperCase()}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  const renderMainContent = () => {
    // Check if this is a recorded_classes course
    if (course?.courseType === 'recorded_classes') {
      return renderVideoContent();
    }

    const totalLessons = getTotalLessons();

    return (
      <div className="course-main-content">
        {activeLesson ? (
          <div className="lesson-player">
            {activeLesson.type === 'test' ? (
              <div className="test-content">
                <div className="test-header">
                  <h2>{activeLesson.name}</h2>
                  <div className="test-meta">
                    <span><FiClock /> {activeLesson.duration} minutes</span>
                    <span>Total Marks: {activeLesson.totalMarks}</span>
                  </div>
                </div>
                <div className="test-instructions">
                  <h3>Instructions:</h3>
                  <p>{activeLesson.instructions || 'No specific instructions provided.'}</p>
                </div>
                <div className="test-actions">
                  <button className="start-test-btn primary">
                    <FiPlay /> Start Test
                  </button>
                </div>
              </div>
            ) : activeLesson.type === 'video' ? (
              <div className="video-content">
                <div className="video-header">
                  <h2>{activeLesson.name}</h2>
                </div>
                <div className="video-placeholder">
                  <FiPlay size={64} />
                  <p>Video player will be implemented here</p>
                  <p>File: {activeLesson.fileName}</p>
                </div>
              </div>
            ) : (
              <div className="document-content">
                <div className="document-header">
                  <h2>{activeLesson.name}</h2>
                  <div className="document-actions">
                    <a 
                      href={activeLesson.downloadUrl} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="download-btn"
                    >
                      <FiDownload /> Download {activeLesson.type.toUpperCase()}
                    </a>
                  </div>
                </div>
                <div className="document-preview">
                  <p>Document preview will be implemented here</p>
                  <p>File: {activeLesson.fileName}</p>
                  <p>Size: {(activeLesson.fileSize / 1024 / 1024).toFixed(2)} MB</p>
                </div>
              </div>
            )}
          </div>
        ) : totalLessons === 0 ? (
          <div className="no-content-available">
            <FiAlertCircle size={64} />
            <h3>No Lessons Available</h3>
            <p>This course structure has been created but no lessons have been added yet.</p>
            <div className="content-info">
              <p>The course currently contains:</p>
              <ul>
                <li>📚 {courseContent.length} Subject{courseContent.length !== 1 ? 's' : ''}</li>
                <li>📘 {courseContent.reduce((acc, s) => acc + s.chapters.length, 0)} Chapter{courseContent.reduce((acc, s) => acc + s.chapters.length, 0) !== 1 ? 's' : ''}</li>
                <li>📝 {courseContent.reduce((acc, s) => acc + s.chapters.reduce((acc2, c) => acc2 + c.topics.length, 0), 0)} Topic{courseContent.reduce((acc, s) => acc + s.chapters.reduce((acc2, c) => acc2 + c.topics.length, 0), 0) !== 1 ? 's' : ''}</li>
              </ul>
              <p className="help-text">
                Lessons, tests, and study materials will appear here once they are added by the instructor.
              </p>
            </div>
          </div>
        ) : (
          <div className="no-lesson-selected">
            <FiBookOpen size={64} />
            <h3>Select a lesson to begin</h3>
            <p>Choose from the {totalLessons} available lesson{totalLessons !== 1 ? 's' : ''} on the left to start learning</p>
          </div>
        )}
      </div>
    );
  };

  if (loading) {
    return (
      <div className="course-viewer loading">
        <div className="loading-spinner">Loading course content...</div>
      </div>
    );
  }

  if (error || !hasAccess) {
    return (
      <div className="course-viewer error">
        <div className="error-message">
          <h2>Access Denied</h2>
          <p>{error || 'You do not have access to this course'}</p>
          <button onClick={() => navigate('/student/dashboard')} className="back-btn">
            Return to Dashboard
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="course-viewer">
      {/* Header */}
      <div className="course-header">
        <div className="course-title">
          <h1>{course?.name || 'Course Content'}</h1>
          <div className="course-progress">
            <div className="progress-bar">
              <div
                className="progress-fill"
                style={{ width: `${userProgress.overallProgress || 0}%` }}
              ></div>
            </div>
            <span className="progress-text">
              {userProgress.overallProgress || 0}% Complete
            </span>
          </div>
        </div>
      </div>

      {/* Main layout */}
      <div className="course-layout">
        {renderSidebar()}
        {renderMainContent()}
      </div>
    </div>
  );
};

export default CourseViewer;

