const mongoose = require("mongoose");
require("dotenv").config();

const Connection = async () => {
  try {
    if (!process.env.MONGO_URI) {
      console.warn("⚠️ MONGO_URI not found in environment variables");
      console.log("📝 Running in development mode without database");
      return;
    }

    await mongoose.connect(process.env.MONGO_URI, {
      // useNewUrlParser: true,
      // useUnifiedTopology: true,
    });
    console.log("✅ Connected to MongoDB Atlas Successfully!");
  } catch (error) {
    console.error("❌ MongoDB Connection Error:", error);
    console.log("🔄 Continuing without database for development...");
    // Don't exit in development - allow server to run without DB
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }
  }
};

module.exports = Connection;

backend/models/AdminUser.js.content:
const mongoose = require("mongoose");
const bcrypt = require("bcrypt");

const CustomPermissionSchema = new mongoose.Schema({
  view: { type: Boolean },
  create: { type: Boolean },
  edit: { type: Boolean },
  delete: { type: Boolean },
  export: { type: Boolean },
  approve: { type: Boolean }
}, { _id: false });

const AdminUserSchema = new mongoose.Schema(
  {
    fullName: {
      type: String,
      required: true,
      trim: true
    },
    email: {
      type: String,
      required: true,
      unique: true,
      lowercase: true,
      trim: true
    },
    phone: {
      type: String,
      default: ""
    },
    password: {
      type: String,
      required: true
    },
    userType: {
      type: String,
      enum: ["superadmin", "subadmin", "teacher"],
      default: "subadmin"
    },
    role: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Role"
    },
    customPermissions: {
      dashboard: CustomPermissionSchema,
      students: CustomPermissionSchema,
      courses: CustomPermissionSchema,
      batches: CustomPermissionSchema,
      liveClasses: CustomPermissionSchema,
      liveBatches: CustomPermissionSchema,
      mockTests: CustomPermissionSchema,
      mockTestFeedback: CustomPermissionSchema,
      practiceTests: CustomPermissionSchema,
      payments: CustomPermissionSchema,
      coupons: CustomPermissionSchema,
      notifications: CustomPermissionSchema,
      announcements: CustomPermissionSchema,
      popupAnnouncements: CustomPermissionSchema,
      leads: CustomPermissionSchema,
      reports: CustomPermissionSchema,
      faculty: CustomPermissionSchema,
      blogs: CustomPermissionSchema,
      demoVideos: CustomPermissionSchema,
      studyMaterials: CustomPermissionSchema,
      pdfManagement: CustomPermissionSchema,
      discussions: CustomPermissionSchema,
      bschools: CustomPermissionSchema,
      iimPredictor: CustomPermissionSchema,
      responseSheets: CustomPermissionSchema,
      downloads: CustomPermissionSchema,
      gallery: CustomPermissionSchema,
      scoreCards: CustomPermissionSchema,
      successStories: CustomPermissionSchema,
      topPerformers: CustomPermissionSchema,
      coursePurchaseContent: CustomPermissionSchema,
      crm: CustomPermissionSchema,
      billing: CustomPermissionSchema,
      roleManagement: CustomPermissionSchema
    },
    status: {
      type: String,
      enum: ["active", "suspended"],
      default: "active"
    },
    lastLogin: {
      type: Date
    },
    createdBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "AdminUser"
    }
  },
  {
    timestamps: true
  }
);

AdminUserSchema.pre("save", async function (next) {
  if (!this.isModified("password")) return next();
  this.password = await bcrypt.hash(this.password, 10);
  next();
});

AdminUserSchema.methods.comparePassword = async function (candidatePassword) {
  return bcrypt.compare(candidatePassword, this.password);
};

AdminUserSchema.methods.getEffectivePermissions = async function () {
  if (this.userType === "superadmin") {
    const allPermissions = {};
    const modules = [
      "dashboard", "students", "courses", "batches", "liveClasses", "liveBatches",
      "mockTests", "mockTestFeedback", "practiceTests", "payments", "coupons", "notifications",
      "announcements", "popupAnnouncements", "leads", "reports", "faculty", "blogs", "demoVideos",
      "studyMaterials", "pdfManagement", "discussions", "bschools", "iimPredictor", "responseSheets",
      "downloads", "gallery", "scoreCards", "successStories", "topPerformers", "coursePurchaseContent",
      "crm", "billing", "roleManagement"
    ];
    modules.forEach(mod => {
      allPermissions[mod] = {
        view: true, create: true, edit: true, delete: true, export: true, approve: true
      };
    });
    return allPermissions;
  }

  let rolePermissions = {};
  if (this.role) {
    const Role = mongoose.model("Role");
    const role = await Role.findById(this.role);
    if (role && role.permissions) {
      rolePermissions = role.permissions.toObject ? role.permissions.toObject() : role.permissions;
    }
  }

  const effectivePermissions = { ...rolePermissions };
  if (this.customPermissions) {
    const customPerms = this.customPermissions.toObject ? this.customPermissions.toObject() : this.customPermissions;
    Object.keys(customPerms).forEach(module => {
      if (customPerms[module]) {
        if (!effectivePermissions[module]) {
          effectivePermissions[module] = {};
        }
        Object.keys(customPerms[module]).forEach(action => {
          if (customPerms[module][action] !== undefined && customPerms[module][action] !== null) {
            effectivePermissions[module][action] = customPerms[module][action];
          }
        });
      }
    });
  }

  return effectivePermissions;
};

module.exports = mongoose.model("AdminUser", AdminUserSchema);

frontend/src/pages/mainAdmin/StudyMateri.content:
.study-materials-container {
  padding: 24px;
  max-width: 1400px;
  margin: 0 auto;
  background-color: #f8f9fa;
  min-height: 100vh;
}

/* Header */
.study-materials-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
  background: white;
  padding: 24px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.header-left h1 {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 8px 0;
  color: #2c3e50;
  font-size: 28px;
  font-weight: 600;
}

.header-left p {
  margin: 0;
  color: #6c757d;
  font-size: 16px;
}

.upload-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #007bff, #0056b3);
  color: white;
  border: none;
  padding: 12px 24px;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
}

.upload-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(0, 123, 255, 0.3);
}

.upload-buttons-group {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.upload-btn-pdf {
  background: linear-gradient(135deg, #e74c3c, #c0392b);
}

.upload-btn-pdf:hover {
  box-shadow: 0 4px 12px rgba(231, 76, 60, 0.4);
}

.upload-btn-study {
  background: linear-gradient(135deg, #28a745, #1e7e34);
}

.upload-btn-study:hover {
  box-shadow: 0 4px 12px rgba(40, 167, 69, 0.3);
}

.upload-btn-video {
  background: linear-gradient(135deg, #dc3545, #c82333);
}

.upload-btn-video:hover {
  box-shadow: 0 4px 12px rgba(220, 53, 69, 0.3);
}

.upload-btn-papers {
  background: linear-gradient(135deg, #6f42c1, #563d7c);
}

.upload-btn-papers:hover {
  box-shadow: 0 4px 12px rgba(111, 66, 193, 0.3);
}

/* Filters */
.materials-filters {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
  background: white;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  align-items: center;
  flex-wrap: wrap;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: 8px;
  position: relative;
}

.filter-group select {
  padding: 10px 16px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  background: white;
  font-size: 14px;
  color: #495057;
  cursor: pointer;
  transition: border-color 0.3s ease;
  min-width: 150px;
}

.filter-group select:focus {
  outline: none;
  border-color: #007bff;
}

.filter-icon {
  color: #6c757d;
  font-size: 16px;
}

.search-group {
  display: flex;
  align-items: center;
  position: relative;
  margin-left: auto;
}

.search-icon {
  position: absolute;
  left: 12px;
  color: #6c757d;
  font-size: 14px;
}

.search-group input {
  padding: 10px 16px 10px 40px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  background: white;
  font-size: 14px;
  color: #495057;
  transition: border-color 0.3s ease;
  min-width: 250px;
}

.search-group input:focus {
  outline: none;
  border-color: #007bff;
}

/* Table */
.materials-table-container {
  background: white;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  margin-bottom: 24px;
}

.materials-table {
  width: 100%;
  border-collapse: collapse;
}

.materials-table th {
  background: #f8f9fa;
  padding: 16px;
  text-align: left;
  font-weight: 600;
  color: #495057;
  border-bottom: 2px solid #e9ecef;
  font-size: 14px;
}

.materials-table td {
  padding: 16px;
  border-bottom: 1px solid #e9ecef;
  vertical-align: middle;
}

.materials-table tr:hover {
  background-color: #f8f9fa;
}

.material-info .material-details {
  display: flex;
  align-items: center;
  gap: 12px;
}

.file-icon {
  font-size: 24px;
  min-width: 32px;
}

.material-details h4 {
  margin: 0 0 4px 0;
  color: #2c3e50;
  font-size: 16px;
  font-weight: 500;
}

.material-details p {
  margin: 0;
  color: #6c757d;
  font-size: 14px;
  max-width: 300px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.subject-badge,
.type-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.subject-badge {
  background: linear-gradient(135deg, #e3f2fd, #bbdefb);
  color: #1976d2;
}

.type-badge {
  background: linear-gradient(135deg, #f3e5f5, #e1bee7);
  color: #7b1fa2;
}

.actions {
  display: flex;
  gap: 8px;
}

.action-btn {
  padding: 8px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 14px;
  min-width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.view-btn {
  background: #e3f2fd;
  color: #1976d2;
}

.view-btn:hover {
  background: #bbdefb;
}

.edit-btn {
  background: #fff3e0;
  color: #f57c00;
}

.edit-btn:hover {
  background: #ffe0b2;
}

.delete-btn {
  background: #ffebee;
  color: #d32f2f;
}

.delete-btn:hover {
  background: #ffcdd2;
}

.no-data {
  text-align: center;
  padding: 48px;
  color: #6c757d;
  font-style: italic;
}

/* Loading */
.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px;
  gap: 16px;
}

.loading-spinner {
  width: 40px;
  height: 40px;
  border: 4px solid #e9ecef;
  border-top: 4px solid #007bff;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  background: white;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.pagination button {
  padding: 8px 16px;
  border: 2px solid #e9ecef;
  background: white;
  color: #495057;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.pagination button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.pagination button:not(:disabled):hover {
  border-color: #007bff;
  color: #007bff;
}

.page-info {
  color: #6c757d;
  font-weight: 500;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;
}

.upload-modal {
  background: white;
  border-radius: 16px;
  max-width: 600px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px;
  border-bottom: 1px solid #e9ecef;
}

.modal-header h2 {
  margin: 0;
  color: #2c3e50;
  font-size: 24px;
  font-weight: 600;
}

.close-btn {
  background: none;
  border: none;
  font-size: 24px;
  color: #6c757d;
  cursor: pointer;
  padding: 4px;
  line-height: 1;
  transition: color 0.3s ease;
}

.close-btn:hover {
  color: #495057;
}

.upload-form {
  padding: 24px;
}

.form-group {
  margin-bottom: 20px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: #495057;
  font-weight: 500;
  font-size: 14px;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  font-size: 14px;
  color: #495057;
  transition: border-color 0.3s ease;
  box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: #007bff;
}

.form-group textarea {
  resize: vertical;
  min-height: 80px;
}

.form-group small {
  display: block;
  margin-top: 4px;
  color: #6c757d;
  font-size: 12px;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 32px;
  padding-top: 20px;
  border-top: 1px solid #e9ecef;
}

.cancel-btn {
  padding: 12px 24px;
  border: 2px solid #e9ecef;
  background: white;
  color: #495057;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 14px;
  font-weight: 500;
}

.cancel-btn:hover {
  border-color: #6c757d;
  color: #6c757d;
}

.submit-btn {
  padding: 12px 24px;
  border: none;
  background: linear-gradient(135deg, #28a745, #20c997);
  color: white;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 14px;
  font-weight: 500;
}

.submit-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(40, 167, 69, 0.3);
}

.submit-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* Responsive */
@media (max-width: 768px) {
  .study-materials-container {
    padding: 16px;
  }

  .study-materials-header {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .materials-filters {
    flex-direction: column;
    align-items: stretch;
  }

  .search-group {
    margin-left: 0;
  }

  .search-group input {
    min-width: 100%;
  }

  .materials-table-container {
    overflow-x: auto;
  }

  .materials-table {
    min-width: 800px;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .modal-overlay {
    padding: 10px;
  }

  .upload-modal {
    max-height: 95vh;
  }
}

@media (max-width: 480px) {
  .header-left h1 {
    font-size: 24px;
  }

  .upload-btn {
    width: 100%;
    justify-content: center;
  }

  .materials-filters {
    padding: 16px;
  }

  .upload-form {
    padding: 16px;
  }

  .modal-header {
    padding: 16px;
  }
}

/* Preview Modal Styles */
.preview-modal {
  max-width: 600px;
}

.preview-content {
  padding: 20px;
}

.preview-item {
  display: flex;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #e9ecef;
}

.preview-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.preview-item label {
  font-weight: 600;
  color: #495057;
  min-width: 120px;
  flex-shrink: 0;
}

.preview-item span {
  color: #212529;
  word-break: break-word;
}

.preview-item .download-link {
  color: #007bff;
  text-decoration: none;
  font-weight: 500;
}

.preview-item .download-link:hover {
  text-decoration: underline;
}

/* Edit Modal Styles */
.edit-modal {
  max-width: 600px;
}

