  border: 2px solid #e2e8f0;
  border-radius: 10px;
  text-align: center;
  font-size: 22px;
  font-weight: 600;
  color: #1a1a2e;
  transition: border-color 0.3s;
}

.otp-input:focus {
  outline: none;
  border-color: #ff6b35;
}

.resend-section {
  text-align: center;
  margin-top: 20px;
}

.resend-section p {
  font-size: 13px;
  color: #64748b;
  margin: 0 0 8px 0;
}

.resend-btn {
  background: none;
  border: none;
  color: #ff6b35;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  padding: 0;
}

.resend-btn:disabled {
  color: #94a3b8;
  cursor: not-allowed;
}

.back-btn {
  width: 100%;
  padding: 12px;
  background: #f8fafc;
  border: none;
  border-radius: 8px;
  color: #64748b;
  font-size: 14px;
  cursor: pointer;
  margin-top: 15px;
  transition: background 0.2s;
}

.back-btn:hover {
  background: #e2e8f0;
}

.auth-terms {
  margin-top: 25px;
  text-align: center;
  font-size: 12px;
  color: #94a3b8;
}

.auth-terms a {
  color: #ff6b35;
  text-decoration: none;
}

.auth-terms a:hover {
  text-decoration: underline;
}

@media (max-width: 768px) {
  .auth-login-container {
    flex-direction: column;
  }

  .auth-login-left {
    padding: 30px 25px;
  }

  .auth-features {
    display: none;
  }

  .auth-login-right {
    padding: 30px 25px;
  }

  .otp-input {
    width: 42px;
    height: 50px;
    font-size: 20px;
  }
}

backend/models/ScoreCard.js.content:
const mongoose = require("mongoose");

const ScoreCardSchema = new mongoose.Schema({
  imageUrl: {
    type: String,
    required: true
  },
  percentileCategory: {
    type: String,
    enum: ["99", "98", "97", "96", "95", "90", "85", "80"],
    required: true
  },
  studentName: {
    type: String,
    default: ""
  },
  percentileScore: {
    type: String,
    default: ""
  },
  order: {
    type: Number,
    default: 0
  },
  isActive: {
    type: Boolean,
    default: true
  },
  createdAt: {
    type: Date,
    default: Date.now
  },
  updatedAt: {
    type: Date,
    default: Date.now
  }
});

module.exports = mongoose.model("ScoreCard", ScoreCardSchema);

frontend/src/utils/crmApi.js.content:
import axios from 'axios';
import { API_BASE } from './apiBase';
import { toast } from 'react-toastify';

const resolveToken = () => {
  const fromLocal = localStorage.getItem('adminToken') || localStorage.getItem('token') || localStorage.getItem('authToken');
  const fromSession = sessionStorage.getItem('token');
  const fromWindow = typeof window !== 'undefined' ? window.__TOKEN__ : null;
  return fromLocal || fromSession || fromWindow || null;
};

const crm = axios.create({ baseURL: API_BASE, withCredentials: true, timeout: 20000 });

crm.interceptors.request.use((config) => {
  const token = resolveToken();
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

crm.interceptors.response.use(
  (res) => res,
  (error) => {
    if (error?.response?.status === 401) {
      try { toast.error('Session expired'); } catch {}
      setTimeout(()=>{ window.location.href = '/admin'; }, 1500);
    }
    return Promise.reject(error);
  }
);

export default crm;

