frontend/src/pages/mainAdmin/MockTestMan.content:
.mock-test-management {
  padding: 24px;
  max-width: 1400px;
  margin: 0 auto;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

/* ---------- HEADER ---------- */

.management-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
}

.header-content h1 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 6px;
}

.header-content .muted {
  font-size: 14px;
  color: #6b7280;
  max-width: 560px;
}

.header-actions .refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid #e5e7eb;
  background: #fff;
  cursor: pointer;
  font-size: 13px;
}

.header-actions .refresh-btn svg {
  font-size: 14px;
}

.header-actions .refresh-btn:hover {
  background: #f9fafb;
}

/* ---------- TABS (MAIN) ---------- */

.tabs {
  display: flex;
  gap: 10px;
  margin-bottom: 16px;
}

.tab {
  flex: 0 0 auto;
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid #e5e7eb;
  background: #fff;
  font-size: 13px;
  cursor: pointer;
  color: #111827;
}

.tab-active {
  border-color: #2563eb;
  color: #2563eb;
  box-shadow: 0 0 0 1px rgba(37, 99, 235, 0.1);
}

/* ---------- CONTENT WRAPPER ---------- */

.management-content {
  background: #ffffff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

/* ---------- HIERARCHY CONTAINERS ---------- */

.paperwise-container,
.topicwise-container {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.test-creator-section {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 2px solid #e5e7eb;
}

/* ---------- SECTION GRID ---------- */

/* ---------- SUB-TABS (PAPER / TOPIC) ---------- */

.subtabs {
  display: inline-flex;
  border-radius: 999px;
  background: #111827;
  padding: 3px;
  margin-bottom: 16px;
}

.subtab {
  padding: 8px 18px;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: #9ca3af;
  font-size: 13px;
  cursor: pointer;
}

.subtab-active {
  background: #fff;
  color: #111827;
}

/* ---------- 3 COLUMN LAYOUT ---------- */

.section-grid {
  display: grid;
  grid-template-columns: 1.1fr 1.1fr 1.2fr;
  gap: 16px;
}

.section-col {
  background: #ffffff;
  border-radius: 16px;
  padding: 16px 18px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
  border: 1px solid #e5e7eb;
}

.section-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 10px;
}

/* ---------- LIST STYLES ---------- */

.list {
  list-style: none;
  margin: 0 0 10px;
  padding: 0;
  max-height: 220px;
  overflow-y: auto;
}

.list-item {
  padding: 8px 10px;
  border-radius: 10px;
  font-size: 14px;
  cursor: pointer;
  color: #111827;
  border: 1px solid transparent;
  transition: all 0.15s ease;
}

.list-item:hover {
  background: #f3f4ff;
  border-color: #e0e7ff;
}

.list-item-active {
  background: #eef2ff;
  border-color: #4f46e5;
  color: #1d1c4f;
  font-weight: 600;
}

/* ---------- FORMS (INLINE + STACK) ---------- */

.inline-form {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

.inline-form input {
  flex: 1;
  padding: 8px 10px;
  border-radius: 999px;
  border: 1px solid #e5e7eb;
  font-size: 13px;
}

.stack-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.stack-form input,
.stack-form textarea {
  width: 100%;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid #e5e7eb;
  font-size: 13px;
}

.stack-form textarea {
  resize: vertical;
  min-height: 70px;
}

.form-row {
  display: flex;
  gap: 8px;
}

.form-row input {
  flex: 1;
}

/* ---------- BUTTONS ---------- */

.small-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  border: none;
  background: #ef4444;
  color: #ffffff;
  font-size: 13px;
  cursor: pointer;
  font-weight: 500;
}

.small-btn svg {
  font-size: 14px;
}

.small-btn:hover {
  background: #dc2626;
}

.small-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

/* ---------- CARD / DETAILS ---------- */

.card {
  background: #f9fafb;
  border-radius: 14px;
  padding: 14px 16px;
  border: 1px solid #e5e7eb;
}

.card-title {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 6px;
}

.card-text {
  font-size: 14px;
  color: #4b5563;
  margin-bottom: 8px;
  white-space: pre-line;
}

.card-meta {
  font-size: 13px;
  color: #6b7280;
}

.card-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* ---------- ICON BUTTON ---------- */

.icon-btn {
  border: none;
  background: #f3f4f6;
  border-radius: 999px;
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.icon-btn svg {
  font-size: 15px;
  color: #374151;
}

.icon-btn:hover {
  background: #e5e7eb;
}

.icon-btn.danger svg {
  color: #b91c1c;
}

/* ---------- SIMPLE TESTS CARD LIST ---------- */

.simple-tests-wrap {
  background: #ffffff;
  border-radius: 16px;
  padding: 16px 18px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
  border: 1px solid #e5e7eb;
}

.simple-test-form {
  display: grid;
  grid-template-columns: 1.2fr 0.7fr 0.7fr 1.4fr auto;
  gap: 8px;
  margin-bottom: 12px;
}

.simple-test-form input {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid #e5e7eb;
  font-size: 13px;
}

.card-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
