import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import * as XLSX from 'xlsx';
import axios from 'axios';
import AdminLayout from '../AdminLayout/AdminLayout';
import './BulkUpload.css';

const BulkUpload = () => {
    const navigate = useNavigate();
    const [file, setFile] = useState(null);
    const [preview, setPreview] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [uploadStatus, setUploadStatus] = useState([]);
    const [courses, setCourses] = useState([]);
    const [selectedCourse, setSelectedCourse] = useState('');
    const [demoData, setDemoData] = useState(null);

    const handleFileSelect = (e) => {
        const selectedFile = e.target.files[0];
        if (selectedFile) {
            setFile(selectedFile);
            // Preview the file
            const reader = new FileReader();
            reader.onload = (e) => {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const previewData = {};

                // Get first 3 rows from each sheet for preview
                workbook.SheetNames.forEach(sheetName => {
                    const sheet = workbook.Sheets[sheetName];
                    const json = XLSX.utils.sheet_to_json(sheet, { header: 1 });
                    previewData[sheetName] = json.slice(0, 3);
                });

                setPreview(previewData);
            };
            reader.readAsArrayBuffer(selectedFile);
        }
    };

    const handleDemoData = () => {
        // Create demo data structure
        const demoWorkbook = XLSX.utils.book_new();

        // Create demo sheets
        const subjectsData = [
            ['Subject Name', 'Description'],
            ['Mathematics', 'Core mathematics concepts'],
            ['Physics', 'Fundamental physics principles']
        ];

        const chaptersData = [
            ['Subject ID', 'Chapter Name', 'Description'],
            ['1', 'Algebra', 'Basic algebraic concepts'],
            ['1', 'Geometry', 'Geometric principles'],
            ['2', 'Mechanics', 'Basic mechanics']
        ];

        // Add sheets to workbook
        XLSX.utils.book_append_sheet(demoWorkbook, XLSX.utils.aoa_to_sheet(subjectsData), 'Subjects');
        XLSX.utils.book_append_sheet(demoWorkbook, XLSX.utils.aoa_to_sheet(chaptersData), 'Chapters');

        // Generate blob and download
        const wbout = XLSX.write(demoWorkbook, { bookType: 'xlsx', type: 'array' });
        const blob = new Blob([wbout], { type: 'application/octet-stream' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', 'demo_course_data.xlsx');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
    };

    const handleUpload = async () => {
        if (!file) {
            toast.error('Please select a file first');
            return;
        }
        if (!selectedCourse) {
            toast.error('Please select a course first');
            return;
        }

        setUploading(true);
        setUploadStatus([]);

        try {
            const formData = new FormData();
            formData.append('file', file);

            const response = await axios.post('/api/admin/bulk-upload', formData, {
                headers: {
                    'Content-Type': 'multipart/form-data'
                },
                params: {
                    courseId: selectedCourse
                },
                onUploadProgress: (progressEvent) => {
                    const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
                    setUploadStatus(prev => [...prev, { type: 'progress', message: `Uploading: ${percentCompleted}%` }]);
                }
            });

            setUploadStatus(prev => [...prev, { type: 'success', message: 'Upload completed successfully' }]);
            toast.success('Course structure uploaded successfully!');
            navigate('/admin/courses');
        } catch (error) {
            setUploadStatus(prev => [...prev, { type: 'error', message: error.response?.data?.message || 'Upload failed' }]);
            toast.error('Upload failed');
        } finally {
            setUploading(false);
        }
    };

    const downloadTemplate = () => {
        axios.get('/api/admin/download-template', {
            responseType: 'blob'
        }).then((response) => {
            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', 'course_template.xlsx');
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        });
    };

    return (
        <AdminLayout>
        <div className="bulk-upload-container">
            <h2>Bulk Upload Course Structure</h2>

            <div className="course-selection">
                <label htmlFor="courseSelect">Select Course:</label>
                <select
                    id="courseSelect"
                    value={selectedCourse}
                    onChange={(e) => setSelectedCourse(e.target.value)}
                    required
                >
                    <option value="">Select a course...</option>
                    {courses.map((course) => (
                        <option key={course._id} value={course._id}>
                            {course.name}
                        </option>
                    ))}
                </select>
            </div>

            <div className="upload-section">
                <div className="upload-area" onClick={() => document.getElementById('fileInput').click()}>
                    <input
                        type="file"
                        id="fileInput"
                        accept=".xlsx,.xls,.csv"
                        onChange={handleFileSelect}
                        style={{ display: 'none' }}
                    />
                    <div className="upload-icon">📁</div>
                    <p>Drag & drop Excel file here or click to browse</p>
                    <p className="file-info">{file ? file.name : 'No file selected'}</p>
                </div>

                <div className="template-buttons">
                    <button onClick={downloadTemplate} className="template-button">
                        Download Template
                    </button>
                    <button onClick={handleDemoData} className="template-button">
                        Download Demo Data
                    </button>
                </div>
            </div>

            {preview && (
                <div className="preview-section">
                    <h3>File Preview</h3>
                    {Object.entries(preview).map(([sheetName, data]) => (
                        <div key={sheetName} className="sheet-preview">
                            <h4>{sheetName}</h4>
                            <table>
                                <thead>
                                    <tr>
                                        {data[0]?.map((header, index) => (
                                            <th key={index}>{header}</th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody>
                                    {data.slice(1).map((row, rowIndex) => (
                                        <tr key={rowIndex}>
                                            {row?.map((cell, cellIndex) => (
                                                <td key={cellIndex}>{cell}</td>
                                            ))}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    ))}
                </div>
            )}

            <div className="upload-controls">
                <button 
                    onClick={handleUpload} 
                    disabled={!file || uploading}
                    className="upload-button"
                >
                    {uploading ? 'Uploading...' : 'Upload Course Structure'}
                </button>
            </div>

            {uploadStatus.length > 0 && (
                <div className="upload-status">
                    <h3>Upload Status</h3>
                    <ul>
                        {uploadStatus.map((status, index) => (
                            <li key={index} className={`status-item ${status.type}`}>
                                {status.message}
                            </li>
                        ))}
                    </ul>
                </div>
            )}
        </div>
        </AdminLayout>
    );
};

export default BulkUpload;

backend/routes/CourseRoute.js.content:
const express = require("express");
const router = express.Router();
const {
  createCourse,
  getCourses,
  getCourseById,
  updateCourse,
  deleteCourse,
  toggleLock,
  togglePublish,
  getPublishedCourses,
  getPublishedCourseById,
  upsertCourseOverview
} = require("../controllers/CourseController");

const {
  addVideoContent,
  getVideosByCourse,
  updateVideoContent,
  deleteVideoContent,
  toggleVideoFreeStatus,
  bulkUploadVideos
} = require("../controllers/VideoContentController");

const {
  getCourseMockTestSeries,
  createCourseMockTestSeries,
  updateCourseMockTestSeries,
  deleteCourseMockTestSeries,
  getSeriesTests,
  createSeriesTest,
  updateSeriesTest,
  deleteSeriesTest
} = require("../controllers/CourseMockTestController");

const {
  getCourseMockTests,
  createCourseMockTest,
  updateCourseMockTest,
  deleteCourseMockTest
} = require("../controllers/DirectCourseMockTestController");

// ✅ Auth & Permission Middleware
const { authMiddleware } = require("../middleware/authMiddleware");
const { checkPermission } = require("../middleware/permissionMiddleware");

// ✅ Multer setup
const multer = require("multer");

const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, "uploads/");
  },
  filename: function (req, file, cb) {
    cb(null, Date.now() + "-" + file.originalname);
  },
});
const upload = multer({ storage });

// ✅ CREATE course with thumbnail
router.post(
  "/",
  authMiddleware,
  checkPermission("course_create"),
  upload.single("thumbnail"),
  createCourse
);

// ✅ PUBLIC routes first (before parameter routes that can match anything)
// ✅ GET published courses for student LMS (no auth needed)
router.get("/student/published-courses", getPublishedCourses);
router.get("/student/published-courses/:id", getPublishedCourseById);

// ✅ READ all courses or by ID (ADMIN - after public routes)
router.get("/", authMiddleware, checkPermission("course_read"), getCourses);

router.get(
  "/:id",
  authMiddleware,
  checkPermission("course_read"),
  getCourseById
);

// ✅ UPDATE course with optional thumbnail
router.put(
  "/:id/overview",
  authMiddleware,
  checkPermission("course_update"),
  upsertCourseOverview
);

router.put(
  "/:id",
  authMiddleware,
  checkPermission("course_update"),
  upload.single("thumbnail"),
  updateCourse
);

// ✅ DELETE course
router.delete(
  "/:id",
  authMiddleware,
  checkPermission("course_delete"),
  deleteCourse
);

// ✅ TOGGLE lock/unlock
router.put(
  "/toggle-lock/:id",
  authMiddleware,
  checkPermission("course_update"),
  toggleLock
);

// ✅ TOGGLE publish/unpublish
router.put(
  "/toggle-publish/:id",
  authMiddleware,
  checkPermission("course_update"),
  togglePublish
);

// ======================================
// ✅ VIDEO CONTENT ROUTES
// ======================================

// ✅ ADD single video to course (supports both file upload and URL)
router.post(
  "/:courseId/videos",
  authMiddleware,
  checkPermission("course_update"),
  upload.single("videoFile"),
  addVideoContent
);

// ✅ BULK upload videos to course
router.post(
  "/videos/bulk-upload",
  authMiddleware,
  checkPermission("course_update"),
  bulkUploadVideos
);

// ✅ GET all videos for a course (with optional topic filter)
router.get("/:courseId/videos", getVideosByCourse);

// ✅ UPDATE video content (supports file upload or URL update)
router.put(
  "/videos/:videoId",
  authMiddleware,
  checkPermission("course_update"),
  upload.single("videoFile"),
  updateVideoContent
);

// ✅ DELETE video content
router.delete(
  "/videos/:videoId",
  authMiddleware,
  checkPermission("course_update"),
  deleteVideoContent
);

// ✅ TOGGLE video Free/Paid status
router.put(
  "/videos/:videoId/toggle-free",
  authMiddleware,
  checkPermission("course_update"),
  toggleVideoFreeStatus
);

// ======================================
// ✅ COURSE-SPECIFIC MOCK TEST ROUTES
// ======================================

// ✅ GET all mock test series for a course
router.get(
  "/:courseId/mock-test-series",
  authMiddleware,
  checkPermission("course_read"),
  getCourseMockTestSeries
);

// ✅ CREATE mock test series for a course
router.post(
  "/:courseId/mock-test-series",
  authMiddleware,
  checkPermission("course_update"),
  createCourseMockTestSeries
);

// ✅ UPDATE mock test series
router.put(
  "/:courseId/mock-test-series/:seriesId",
  authMiddleware,
  checkPermission("course_update"),
  updateCourseMockTestSeries
);

// ✅ DELETE mock test series
router.delete(
  "/:courseId/mock-test-series/:seriesId",
  authMiddleware,
  checkPermission("course_update"),
  deleteCourseMockTestSeries
);

// ✅ GET all tests in a series
router.get(
  "/:courseId/mock-test-series/:seriesId/tests",
  authMiddleware,
  checkPermission("course_read"),
  getSeriesTests
);

// ✅ CREATE test in a series
router.post(
  "/:courseId/mock-test-series/:seriesId/tests",
  authMiddleware,
  checkPermission("course_update"),
  createSeriesTest
);

// ✅ UPDATE test in a series
router.put(
  "/:courseId/mock-test-series/:seriesId/tests/:testId",
  authMiddleware,
  checkPermission("course_update"),
  updateSeriesTest
);

// ✅ DELETE test from a series
router.delete(
  "/:courseId/mock-test-series/:seriesId/tests/:testId",
  authMiddleware,
  checkPermission("course_update"),
  deleteSeriesTest
);

// ======================================
// ✅ DIRECT COURSE MOCK TEST ROUTES (NO SERIES)
// ======================================

// ✅ GET all mock tests directly for a course
router.get(
  "/:courseId/mock-tests",
  authMiddleware,
  checkPermission("course_read"),
  getCourseMockTests
);

// ✅ CREATE mock test directly for a course
router.post(
  "/:courseId/mock-tests",
  authMiddleware,
  checkPermission("course_update"),
  createCourseMockTest
);

// ✅ UPDATE mock test directly for a course
router.put(
  "/:courseId/mock-tests/:testId",
  authMiddleware,
  checkPermission("course_update"),
  updateCourseMockTest
);

// ✅ DELETE mock test directly from a course
router.delete(
  "/:courseId/mock-tests/:testId",
  authMiddleware,
  checkPermission("course_update"),
  deleteCourseMockTest
);

module.exports = router;

