/* ================================
   FIX OVERRIDES: Buttons + Actions
   (ADD AT THE END - DO NOT REMOVE EXISTING CSS)
=================================== */

/* Ensure action row doesn’t collapse */
.lc-card-actions,
.lc-modal-footer,
.lc-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

/* Make all lc-btn consistent for <a>, <button>, <span> */
.lc-btn {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 8px;

  padding: 10px 14px;
  min-height: 40px;
  border-radius: 10px;

  border: 1px solid rgba(0, 0, 0, 0.12);
  background: #ffffff;
  color: #111827;

  font-size: 14px;
  font-weight: 600;
  line-height: 1;

  cursor: pointer;
  text-decoration: none !important;
  user-select: none;
  white-space: nowrap;
}

/* For anchor buttons */
a.lc-btn {
  text-decoration: none !important;
}

/* Remove default button styling conflicts */
button.lc-btn {
  appearance: none;
  -webkit-appearance: none;
  outline: none;
}

/* Primary button (Join Now / Watch Recording) */
.lc-btn.primary {
  background: #2563eb !important;
  border-color: #2563eb !important;
  color: #ffffff !important;
}

/* Hover */
.lc-btn:hover {
  filter: brightness(0.98);
  transform: translateY(-0.5px);
}

/* Disabled / coming soon */
.lc-btn.link-coming-soon {
  background: #f3f4f6 !important;
  border-color: #e5e7eb !important;
  color: #6b7280 !important;
  cursor: not-allowed !important;
}

/* Reminder active state */
.lc-btn.active {
  background: #111827 !important;
  border-color: #111827 !important;
  color: #ffffff !important;
}

/* If refresh button uses lc-btn */
.lc-actions .lc-btn[disabled] {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* Make action row breathe */
.lc-card-actions {
  margin-top: 12px;
}

/* Optional: make cards not hide buttons */
.lc-card {
  overflow: visible;
}

/* Small screens: full width buttons */
@media (max-width: 640px) {

  .lc-card-actions .lc-btn,
  .lc-modal-footer .lc-btn,
  .lc-actions .lc-btn {
    width: 100%;
    justify-content: center;
  }
}

/* Recording text */
.lc-no-recording {
  display: inline-block;
  padding: 10px 12px;
  border-radius: 10px;
  background: #f9fafb;
  border: 1px dashed #e5e7eb;
  color: #6b7280;
  font-weight: 600;
}

/* ================================================
   LIVE CLASSES - ENHANCED MOBILE RESPONSIVE
   ================================================ */
@media (max-width: 768px) {
  .lc-view {
    padding-bottom: 80px;
  }

  .lc-header {
    padding: 14px;
    flex-wrap: wrap;
    gap: 10px;
  }

  .lc-page-title {
    font-size: 22px;
    width: 100%;
  }

  /* Back button full width */
  .lc-back-btn,
  .lc-header .back-btn {
    width: 100%;
    text-align: center;
    padding: 12px 16px;
    min-height: 44px;
    border-radius: 10px;
  }

  /* Tab controls */
  .lc-tabs,
  .lc-filter-tabs {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 0 14px;
    margin-bottom: 16px;
  }

  .lc-tabs .tab,
  .lc-filter-tabs .tab,
  .lc-tab-btn {
    flex: 1 1 calc(33.33% - 8px);
    min-width: 90px;
    text-align: center;
    min-height: 44px;
    padding: 10px 12px;
    font-size: 13px;
    border-radius: 10px;
  }

  /* Video wrap */
  .lc-video-wrap {
    padding: 0 14px 14px;
  }

  .lc-placeholder {
    min-height: 200px;
  }

  /* Meta items */
  .lc-meta {
    padding: 0 14px 14px;
    gap: 10px;
  }

  .lc-meta-item {
    padding: 14px;
  }

  .lc-meta-label {
    font-size: 11px;
  }

  .lc-meta-value {
    font-size: 14px;
  }

  /* Cards */
  .lc-card {
    padding: 14px;
    margin: 0 14px 14px;
    border-radius: 12px;
  }

  /* Empty state */
  .lc-empty-state,
  .lc-no-classes {
    padding: 40px 20px;
    text-align: center;
  }

  .lc-empty-state img,
  .lc-no-classes img {
    max-width: 100px;
    margin: 0 auto 16px;
  }

  .lc-empty-state h3,
  .lc-no-classes h3 {
    font-size: 18px;
    margin-bottom: 8px;
  }

  .lc-empty-state p,
  .lc-no-classes p {
    font-size: 14px;
    line-height: 1.5;
  }

  /* Sticky bar */
  .lc-sticky-bar {
    padding: 12px 14px;
    gap: 10px;
    flex-wrap: wrap;
  }

  .lc-bar-btn {
    flex: 1 1 calc(50% - 10px);
    min-width: 120px;
    text-align: center;
    min-height: 44px;
  }

  /* Notes */
  .lc-notes {
    padding: 0 14px;
    margin-bottom: 100px;
  }

  .lc-notes-title {
    font-size: 16px;
  }
}

@media (max-width: 400px) {
  .lc-tabs .tab,
  .lc-filter-tabs .tab {
    flex: 1 1 100%;
  }

  .lc-bar-btn {
    flex: 1 1 100%;
  }
}

