                          <td style={{ padding: "10px" }}>
                            {student.studentName}
                            {student.isCurrentUser && (
                              <span
                                style={{
                                  marginLeft: "8px",
                                  fontSize: "12px",
                                  background: "#667eea",
                                  color: "white",
                                  padding: "2px 6px",
                                  borderRadius: "4px",
                                }}
                              >
                                You
                              </span>
                            )}
                          </td>
                          <td
                            style={{
                              padding: "10px",
                              textAlign: "center",
                              fontWeight: "bold",
                              color: "#667eea",
                            }}
                          >
                            {student.score}
                          </td>
                          <td style={{ padding: "10px", textAlign: "center" }}>
                            {student.timeTakenMinutes} min
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </>
              ) : (
                <div
                  style={{
                    textAlign: "center",
                    padding: "40px",
                    color: "#888",
                  }}
                >
                  No leaderboard data available
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    );
  };

  const renderDoubtsContent = () => <DiscussionForum />;

  const renderMaterialsContent = () => (
    <div className="materials-content">
      <div className="section-header">
