            <p>Check back later for new materials or try different filters.</p>
          </div>
        ) : (
          studyMaterials.map((material) => (
            <div key={material._id} className="material-card">
              <div className="material-icon">
                {material.type === "PDF" ? (
                  <FiFileText />
