            {
              day: "Wednesday",
              date: "17",
              events: [
                { time: "3:00 PM", title: "Verbal Class", type: "class" },
              ],
            },
            {
              day: "Thursday",
              date: "18",
              events: [
                { time: "2:00 PM", title: "DI Practice", type: "practice" },
              ],
            },
            {
              day: "Friday",
              date: "19",
              events: [
                { time: "4:00 PM", title: "Doubt Session", type: "doubt" },
