            <h3>No Announcements</h3>
            <p>Check back later for new announcements.</p>
          </div>
        ) : (
          announcements.map((announcement) => (
            <div
              key={announcement._id}
              className={`announcement-card ${announcement.isUnread ? "unread" : ""}`}
              onClick={() => {
