const mongoose = require("mongoose");
const bcrypt = require("bcrypt");

const userSchema = new mongoose.Schema({
    email: {
        type: String,
        unique: true,
        sparse: true,
        trim: true
    },
    phoneNumber: {
        type: String,
        unique: true,
        sparse: true,
        match: [/^\d{10}$/, "Invalid phone number"],
    },
    password: {
        type: String,
        default: null,
    },
    isEmailVerified: {
        type: Boolean,
        default: false,
    },
    isPhoneVerified: {
        type: Boolean,
        default: false,
    },
    role: {
        type: String,
        enum: ["admin", "student", "subadmin"],
        default: "student",
    },
    name: {
        type: String,
        default: null,
    },
    dob: {
        type: String,
        default: null,
    },
    gender: {
        type: String,
        enum: ["Male", "Female", "Other"],
        default: null,
    },
    city: {
        type: String,
