import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import { motion, AnimatePresence } from "framer-motion";
import "./CourseOverview.css";

const parseList = (value) => {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value === "string") return value.split(/\r?\n+/).map((v) => v.trim()).filter(Boolean);
  return [];
};

const useQuery = () => new URLSearchParams(typeof window !== 'undefined' ? window.location.search : '');

const OverviewSection = ({ title, children, icon }) => (
  <motion.div
    className="co-card"
    initial={{ opacity: 0, y: 8 }}
    whileInView={{ opacity: 1, y: 0 }}
    viewport={{ once: true, amount: 0.3 }}
    transition={{ duration: 0.25 }}
  >
    <div className="co-card-header">
      <span className="co-card-icon" aria-hidden>{icon}</span>
      <h3 className="co-card-title">{title}</h3>
    </div>
    <div className="co-card-body">{children}</div>
  </motion.div>
);

const CourseOverview = () => {
  const query = useQuery();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [course, setCourse] = useState(null);

  const courseId = query.get("id");
  const slug = query.get("slug");

  const builderPublicKey = (typeof window !== 'undefined' && window.__BUILDER_PUBLIC_API_KEY__) || process.env.REACT_APP_BUILDER_PUBLIC_API_KEY || '';
  const builderModel = (typeof window !== 'undefined' && window.__BUILDER_MODEL__) || process.env.REACT_APP_BUILDER_MODEL || 'courses';

  async function fetchFromBuilder() {
    if (!builderPublicKey) return null;
    const queryObj = slug ? { 'data.slug': slug } : (courseId ? { 'data.courseId': String(courseId) } : {});
    const qs = new URLSearchParams({ apiKey: builderPublicKey, limit: '1', query: JSON.stringify(queryObj) }).toString();
    const url = `https://cdn.builder.io/api/v3/content/${encodeURIComponent(builderModel)}?${qs}`;
    const { data } = await axios.get(url, { timeout: 8000 });
    const item = data?.results?.[0];
    if (!item) return null;
    const d = item.data || {};
    const overview = d.overview || {};
    // normalize to match backend course shape for UI reuse
    return {
      _id: d.courseId || item.id,
      name: d.name,
      price: d.price,
      thumbnail: d.thumbnail,
      overview: {
        description: overview.description || '',
        materialIncludes: Array.isArray(overview.materialIncludes) ? overview.materialIncludes : [],
        requirements: Array.isArray(overview.requirements) ? overview.requirements : [],
      },
    };
  }

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setError("");
      try {
        let fromBuilder = null;
        try {
          fromBuilder = await fetchFromBuilder();
        } catch {}
        if (!cancelled && fromBuilder) {
          setCourse(fromBuilder);
          return;
        }
        if (courseId) {
          const { data } = await axios.get(`/api/courses/student/published-courses/${courseId}`);
          if (!cancelled) setCourse(data.course || null);
        } else {
          const { data } = await axios.get("/api/courses/student/published-courses");
          const list = Array.isArray(data.courses) ? data.courses : [];
          if (!cancelled) setCourse(list[0] || null);
        }
      } catch (e) {
        if (!cancelled) setError(e?.response?.data?.message || e.message || "Failed to load course overview");
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    load();
    return () => {
      cancelled = true;
    };
  }, [courseId, slug, builderPublicKey, builderModel]);

  const overview = useMemo(() => course?.overview || {}, [course]);
  const materials = useMemo(() => parseList(overview?.materialIncludes), [overview]);
  const requirements = useMemo(() => parseList(overview?.requirements), [overview]);

  if (loading) {
    return (
      <div className="co-container" aria-busy="true" aria-live="polite">
        <div className="co-skel-row" />
        <div className="co-skel-row" />
        <div className="co-skel-row" />
      </div>
    );
  }

  if (error || !course) {
    return (
      <div className="co-container">
        <div className="co-empty">
          <p>{error || "No course available"}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="co-container" data-course-id={course._id}>
      <AnimatePresence>
        {(overview?.description || materials.length || requirements.length) ? (
          <motion.div initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} viewport={{ once: true }}>
            <h2 className="co-heading">Course Overview</h2>
            <div className="co-grid">
              <OverviewSection title="Description" icon="📝">
                {overview?.description ? (
                  <p className="co-text" data-builder-field="overview.description">{overview.description}</p>
                ) : (
                  <p className="co-muted">No description added yet.</p>
                )}
              </OverviewSection>

              <OverviewSection title="Material Includes" icon="📦">
                {materials.length ? (
                  <ul className="co-list" data-builder-field="overview.materialIncludes">
                    {materials.map((item, idx) => (
                      <li key={idx} className="co-list-item">{item}</li>
                    ))}
                  </ul>
                ) : (
                  <p className="co-muted">No materials listed.</p>
                )}
              </OverviewSection>

              <OverviewSection title="Requirements" icon="✅">
                {requirements.length ? (
                  <ul className="co-list" data-builder-field="overview.requirements">
                    {requirements.map((item, idx) => (
                      <li key={idx} className="co-list-item">{item}</li>
                    ))}
                  </ul>
                ) : (
                  <p className="co-muted">No requirements specified.</p>
                )}
              </OverviewSection>
            </div>
          </motion.div>
        ) : (
          <div className="co-empty"><p>Overview will appear here once added by admin.</p></div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CourseOverview;

frontend/src/pages/mainAdmin/DiscussionM.content:
import React, { useState, useEffect } from 'react';
import './DiscussionManagement.css';
import AdminLayout from '../AdminLayout/AdminLayout';
import {
  FiMessageCircle,
  FiUsers,
  FiEye,
  FiCheckCircle,
  FiXCircle,
  FiEdit3,
  FiTrash2,
  FiSearch,
  FiFilter,
  FiBarChart2,
  FiClock,
  FiThumbsUp,
  FiThumbsDown,
  FiStar,
  FiMoreVertical,
  FiAlertTriangle,
  FiRefreshCw
} from 'react-icons/fi';

const DiscussionManagement = () => {
  const [activeTab, setActiveTab] = useState('discussions');
  const [discussions, setDiscussions] = useState([]);
  const [replies, setReplies] = useState([]);
  const [stats, setStats] = useState({});
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({
    status: 'all',
    category: 'all',
    search: ''
  });

  const fetchDiscussions = async () => {
    setLoading(true);
    try {
      const adminToken = localStorage.getItem('adminToken');
      const queryParams = new URLSearchParams({
        page: 1,
        limit: 20,
        status: filters.status !== 'all' ? filters.status : '',
        category: filters.category !== 'all' ? filters.category : '',
        search: filters.search
      });

      const response = await fetch(`/api/admin/discussions/discussions?${queryParams}`, {
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      if (data.success) {
        setDiscussions(data.discussions);
      } else {
        console.error('Failed to fetch discussions:', data.message);
      }
    } catch (error) {
      console.error('Error fetching discussions:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchReplies = async () => {
    setLoading(true);
    try {
      const adminToken = localStorage.getItem('adminToken');
      const queryParams = new URLSearchParams({
        page: 1,
        limit: 20,
        status: filters.status !== 'all' ? filters.status : ''
      });

      const response = await fetch(`/api/admin/discussions/replies?${queryParams}`, {
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      if (data.success) {
        setReplies(data.replies);
      } else {
        console.error('Failed to fetch replies:', data.message);
      }
    } catch (error) {
      console.error('Error fetching replies:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const adminToken = localStorage.getItem('adminToken');
      const response = await fetch('/api/admin/discussions/discussions/stats', {
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      if (data.success) {
        setStats(data.stats);
      }
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  };

  useEffect(() => {
    fetchStats();
  }, []);

  useEffect(() => {
    if (activeTab === 'discussions') {
      fetchDiscussions();
    } else if (activeTab === 'replies') {
      fetchReplies();
    }
  }, [activeTab, filters]);

  const moderateDiscussion = async (discussionId, action, moderationNote = '') => {
    try {
      const adminToken = localStorage.getItem('adminToken');
      const response = await fetch(`/api/admin/discussions/discussions/${discussionId}/moderate`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ action, moderationNote })
      });

      const data = await response.json();
      if (data.success) {
        fetchDiscussions();
        fetchStats();
        alert(`Discussion ${action}ed successfully`);
      } else {
        alert(data.message || 'Failed to moderate discussion');
      }
    } catch (error) {
      console.error('Error moderating discussion:', error);
      alert('Failed to moderate discussion');
    }
  };

  const moderateReply = async (replyId, action, moderationNote = '') => {
    try {
      const adminToken = localStorage.getItem('adminToken');
      const response = await fetch(`/api/admin/discussions/replies/${replyId}/moderate`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ action, moderationNote })
      });

      const data = await response.json();
      if (data.success) {
        fetchReplies();
        alert(`Reply ${action}ed successfully`);
      } else {
        alert(data.message || 'Failed to moderate reply');
      }
    } catch (error) {
      console.error('Error moderating reply:', error);
      alert('Failed to moderate reply');
    }
  };

  const deleteDiscussion = async (discussionId) => {
    if (!window.confirm('Are you sure you want to delete this discussion? This action cannot be undone.')) {
      return;
    }

    try {
      const adminToken = localStorage.getItem('adminToken');
      const response = await fetch(`/api/admin/discussions/discussions/${discussionId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      if (data.success) {
        fetchDiscussions();
        fetchStats();
        alert('Discussion deleted successfully');
      } else {
        alert(data.message || 'Failed to delete discussion');
      }
    } catch (error) {
      console.error('Error deleting discussion:', error);
      alert('Failed to delete discussion');
    }
  };

  const deleteReply = async (replyId) => {
    if (!window.confirm('Are you sure you want to delete this reply? This action cannot be undone.')) {
      return;
    }

    try {
      const adminToken = localStorage.getItem('adminToken');
      const response = await fetch(`/api/admin/discussions/replies/${replyId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${adminToken}`,
          'Content-Type': 'application/json'
        }
      });

      const data = await response.json();
      if (data.success) {
        fetchReplies();
        alert('Reply deleted successfully');
      } else {
        alert(data.message || 'Failed to delete reply');
      }
    } catch (error) {
      console.error('Error deleting reply:', error);
      alert('Failed to delete reply');
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      pending: { color: '#f59e0b', bg: '#fef3c7', text: 'Pending' },
      approved: { color: '#10b981', bg: '#d1fae5', text: 'Approved' },
      rejected: { color: '#ef4444', bg: '#fee2e2', text: 'Rejected' },
      resolved: { color: '#8b5cf6', bg: '#ede9fe', text: 'Resolved' }
    };

    const config = statusConfig[status] || statusConfig.pending;
    return (
      <span 
        className="status-badge"
        style={{ 
          color: config.color, 
          backgroundColor: config.bg 
        }}
      >
        {config.text}
      </span>
    );
  };

  const StatsOverview = () => (
    <div className="stats-overview">
      <div className="stat-card">
        <div className="stat-icon">
          <FiMessageCircle />
        </div>
        <div className="stat-info">
          <h3>{stats.total || 0}</h3>
          <p>Total Discussions</p>
        </div>
      </div>

      <div className="stat-card">
        <div className="stat-icon pending">
          <FiClock />
        </div>
        <div className="stat-info">
          <h3>{stats.pending || 0}</h3>
          <p>Pending Approval</p>
        </div>
      </div>

      <div className="stat-card">
        <div className="stat-icon approved">
          <FiCheckCircle />
        </div>
        <div className="stat-info">
          <h3>{stats.approved || 0}</h3>
          <p>Approved</p>
        </div>
      </div>

      <div className="stat-card">
        <div className="stat-icon">
          <FiUsers />
        </div>
        <div className="stat-info">
          <h3>{stats.totalReplies || 0}</h3>
          <p>Total Replies</p>
        </div>
      </div>
    </div>
  );

  const DiscussionCard = ({ discussion }) => (
    <div className="management-card">
      <div className="card-header">
        <div className="discussion-info">
          <h4>{discussion.title}</h4>
          <div className="discussion-meta">
            <span>By {discussion.askedBy?.name || 'Anonymous'}</span>
            <span>{formatDate(discussion.createdAt)}</span>
            <span className="category-tag">{discussion.category}</span>
            {getStatusBadge(discussion.status)}
          </div>
        </div>
        <div className="card-actions">
          <div className="action-dropdown">
            <button className="action-btn">
              <FiMoreVertical />
            </button>
            <div className="dropdown-menu">
              {discussion.status === 'pending' && (
                <>
                  <button onClick={() => moderateDiscussion(discussion._id, 'approve')}>
                    <FiCheckCircle /> Approve
                  </button>
                  <button onClick={() => moderateDiscussion(discussion._id, 'reject')}>
                    <FiXCircle /> Reject
                  </button>
                </>
              )}
              <button onClick={() => moderateDiscussion(discussion._id, discussion.isPublished ? 'unpublish' : 'publish')}>
                <FiEye /> {discussion.isPublished ? 'Unpublish' : 'Publish'}
              </button>
              <button onClick={() => moderateDiscussion(discussion._id, discussion.isPinned ? 'unpin' : 'pin')}>
                <FiStar /> {discussion.isPinned ? 'Unpin' : 'Pin'}
              </button>
              <button onClick={() => deleteDiscussion(discussion._id)} className="delete-action">
                <FiTrash2 /> Delete
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="card-content">
        <p>{discussion.content.substring(0, 200)}...</p>
        <div className="discussion-stats">
          <span><FiEye /> {discussion.views || 0} views</span>
          <span><FiMessageCircle /> {discussion.replies?.length || 0} replies</span>
          <span><FiThumbsUp /> {discussion.upvotes?.length || 0} upvotes</span>
        </div>
      </div>
    </div>
  );

  const ReplyCard = ({ reply }) => (
    <div className="management-card">
      <div className="card-header">
        <div className="reply-info">
          <h4>Reply to: {reply.discussionId?.title || 'Unknown Discussion'}</h4>
          <div className="reply-meta">
            <span>By {reply.repliedBy?.name || 'Anonymous'}</span>
            <span>{formatDate(reply.createdAt)}</span>
            {getStatusBadge(reply.status)}
            {reply.isBestAnswer && (
              <span className="best-answer-badge">
                <FiCheckCircle /> Best Answer
              </span>
            )}
          </div>
        </div>
        <div className="card-actions">
          <div className="action-dropdown">
            <button className="action-btn">
              <FiMoreVertical />
            </button>
            <div className="dropdown-menu">
              {reply.status === 'pending' && (
                <>
                  <button onClick={() => moderateReply(reply._id, 'approve')}>
                    <FiCheckCircle /> Approve
                  </button>
                  <button onClick={() => moderateReply(reply._id, 'reject')}>
                    <FiXCircle /> Reject
                  </button>
                </>
              )}
              <button onClick={() => moderateReply(reply._id, reply.isBestAnswer ? 'unmark_best' : 'mark_best')}>
                <FiCheckCircle /> {reply.isBestAnswer ? 'Unmark Best' : 'Mark as Best'}
              </button>
              <button onClick={() => deleteReply(reply._id)} className="delete-action">
                <FiTrash2 /> Delete
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="card-content">
        <p>{reply.content}</p>
        <div className="reply-stats">
          <span><FiThumbsUp /> {reply.upvotes?.length || 0} upvotes</span>
          <span><FiThumbsDown /> {reply.downvotes?.length || 0} downvotes</span>
        </div>
      </div>
    </div>
  );

  return (
    <AdminLayout>
    <div className="discussion-management">
      <div className="management-header">
        <h1>Discussion Management</h1>
        <button onClick={() => {
