/* Root page */
.scm-page {
  min-height: 100vh;
  background: #f3f4f8;
  padding: 24px;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  color: #0f172a;
}

/* Center card for loading / error */
.scm-center-card {
  max-width: 420px;
  margin: 72px auto;
  background: #ffffff;
  border-radius: 20px;
  padding: 32px 28px;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.15);
  text-align: center;
}

.scm-loader {
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: 3px solid #e5e7eb;
  border-top-color: #6366f1;
  margin: 0 auto 16px;
  animation: scm-spin 0.7s linear infinite;
}

@keyframes scm-spin {
  to {
    transform: rotate(360deg);
  }
}

.scm-muted {
  color: #6b7280;
  font-size: 0.9rem;
}

/* ERROR */
.scm-error-card {
  border: 1px solid rgba(248, 113, 113, 0.35);
}

.scm-error-icon {
  font-size: 40px;
  color: #ef4444;
  margin-bottom: 12px;
}

.scm-upcoming-icon {
  color: #f59e0b;
}

.scm-start-date-info {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 20px;
  background: linear-gradient(135deg, #fef3c7, #fde68a);
  border-radius: 12px;
  margin: 16px 0;
  color: #92400e;
  font-size: 0.95rem;
}

.scm-start-date-info svg {
  font-size: 18px;
}

/* HEADER */
.scm-header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 28px;
  border-radius: 24px;
  background: linear-gradient(120deg, #4f46e5, #7c3aed, #ec4899);
  color: white;
  box-shadow: 0 20px 40px rgba(79, 70, 229, 0.35);
  margin-bottom: 20px;
}

.scm-header-left {
  flex: 2;
}

.scm-badge-live {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.25);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}

.scm-title {
  font-size: 1.9rem;
  font-weight: 700;
  margin: 4px 0 8px;
}

.scm-description {
  font-size: 0.95rem;
  color: rgba(249, 250, 251, 0.9);
  max-width: 620px;
}

.scm-header-right {
  flex: 1.2;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  align-items: flex-end;
  flex-wrap: wrap;
}

.scm-stat-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.22);
  font-size: 0.85rem;
  min-width: 120px;
}

.scm-stat-pill svg {
  font-size: 18px;
}

.scm-stat-label {
  display: block;
  color: rgba(226, 232, 240, 0.9);
  font-size: 0.75rem;
}

.scm-stat-value {
  font-weight: 600;
}

/* TABS */
.scm-tabs {
  margin-top: 18px;
  margin-bottom: 14px;
  display: flex;
  gap: 8px;
  background: #e5e7eb;
  padding: 4px;
  border-radius: 999px;
  align-items: center;
}

.scm-tab {
  flex: 1;
  border: none;
  outline: none;
  border-radius: 999px;
  padding: 8px 14px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 0.85rem;
  color: #4b5563;
  cursor: pointer;
  transition: all 0.18s ease-out;
}

.scm-tab svg {
  font-size: 14px;
}

.scm-tab-count {
  padding: 1px 8px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.08);
  font-size: 0.75rem;
}

.scm-tab.is-active {
  background: #111827;
  color: #ffffff;
}

.scm-tab.is-active .scm-tab-count {
  background: #f9fafb;
  color: #111827;
}

/* MAIN LAYOUT */
.scm-main {
  margin-top: 8px;
}

.scm-section {
  background: #ffffff;
  border-radius: 24px;
  padding: 22px 22px 18px;
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.12);
}

.scm-section-header h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.25rem;
  margin-bottom: 4px;
}

.scm-section-header svg {
  color: #4f46e5;
}

.scm-section-header .scm-muted {
  font-size: 0.86rem;
}

/* Empty state */
.scm-empty {
  margin-top: 26px;
  padding: 42px 26px;
  text-align: center;
  border-radius: 20px;
  background: #f9fafb;
  border: 1px dashed #d1d5db;
}

.scm-empty-icon {
  font-size: 32px;
  color: #9ca3af;
  margin-bottom: 10px;
}

/* Recorded layout */
.scm-recorded-layout {
  margin-top: 18px;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.7fr);
  gap: 18px;
}

/* LEFT – topic + list */
.scm-video-list {
  max-height: 630px;
  overflow-y: auto;
  padding-right: 4px;
}

.scm-topic-block + .scm-topic-block {
  margin-top: 16px;
}

.scm-topic-header {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-bottom: 6px;
}

.scm-topic-header h3 {
  font-size: 0.98rem;
  font-weight: 600;
}

.scm-topic-chip {
  font-size: 0.7rem;
  padding: 2px 7px;
  border-radius: 999px;
  background: #eef2ff;
  color: #4f46e5;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.scm-topic-count {
  font-size: 0.75rem;
  color: #6b7280;
}

.scm-video-items {
  border-radius: 14px;
  border: 1px solid #e5e7eb;
  background: #f9fafb;
  overflow: hidden;
}

/* individual video item */
.scm-video-item {
  display: flex;
  gap: 10px;
  width: 100%;
  border: none;
  background: transparent;
  padding: 8px 10px;
  align-items: center;
  cursor: pointer;
  transition: background 0.15s ease-out, transform 0.12s ease-out;
}

.scm-video-item + .scm-video-item {
  border-top: 1px solid #e5e7eb;
}

.scm-video-item:hover {
  background: #eef2ff;
  transform: translateY(-1px);
}

.scm-video-item.is-active {
  background: #111827;
  color: #f9fafb;
}

.scm-video-thumb {
  width: 72px;
  height: 44px;
  border-radius: 10px;
  overflow: hidden;
  background: #111827;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.scm-video-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.scm-thumb-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #f97316;
