  }

  .left-actions,
  .right-actions {
    justify-content: center;
  }

  .calculator-modal,
  .scratchpad-modal,
  .instructions-modal,
  .question-paper-modal {
    width: 95%;
    max-width: 400px;
  }

  .result-summary {
    grid-template-columns: 1fr;
  }

  /* ================================================
     MOBILE RESPONSIVE - Profile + Status Legend Fix
     ================================================ */

  /* Profile section - centered with proper spacing */
  .profile-section {
    width: 100%;
    padding: 16px 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    background: white;
    border-bottom: 2px solid #4a9fd4;
  }

  .profile-avatar {
    width: 70px;
    height: 70px;
    margin-bottom: 4px;
  }

  .profile-name {
    font-size: 16px;
    font-weight: 600;
    color: #333;
    text-align: center;
  }

  /* Question Legend - prevent text truncation */
  .question-legend {
    padding: 12px 10px;
    background: white;
    border-bottom: 1px solid #ddd;
    max-height: none;
    overflow: visible;
  }

  .legend-row {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 8px;
    align-items: flex-start;
  }

  .legend-row.full-width {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    color: #555;
    min-width: 120px;
    flex: 0 0 auto;
  }

  .legend-box {
    width: 24px;
    height: 24px;
    min-width: 24px;
    flex-shrink: 0;
  }

  .legend-text {
    flex: 1;
    line-height: 1.3;
    word-wrap: break-word;
    white-space: normal;
    font-size: 11px;
  }

  /* Sidebar panel mobile layout */
  .cat-sidebar-panel {
    width: 100%;
    flex-direction: column;
    border-left: none;
    border-top: 1px solid #ddd;
  }

  /* Question palette scrollable on mobile */
  .question-palette {
    max-height: 180px;
    overflow-y: auto;
    padding: 10px;
  }

  .palette-grid {
    grid-template-columns: repeat(6, 1fr);
    gap: 5px;
  }

  .palette-btn {
    width: 36px;
    height: 36px;
    font-size: 12px;
  }
}

/* Extra small screens (480px and below) */
@media (max-width: 480px) {
  .profile-section {
    padding: 14px 10px;
  }

  .profile-avatar {
    width: 60px;
    height: 60px;
  }

  .profile-name {
    font-size: 14px;
  }

  .question-legend {
    padding: 10px 8px;
  }

  .legend-item {
    min-width: 100px;
    font-size: 10px;
  }

  .legend-box {
    width: 22px;
    height: 22px;
    min-width: 22px;
    font-size: 9px;
  }

  .legend-text {
    font-size: 10px;
  }

  .palette-grid {
    grid-template-columns: repeat(5, 1fr);
  }

  .palette-btn {
    width: 32px;
    height: 32px;
    font-size: 11px;
  }
}

