import React, { useState, useEffect } from 'react';
import { fetchWithErrorHandling } from '../../../utils/api';
import AdminLayout from '../AdminLayout/AdminLayout';
import './HierarchyManagement.css';

const HierarchyManagement = () => {
  const [activeTab, setActiveTab] = useState('examCategory');

  const [examCategories, setExamCategories] = useState([]);
  const [examYears, setExamYears] = useState([]);
  const [examSlots, setExamSlots] = useState([]);
  const [topicCategories, setTopicCategories] = useState([]);
  const [topicTestGroups, setTopicTestGroups] = useState([]);

  const [loading, setLoading] = useState(false);
  const [editingItem, setEditingItem] = useState(null);

  const [formData, setFormData] = useState({});

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchExamCategories(),
        fetchExamYears(),
        fetchExamSlots(),
        fetchTopicCategories(),
        fetchTopicTestGroups()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
    setLoading(false);
  };

  const fetchExamCategories = async () => {
    const data = await fetchWithErrorHandling('/api/admin/hierarchy/exam-categories');
    if (data?.categories) setExamCategories(data.categories);
  };

  const fetchExamYears = async () => {
    const data = await fetchWithErrorHandling('/api/admin/hierarchy/exam-years');
    if (data?.years) setExamYears(data.years);
  };

  const fetchExamSlots = async () => {
    const data = await fetchWithErrorHandling('/api/admin/hierarchy/exam-slots');
    if (data?.slots) setExamSlots(data.slots);
  };

  const fetchTopicCategories = async () => {
    const data = await fetchWithErrorHandling('/api/admin/hierarchy/topic-categories');
    if (data?.categories) setTopicCategories(data.categories);
  };

  const fetchTopicTestGroups = async () => {
    const data = await fetchWithErrorHandling('/api/admin/hierarchy/topic-test-groups');
    if (data?.groups) setTopicTestGroups(data.groups);
  };

  const handleCreate = (type) => {
    setEditingItem(null);
    setFormData(getEmptyFormData(type));
  };

  const handleEdit = (type, item) => {
    setEditingItem({ type, id: item._id });
    setFormData(item);
  };

  const handleCancel = () => {
    setEditingItem(null);
    setFormData({});
  };

  const handleSubmit = async (e, type) => {
    e.preventDefault();
    setLoading(true);

    try {
      const endpoint = getEndpoint(type);
      const method = editingItem ? 'PUT' : 'POST';
      const url = editingItem 
        ? `/api/admin/hierarchy/${endpoint}/${editingItem.id}`
        : `/api/admin/hierarchy/${endpoint}`;

      const data = await fetchWithErrorHandling(url, {
        method,
        body: JSON.stringify(formData)
      });

      if (data?.success) {
        alert(`${type} ${editingItem ? 'updated' : 'created'} successfully!`);
        handleCancel();
        fetchAllData();
      }
    } catch (error) {
      alert(`Failed to ${editingItem ? 'update' : 'create'} ${type}: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (type, id) => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;

    setLoading(true);
    try {
      const endpoint = getEndpoint(type);
      const data = await fetchWithErrorHandling(`/api/admin/hierarchy/${endpoint}/${id}`, {
        method: 'DELETE'
      });

      if (data?.success) {
        alert('Deleted successfully!');
        fetchAllData();
      }
    } catch (error) {
      alert(`Failed to delete: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const getEndpoint = (type) => {
    const endpoints = {
      examCategory: 'exam-categories',
      examYear: 'exam-years',
      examSlot: 'exam-slots',
      topicCategory: 'topic-categories',
      topicTestGroup: 'topic-test-groups'
    };
    return endpoints[type];
  };

  const getEmptyFormData = (type) => {
    switch (type) {
      case 'examCategory':
        return { name: '', code: '', description: '', displayOrder: 0 };
      case 'examYear':
        return { examCategoryId: '', label: '', displayOrder: 0 };
      case 'examSlot':
        return { examYearId: '', label: '', slotMonth: '', displayOrder: 0 };
      case 'topicCategory':
        return { name: '', code: '', description: '', displayOrder: 0 };
      case 'topicTestGroup':
        return { topicCategoryId: '', title: '', description: '', displayOrder: 0 };
      default:
        return {};
    }
  };

  const renderExamCategoryForm = () => (
    <form onSubmit={(e) => handleSubmit(e, 'examCategory')} className="hierarchy-form">
      <h3>{editingItem ? 'Edit' : 'Create'} Exam Category</h3>
      <input
        type="text"
        placeholder="Name (e.g., CAT, XAT, SNAP)"
        value={formData.name || ''}
        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
        required
      />
      <input
        type="text"
        placeholder="Code (e.g., CAT, XAT)"
        value={formData.code || ''}
        onChange={(e) => setFormData({ ...formData, code: e.target.value })}
        required
      />
      <textarea
        placeholder="Description"
        value={formData.description || ''}
        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
      />
      <input
        type="number"
        placeholder="Display Order"
        value={formData.displayOrder || 0}
        onChange={(e) => setFormData({ ...formData, displayOrder: parseInt(e.target.value) })}
      />
      <div className="form-actions">
        <button type="submit" className="btn-primary" disabled={loading}>
          {editingItem ? 'Update' : 'Create'}
        </button>
        <button type="button" className="btn-secondary" onClick={handleCancel}>
          Cancel
        </button>
      </div>
    </form>
  );

  const renderExamYearForm = () => (
    <form onSubmit={(e) => handleSubmit(e, 'examYear')} className="hierarchy-form">
      <h3>{editingItem ? 'Edit' : 'Create'} Exam Year</h3>
      <select
        value={formData.examCategoryId || ''}
        onChange={(e) => setFormData({ ...formData, examCategoryId: e.target.value })}
        required
      >
        <option value="">Select Exam Category</option>
        {examCategories.map(cat => (
          <option key={cat._id} value={cat._id}>{cat.name}</option>
        ))}
      </select>
      <input
        type="text"
        placeholder="Year Label (e.g., 2024)"
        value={formData.label || ''}
        onChange={(e) => setFormData({ ...formData, label: e.target.value })}
        required
      />
      <input
        type="number"
        placeholder="Display Order"
        value={formData.displayOrder || 0}
        onChange={(e) => setFormData({ ...formData, displayOrder: parseInt(e.target.value) })}
      />
      <div className="form-actions">
        <button type="submit" className="btn-primary" disabled={loading}>
          {editingItem ? 'Update' : 'Create'}
        </button>
        <button type="button" className="btn-secondary" onClick={handleCancel}>
          Cancel
        </button>
      </div>
    </form>
  );

  const renderExamSlotForm = () => (
    <form onSubmit={(e) => handleSubmit(e, 'examSlot')} className="hierarchy-form">
      <h3>{editingItem ? 'Edit' : 'Create'} Exam Slot</h3>
      <select
        value={formData.examYearId || ''}
        onChange={(e) => setFormData({ ...formData, examYearId: e.target.value })}
        required
      >
        <option value="">Select Exam Year</option>
        {examYears.map(year => (
          <option key={year._id} value={year._id}>
            {year.examCategoryId?.name} - {year.label}
          </option>
        ))}
      </select>
      <input
        type="text"
        placeholder="Slot Label (e.g., Slot 1, Slot A)"
        value={formData.label || ''}
        onChange={(e) => setFormData({ ...formData, label: e.target.value })}
        required
      />
      <input
        type="text"
        placeholder="Slot Month (optional)"
        value={formData.slotMonth || ''}
        onChange={(e) => setFormData({ ...formData, slotMonth: e.target.value })}
      />
      <input
        type="number"
        placeholder="Display Order"
        value={formData.displayOrder || 0}
        onChange={(e) => setFormData({ ...formData, displayOrder: parseInt(e.target.value) })}
      />
      <div className="form-actions">
        <button type="submit" className="btn-primary" disabled={loading}>
          {editingItem ? 'Update' : 'Create'}
        </button>
        <button type="button" className="btn-secondary" onClick={handleCancel}>
          Cancel
        </button>
      </div>
    </form>
  );

  const renderTopicCategoryForm = () => (
    <form onSubmit={(e) => handleSubmit(e, 'topicCategory')} className="hierarchy-form">
      <h3>{editingItem ? 'Edit' : 'Create'} Topic Category</h3>
      <input
        type="text"
        placeholder="Name (e.g., VARC, LRDI, Quant)"
        value={formData.name || ''}
        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
        required
      />
      <input
        type="text"
        placeholder="Code (e.g., VARC, LRDI)"
        value={formData.code || ''}
        onChange={(e) => setFormData({ ...formData, code: e.target.value })}
        required
      />
      <textarea
        placeholder="Description"
        value={formData.description || ''}
        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
      />
      <input
        type="number"
        placeholder="Display Order"
        value={formData.displayOrder || 0}
        onChange={(e) => setFormData({ ...formData, displayOrder: parseInt(e.target.value) })}
      />
      <div className="form-actions">
        <button type="submit" className="btn-primary" disabled={loading}>
          {editingItem ? 'Update' : 'Create'}
        </button>
        <button type="button" className="btn-secondary" onClick={handleCancel}>
          Cancel
        </button>
      </div>
    </form>
  );

  const renderTopicTestGroupForm = () => (
    <form onSubmit={(e) => handleSubmit(e, 'topicTestGroup')} className="hierarchy-form">
      <h3>{editingItem ? 'Edit' : 'Create'} Topic Test Group</h3>
      <select
        value={formData.topicCategoryId || ''}
        onChange={(e) => setFormData({ ...formData, topicCategoryId: e.target.value })}
        required
      >
        <option value="">Select Topic Category</option>
        {topicCategories.map(cat => (
          <option key={cat._id} value={cat._id}>{cat.name}</option>
        ))}
      </select>
      <input
        type="text"
        placeholder="Title (e.g., Algebra, Reading Comprehension)"
        value={formData.title || ''}
        onChange={(e) => setFormData({ ...formData, title: e.target.value })}
        required
      />
      <textarea
        placeholder="Description"
        value={formData.description || ''}
        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
      />
      <input
        type="number"
        placeholder="Display Order"
        value={formData.displayOrder || 0}
        onChange={(e) => setFormData({ ...formData, displayOrder: parseInt(e.target.value) })}
      />
      <div className="form-actions">
        <button type="submit" className="btn-primary" disabled={loading}>
          {editingItem ? 'Update' : 'Create'}
        </button>
        <button type="button" className="btn-secondary" onClick={handleCancel}>
          Cancel
        </button>
      </div>
    </form>
  );

  const renderItemsList = (items, type) => {
    if (!items || items.length === 0) {
      return <p className="no-items">No items found. Create one to get started!</p>;
    }

    return (
      <div className="items-grid">
        {items.map(item => (
          <div key={item._id} className="item-card">
            <h4>{item.name || item.label || item.title}</h4>
            {item.code && <div className="item-code">Code: {item.code}</div>}
            {item.description && <div className="item-desc">{item.description}</div>}
            {item.examCategoryId && (
              <div className="item-parent">Exam: {item.examCategoryId.name}</div>
            )}
            {item.examYearId && (
              <div className="item-parent">
                Year: {item.examYearId.examCategoryId?.name} - {item.examYearId.label}
              </div>
            )}
            {item.topicCategoryId && (
              <div className="item-parent">Category: {item.topicCategoryId.name}</div>
            )}
            {item.slotMonth && <div className="item-month">Month: {item.slotMonth}</div>}
            <div className="item-order">Order: {item.displayOrder}</div>
            <div className="item-actions">
              <button onClick={() => handleEdit(type, item)} className="btn-edit">
                Edit
              </button>
              <button onClick={() => handleDelete(type, item._id)} className="btn-delete">
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    );
  };

  return (
    <AdminLayout>
    <div className="hierarchy-management">
      <div className="page-header">
        <h1>Hierarchy Management</h1>
        <p>Configure the structure for organizing mock tests</p>
      </div>

      <div className="tabs-container">
        <button
          className={activeTab === 'examCategory' ? 'tab active' : 'tab'}
          onClick={() => setActiveTab('examCategory')}
        >
          Exam Categories
        </button>
        <button
          className={activeTab === 'examYear' ? 'tab active' : 'tab'}
          onClick={() => setActiveTab('examYear')}
        >
          Exam Years
        </button>
        <button
          className={activeTab === 'examSlot' ? 'tab active' : 'tab'}
          onClick={() => setActiveTab('examSlot')}
        >
          Exam Slots
        </button>
        <button
          className={activeTab === 'topicCategory' ? 'tab active' : 'tab'}
          onClick={() => setActiveTab('topicCategory')}
        >
          Topic Categories
        </button>
        <button
          className={activeTab === 'topicTestGroup' ? 'tab active' : 'tab'}
          onClick={() => setActiveTab('topicTestGroup')}
        >
          Topic Groups
        </button>
      </div>

      <div className="content-area">
        <div className="form-section">
          {!editingItem && (
            <button
              onClick={() => handleCreate(activeTab)}
              className="btn-create"
            >
              + Create New {activeTab.replace(/([A-Z])/g, ' $1').trim()}
            </button>
          )}

          {(editingItem || formData.name !== undefined || formData.label !== undefined || formData.title !== undefined) && (
            <>
              {activeTab === 'examCategory' && renderExamCategoryForm()}
              {activeTab === 'examYear' && renderExamYearForm()}
              {activeTab === 'examSlot' && renderExamSlotForm()}
              {activeTab === 'topicCategory' && renderTopicCategoryForm()}
              {activeTab === 'topicTestGroup' && renderTopicTestGroupForm()}
            </>
          )}
        </div>

        <div className="items-section">
          <h2>Existing {activeTab.replace(/([A-Z])/g, ' $1').trim()}s</h2>
          {loading ? (
            <p>Loading...</p>
          ) : (
            <>
              {activeTab === 'examCategory' && renderItemsList(examCategories, 'examCategory')}
              {activeTab === 'examYear' && renderItemsList(examYears, 'examYear')}
              {activeTab === 'examSlot' && renderItemsList(examSlots, 'examSlot')}
              {activeTab === 'topicCategory' && renderItemsList(topicCategories, 'topicCategory')}
              {activeTab === 'topicTestGroup' && renderItemsList(topicTestGroups, 'topicTestGroup')}
            </>
          )}
        </div>
      </div>
    </div>
    </AdminLayout>
  );
};

export default HierarchyManagement;

frontend/src/CoursePurchasepage/Cat26Adv.content:
/* AdvanceOMETOfflinePage.css */

/* ------------------ Tokens ------------------ */
:root{
  --aocp-font:"Manrope","Inter","Segoe UI",system-ui,-apple-system,Roboto,Helvetica,Arial,sans-serif;
  --aocp-weight-heading:700;
  --aocp-weight-strong:600;
  --aocp-weight-body:500;

  --aocp-size-title:clamp(22px,2.0vw,28px);
  --aocp-size-h:clamp(20px,1.9vw,26px);
  --aocp-size-sub:18px;
  --aocp-size-body:16px;
  --aocp-size-small:14px;
  --aocp-line:1.55;

  --aocp-primary:#1A237E;
  --aocp-accent:#D8583F;
  --aocp-ink:#1d1d1f;
  --aocp-ink-2:#111;
  --aocp-muted:#888;
  --aocp-border:#999;
  --aocp-soft:#f4f6f8;
}

/* ------------------ Reset/Base ------------------ */
*{margin:0;padding:0;box-sizing:border-box}
body{
  font-family:var(--aocp-font);
  font-size:var(--aocp-size-body);
  font-weight:var(--aocp-weight-body);
  line-height:var(--aocp-line);
  background:var(--aocp-soft);
  color:var(--aocp-ink);
}
.container{max-width:1600px;width:100%;margin:0 auto}
.row{display:flex;gap:30px}

/* ------------------ Page ------------------ */
.aocp-page{background:#fff;padding-top:40px}

/* ------------------ Left ------------------ */
.aocp-left{flex:70%;padding-left:50px}
.aocp-video iframe{
  width:100%;
  height:400px;
  border-radius:10px;
  border:none;
  margin-bottom:20px;
}
.aocp-title{
  text-transform:uppercase;
  letter-spacing:.4px;
  color:var(--aocp-primary);
  font-size:var(--aocp-size-title);
  font-weight:var(--aocp-weight-heading);
  margin-bottom:25px;
}

/* ------------------ Info grid ------------------ */
.aocp-info-grid{display:flex;gap:0;margin-bottom:30px;flex-wrap:wrap}
.aocp-info-item{display:flex;align-items:center;gap:10px;min-width:220px;flex:1}
.aocp-ico{font-size:22px;color:#005ae0}
.aocp-label{font-size:var(--aocp-size-small);color:var(--aocp-muted);font-weight:var(--aocp-weight-body)}
.aocp-val{font-size:var(--aocp-size-body);color:var(--aocp-ink-2);font-weight:var(--aocp-weight-strong)}

/* ------------------ Right ------------------ */
.aocp-right{flex:0 0 30%;display:flex;flex-direction:column;gap:30px}
.aocp-course-info{
  background:#fff;
  padding:25px;
  border-radius:12px;
  border:1px solid var(--aocp-border);
  box-shadow:0 0 10px rgba(0,0,0,.05);
}
.aocp-course-title{
  background:#EFF0FF;
  color:var(--aocp-primary);
  font-weight:var(--aocp-weight-heading);
  padding:12px 15px;
  border-radius:8px;
  font-size:var(--aocp-size-title);
  text-align:center;
  margin-bottom:25px;
}
.aocp-buy-btn{
  width:100%;
  padding:10px 12px;
  background:#1d0a71;
  color:#fff;
  font-weight:var(--aocp-weight-heading);
  border:none;
  border-radius:8px;
  cursor:pointer;
  font-size:var(--aocp-size-body);
  margin-top:15px;
  transition:background .3s ease, transform .06s ease;
}
.aocp-buy-btn:hover{background:#140a5a}
.aocp-buy-btn:active{transform:translateY(1px)}

.aocp-desc-scroll{max-height:220px;overflow-y:auto;padding-right:5px}
.aocp-desc-scroll::-webkit-scrollbar{width:0;background:transparent}
.aocp-material-box{
  background:#fff;
  padding:25px;
  border:1px solid var(--aocp-border);
  border-radius:12px;
  box-shadow:0 0 10px rgba(0,0,0,.05);
}
.aocp-material-box h4{
  font-size:var(--aocp-size-sub);
  font-weight:var(--aocp-weight-heading);
  color:#000;
  margin-bottom:12px;
  text-align:left;
}
.aocp-material-list{
  list-style:disc;
  text-align:left;
  padding-left:20px;
  color:#000;
  font-size:15px;
}
.aocp-material-list li{margin-bottom:8px}

/* ------------------ Tabs ------------------ */
.aocp-tabs{margin-top:40px}
.aocp-tab-buttons{display:flex;gap:15px;margin-bottom:25px;flex-wrap:wrap}
.aocp-tab-btn{
  border:2px solid var(--aocp-primary);
  background:transparent;
  color:var(--aocp-primary);
  font-weight:var(--aocp-weight-heading);
  font-size:var(--aocp-size-body);
  padding:8px 24px;
  border-radius:16px;
  cursor:pointer;
  transition:background .25s ease, color .25s ease, border-color .25s ease;
}
.aocp-tab-btn:hover{background:#eaeaff}
.aocp-tab-btn.active{
  background:var(--aocp-primary);
  color:#fff;
  border-color:var(--aocp-primary);
}

.aocp-tab-content h3,
.aocp-curriculum h3,
.aocp-instructors h3,
.aocp-reviews h3{
  font-size:var(--aocp-size-h);
  font-weight:var(--aocp-weight-heading);
  color:#000;
  text-align:left;
  margin-bottom:18px;
}
.aocp-tab-content p{
  font-size:var(--aocp-size-body);
  font-weight:var(--aocp-weight-body);
  color:#000;
  text-align:left;
  margin-bottom:18px;
}

/* ------------------ Curriculum ------------------ */
.aocp-curriculum{margin-top:40px}
.aocp-curriculum-item{
  border:1px solid #ddd;
  border-radius:10px;
  margin-bottom:15px;
  background:#fff;
  padding:15px 20px;
  cursor:pointer;
  transition:all .3s ease;
}
.aocp-curriculum-item:hover{background:#f9f9ff}
.aocp-curriculum-title{
  display:flex;
  justify-content:space-between;
  font-weight:var(--aocp-weight-heading);
  font-size:18px;
  color:var(--aocp-primary);
}
.aocp-curriculum-content{
  margin-top:10px;
  font-size:var(--aocp-size-body);
  font-weight:var(--aocp-weight-body);
  color:#000;
  text-align:left;
}
.aocp-arrow{font-size:18px;color:#2f2f2f}

/* ------------------ Instructors ------------------ */
.aocp-instructor-grid{display:flex;gap:20px;flex-wrap:wrap}
.aocp-instructor-card{
  flex:1 1 30%;
  border-radius:15px;
  overflow:hidden;
  background:#f0f2ff;
  box-shadow:0 0 8px rgba(0,0,0,.05);
  text-align:center;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
}
.aocp-instructor-img{background:#0c1a66;padding:20px}
.aocp-instructor-img img{width:100%;max-height:250px;object-fit:contain;border-radius:8px}
.aocp-instructor-info{
  padding:15px;
  background:#f0f2ff;
  font-size:var(--aocp-size-body);
  font-weight:var(--aocp-weight-strong);
  color:var(--aocp-ink);
  line-height:1.4;
  text-align:left;
}

/* ------------------ Reviews ------------------ */
.aocp-reviews{margin-top:40px}
.aocp-review-layout{display:flex;flex-direction:column;gap:30px}

.aocp-rating-summary{display:flex;align-items:flex-start;gap:20px}
.aocp-rating-score{font-size:40px;font-weight:var(--aocp-weight-heading);line-height:1}
.aocp-rating-stars{
  position:relative;
  display:inline-block;
  line-height:1;
  color:orange;
  font-size:18px;
  margin:5px 0;
}
.aocp-stars-outer{color:#ddd}
.aocp-stars-inner{
  position:absolute;
  top:0;left:0;
  width:var(--percent,0%);
  overflow:hidden;
  color:orange;
  white-space:nowrap;
  pointer-events:none;
}
.aocp-total-rating{font-size:var(--aocp-size-small);color:#555}

.aocp-rating-bars{flex:1}
.aocp-bar-line{display:flex;align-items:center;font-size:var(--aocp-size-small);margin-bottom:10px}
.aocp-bar-line .aocp-bar{
  flex:1;height:6px;background:#ddd;margin:0 10px;border-radius:5px;overflow:hidden
}
.aocp-bar-line .aocp-fill{background:var(--aocp-primary);height:100%}

.aocp-review-image-box{flex:0 0 55%;background:transparent;display:flex;align-items:center}
.aocp-review-image-box img{
  width:100%;
  max-width:600px;
  height:300px;
  border-radius:12px;
  object-fit:contain;
}

/* extra review images */
.aocp-reviews-gallery{display:flex;gap:16px;margin-top:18px;flex-wrap:wrap}
.aocp-reviews-gallery img{
  flex:1 1 calc(33.333% - 11px);
  max-width:calc(33.333% - 11px);
  height:240px;
  object-fit:contain;
  background:#fff;
  border:1px solid #e6e6e6;
  border-radius:12px;
  box-shadow:0 2px 10px rgba(0,0,0,.05);
  padding:8px;
}
@media (max-width:992px){
  .aocp-reviews-gallery img{
    flex-basis:calc(50% - 8px);
    max-width:calc(50% - 8px);
    height:180px;
  }
}

/* ------------------ Mobile ------------------ */
@media (max-width:768px){
  .row{flex-direction:column;gap:40px}
  .aocp-left{padding-left:0}
  .aocp-video iframe{height:250px}
}

backend/models/MockTestFeedback.js.content:
const mongoose = require('mongoose');

const MockTestFeedbackSchema = new mongoose.Schema({
  userId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true
  },
  attemptId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'MockTestAttempt',
    required: true
  },
  testId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'MockTest',
    required: true
  },
  studentName: {
    type: String,
    default: ''
  },
  studentEmail: {
    type: String,
    default: ''
  },
  responses: {
    q1_exam_support: {
      type: Number,
      min: 1,
      max: 4
    },
    q2_digital_exam_experience: {
      type: Number,
      min: 1,
      max: 4
    },
    q3_1_ease_of_locating: {
      type: Number,
      min: 1,
      max: 4
    },
    q3_2_finding_seat: {
      type: Number,
      min: 1,
      max: 4
    },
    q3_3_seating_arrangement: {
      type: Number,
      min: 1,
      max: 4
    },
    q3_4_basic_facilities: {
      type: Number,
      min: 1,
      max: 4
    },
    q3_5_exam_node_quality: {
      type: Number,
      min: 1,
      max: 4
    },
    q3_6_staff_behavior: {
      type: Number,
      min: 1,
      max: 4
    },
    q4_overall_experience: {
      type: String,
      default: ''
    }
  },
  averageRating: {
    type: Number,
    default: 0
  },
  submittedAt: {
    type: Date,
    default: Date.now
  }
}, { timestamps: true });

MockTestFeedbackSchema.pre('save', function(next) {
  const ratings = [];
  const r = this.responses;
  if (r.q1_exam_support) ratings.push(r.q1_exam_support);
  if (r.q2_digital_exam_experience) ratings.push(r.q2_digital_exam_experience);
  if (r.q3_1_ease_of_locating) ratings.push(r.q3_1_ease_of_locating);
  if (r.q3_2_finding_seat) ratings.push(r.q3_2_finding_seat);
  if (r.q3_3_seating_arrangement) ratings.push(r.q3_3_seating_arrangement);
  if (r.q3_4_basic_facilities) ratings.push(r.q3_4_basic_facilities);
  if (r.q3_5_exam_node_quality) ratings.push(r.q3_5_exam_node_quality);
  if (r.q3_6_staff_behavior) ratings.push(r.q3_6_staff_behavior);

  if (ratings.length > 0) {
    this.averageRating = ratings.reduce((a, b) => a + b, 0) / ratings.length;
  }
  next();
});

module.exports = mongoose.model('MockTestFeedback', MockTestFeedbackSchema);

