  align-items: flex-start;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 16px;
}
.um-header h1 { font-size: 28px; font-weight: 700; color: #1e293b; margin: 0 0 4px 0; }
.um-header p { color: #64748b; font-size: 14px; margin: 0; }
.um-header-actions { display: flex; gap: 10px; flex-wrap: wrap; }

.um-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border: none;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}
.um-btn:disabled { opacity: 0.6; cursor: not-allowed; }
.um-btn-primary { background: #3b82f6; color: #fff; }
.um-btn-primary:hover:not(:disabled) { background: #2563eb; }
.um-btn-enroll { background: #10b981; color: #fff; padding: 6px 14px; font-size: 13px; }
.um-btn-enroll:hover { background: #059669; }
.um-btn-cancel { background: #e2e8f0; color: #475569; }
.um-btn-cancel:hover { background: #cbd5e1; }
.um-btn-outline { background: transparent; border: 2px solid #3b82f6; color: #3b82f6; }
.um-btn-outline:hover { background: #eff6ff; }
.um-btn-danger { background: #ef4444; color: #fff; }
.um-btn-danger:hover { background: #dc2626; }
.um-btn-success { background: #10b981; color: #fff; }
