.um-loading { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 300px; gap: 16px; }
.um-spinner { width: 40px; height: 40px; border: 3px solid #e2e8f0; border-top-color: #3b82f6; border-radius: 50%; animation: spin 0.8s linear infinite; }
