.um-clickable { cursor: pointer; }
.um-clickable:hover { color: #3b82f6; text-decoration: underline; }
.um-empty { text-align: center; color: #94a3b8; padding: 40px 16px !important; }

.um-row-banned { background: #fef2f2 !important; }
.um-banned-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  color: #fff;
  background: #ef4444;
  padding: 2px 6px;
  border-radius: 4px;
  margin-left: 8px;
  vertical-align: middle;
}

.um-verification-badges { display: flex; gap: 4px; flex-wrap: wrap; }
.um-v-badge {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 12px;
  font-weight: 500;
}
.um-v-badge.verified { background: #dcfce7; color: #166534; }
.um-v-badge.unverified { background: #fef9c3; color: #854d0e; }

.um-enrolled-list { display: flex; flex-wrap: wrap; gap: 6px; }
.um-course-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  background: #dbeafe;
  color: #1e40af;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
}
.um-badge-remove {
  background: none;
  border: none;
  color: #ef4444;
