.um-no-courses { color: #94a3b8; font-size: 13px; font-style: italic; }

.um-action-btns { display: flex; gap: 6px; }
.um-icon-btn {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 14px;
  transition: all 0.2s;
}
.um-icon-view { background: #eff6ff; color: #3b82f6; }
.um-icon-view:hover { background: #dbeafe; }
.um-icon-enroll { background: #ecfdf5; color: #10b981; }
.um-icon-enroll:hover { background: #d1fae5; }
.um-icon-edit { background: #fef9c3; color: #ca8a04; }
.um-icon-edit:hover { background: #fef08a; }
.um-icon-ban { background: #fee2e2; color: #ef4444; }
.um-icon-ban:hover { background: #fecaca; }
.um-icon-unban { background: #dcfce7; color: #16a34a; }
.um-icon-unban:hover { background: #bbf7d0; }
.um-icon-delete { background: #fee2e2; color: #dc2626; }
.um-icon-delete:hover { background: #fecaca; }
.um-icon-approve { background: #dcfce7; color: #16a34a; }
.um-icon-approve:hover { background: #bbf7d0; }
.um-icon-reject { background: #fee2e2; color: #dc2626; }
.um-icon-reject:hover { background: #fecaca; }
.um-icon-green { color: #16a34a; font-size: 16px; }
.um-icon-red { color: #ef4444; font-size: 16px; }

.um-amount { font-weight: 600; color: #1e293b; }

.um-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
